let _abcjs: any = null;
function getAbcjs(): any {
  if (!_abcjs) {
    const loaded = require('abcjs');
    _abcjs = loaded.default ?? loaded;
  }
  return _abcjs;
}

function formatTime(seconds: number): string {
  if (isNaN(seconds) || seconds < 0) return '0:00';
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

function createSvgIcon(
  attrs: Record<string, string>,
  children: Array<{ tag: string; attrs: Record<string, string> }>
): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('xmlns', SVG_NS);
  for (const [k, v] of Object.entries(attrs)) {
    svg.setAttribute(k, v);
  }
  for (const child of children) {
    const el = document.createElementNS(SVG_NS, child.tag);
    for (const [k, v] of Object.entries(child.attrs)) {
      el.setAttribute(k, v);
    }
    svg.appendChild(el);
  }
  return svg;
}

function createPlayIcon(): SVGSVGElement {
  return createSvgIcon(
    { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'currentColor', stroke: 'none' },
    [{ tag: 'polygon', attrs: { points: '6 3 20 12 6 21 6 3' } }]
  );
}

function createPauseIcon(): SVGSVGElement {
  return createSvgIcon(
    { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'currentColor', stroke: 'none' },
    [
      { tag: 'rect', attrs: { x: '6', y: '4', width: '4', height: '16' } },
      { tag: 'rect', attrs: { x: '14', y: '4', width: '4', height: '16' } },
    ]
  );
}

function createStopIcon(): SVGSVGElement {
  return createSvgIcon(
    { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'currentColor', stroke: 'none' },
    [{ tag: 'rect', attrs: { x: '5', y: '5', width: '14', height: '14', rx: '2' } }]
  );
}

function createRestartIcon(): SVGSVGElement {
  return createSvgIcon(
    { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': '2', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' },
    [
      { tag: 'path', attrs: { d: 'M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8' } },
      { tag: 'path', attrs: { d: 'M3 3v5h5' } },
    ]
  );
}

function createDownloadIcon(): SVGSVGElement {
  return createSvgIcon(
    { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': '2', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' },
    [
      { tag: 'path', attrs: { d: 'M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4' } },
      { tag: 'polyline', attrs: { points: '7 10 12 15 17 10' } },
      { tag: 'line', attrs: { x1: '12', x2: '12', y1: '15', y2: '3' } },
    ]
  );
}

function setButtonIcon(btn: HTMLElement, iconEl: Node): void {
  btn.replaceChildren(iconEl);
}

export function renderAbcBlock(source: string, container: HTMLElement): void {
  const abcjs = getAbcjs();
  const wrapper = createDiv();
  wrapper.className = 'abcjs-wrapper';

  const sheetContainer = createDiv();
  sheetContainer.className = 'abcjs-sheet-container';

  let visualObj: any = null;
  try {
    const renderResult = abcjs.renderAbc(sheetContainer, source.trim(), {
      responsive: 'resize',
      add_classes: true,
    });
    if (renderResult && renderResult.length > 0) {
      visualObj = renderResult[0];
    }
  } catch (err) {
    const errDiv = createDiv();
    errDiv.className = 'chart-error';
    errDiv.textContent = `ABC Render Error: ${err}`;
    container.appendChild(errDiv);
    return;
  }

  wrapper.appendChild(sheetContainer);

  // Audio Context and Synth Controller state
  let synthController: any = null;
  let audioContext: AudioContext | null = null;
  let playbackState: 'idle' | 'loading' | 'playing' | 'paused' = 'idle';
  let totalDuration = 0;
  let animId: number | null = null;
  let highlightedElements: SVGElement[] = [];

  const clearHighlights = () => {
    highlightedElements.forEach((el) => {
      try {
        el.classList.remove('abcjs-highlight');
      } catch {
        // ignore
      }
    });
    highlightedElements = [];
  };

  const stopPlayback = () => {
    if (synthController) {
      try {
        synthController.pause();
        synthController.isStarted = false;
        synthController.restart();
      } catch {
        // ignore
      }
    }
    clearHighlights();
    playbackState = 'idle';
    updateControlsUI();
    if (animId) {
      window.cancelAnimationFrame(animId);
      animId = null;
    }
  };

  const controlsBar = createDiv();
  controlsBar.className = 'abcjs-controls-bar';

  // Left controls group (Play / Stop / Restart)
  const leftBtns = createDiv();
  leftBtns.className = 'abcjs-left-controls';

  // Play / Pause Button
  const playPauseBtn = createEl('button');
  playPauseBtn.className = 'abcjs-btn abcjs-play-btn';
  playPauseBtn.title = 'Play';
  setButtonIcon(playPauseBtn, createPlayIcon());

  // Stop Button
  const stopBtn = createEl('button');
  stopBtn.className = 'abcjs-btn abcjs-stop-btn';
  stopBtn.title = 'Stop';
  setButtonIcon(stopBtn, createStopIcon());
  stopBtn.disabled = true;

  // Restart Button
  const restartBtn = createEl('button');
  restartBtn.className = 'abcjs-btn abcjs-restart-btn';
  restartBtn.title = 'Start from beginning';
  setButtonIcon(restartBtn, createRestartIcon());
  restartBtn.disabled = true;

  leftBtns.appendChild(playPauseBtn);
  leftBtns.appendChild(stopBtn);
  leftBtns.appendChild(restartBtn);

  // Progress container group (Time Label / Progress Slider / Duration Label)
  const progressContainer = createDiv();
  progressContainer.className = 'abcjs-progress-container';

  // Current Time Label
  const currentTimeEl = createSpan();
  currentTimeEl.className = 'abcjs-time-label';
  currentTimeEl.textContent = '0:00';

  // Progress Bar
  const progressSlider = createEl('input');
  progressSlider.type = 'range';
  progressSlider.className = 'abcjs-progress-slider';
  progressSlider.min = '0';
  progressSlider.max = '100';
  progressSlider.step = '0.1';
  progressSlider.value = '0';
  progressSlider.disabled = true;

  // Duration Label
  const durationEl = createSpan();
  durationEl.className = 'abcjs-time-label';
  durationEl.textContent = '0:00';

  progressContainer.appendChild(currentTimeEl);
  progressContainer.appendChild(progressSlider);
  progressContainer.appendChild(durationEl);

  // Right side buttons container
  const rightBtns = createDiv();
  rightBtns.className = 'abcjs-right-controls';

  // MIDI Download Button
  const downloadBtn = createEl('button');
  downloadBtn.className = 'abcjs-btn abcjs-download-btn';
  downloadBtn.title = 'Download MIDI';
  setButtonIcon(downloadBtn, createDownloadIcon());

  downloadBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    try {
      const midiData = abcjs.synth.getMidiFile(source.trim(), { midiOutputType: 'encoded' });
      if (!midiData) return;
      const dataUrl = Array.isArray(midiData) ? midiData[0] : midiData;
      const a = createEl('a');
      a.href = dataUrl;
      a.download = 'sheet-music.midi';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch (err) {
      console.error('MIDI export failed', err);
    }
  });

  rightBtns.appendChild(downloadBtn);

  controlsBar.appendChild(leftBtns);
  controlsBar.appendChild(progressContainer);
  controlsBar.appendChild(rightBtns);

  wrapper.appendChild(controlsBar);
  container.appendChild(wrapper);

  function updateControlsUI() {
    if (playbackState === 'playing') {
      setButtonIcon(playPauseBtn, createPauseIcon());
      playPauseBtn.title = 'Pause';
      stopBtn.disabled = false;
      restartBtn.disabled = false;
      progressSlider.disabled = false;
    } else if (playbackState === 'paused') {
      setButtonIcon(playPauseBtn, createPlayIcon());
      playPauseBtn.title = 'Play';
      stopBtn.disabled = false;
      restartBtn.disabled = false;
      progressSlider.disabled = false;
    } else if (playbackState === 'loading') {
      setButtonIcon(playPauseBtn, createPlayIcon());
      playPauseBtn.title = 'Loading...';
      stopBtn.disabled = true;
      restartBtn.disabled = true;
      progressSlider.disabled = true;
    } else {
      setButtonIcon(playPauseBtn, createPlayIcon());
      playPauseBtn.title = 'Play';
      stopBtn.disabled = true;
      restartBtn.disabled = true;
      progressSlider.disabled = true;
      progressSlider.value = '0';
      currentTimeEl.textContent = '0:00';
    }
  }

  const syncProgress = () => {
    if (synthController && synthController.midiBuffer) {
      totalDuration = synthController.midiBuffer.duration || totalDuration || 0;
      if (totalDuration > 0) {
        progressSlider.max = totalDuration.toString();
        durationEl.textContent = formatTime(totalDuration);
      }
      const pct = synthController.percent || 0;
      const curTime = pct * totalDuration;
      currentTimeEl.textContent = formatTime(curTime);
      progressSlider.value = curTime.toString();
    }
    if (playbackState === 'playing') {
      animId = window.requestAnimationFrame(syncProgress);
    }
  };

  const initSynth = async (): Promise<any> => {
    if (synthController) return synthController;

    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioCtx) return null;

    if (!audioContext || audioContext.state === 'closed') {
      audioContext = new AudioCtx();
    }
    if (audioContext.state === 'suspended') {
      await audioContext.resume();
    }

    if (abcjs.synth.registerAudioContext) {
      abcjs.synth.registerAudioContext(audioContext);
    }

    const sc: any = new abcjs.synth.SynthController();

    const cursorControl = {
      onStart: () => {
        clearHighlights();
      },
      onEvent: (ev: any) => {
        clearHighlights();
        if (ev && ev.elements) {
          ev.elements.forEach((group: any[]) => {
            if (Array.isArray(group)) {
              group.forEach((el: SVGElement) => {
                if (el && el.classList) {
                  el.classList.add('abcjs-highlight');
                  highlightedElements.push(el);
                }
              });
            }
          });
        }
      },
      onFinished: () => {
        clearHighlights();
        playbackState = 'idle';
        updateControlsUI();
        if (animId) window.cancelAnimationFrame(animId);
      },
    };

    sc.cursorControl = cursorControl;

    await sc.setTune(visualObj, false, {});

    synthController = sc;
    totalDuration = sc.midiBuffer?.duration || 0;
    if (totalDuration > 0) {
      durationEl.textContent = formatTime(totalDuration);
      progressSlider.max = totalDuration.toString();
    }
    return sc;
  };

  playPauseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!visualObj) return;

    if (playbackState === 'playing') {
      if (synthController) {
        synthController.pause();
        synthController.isStarted = false;
      }
      playbackState = 'paused';
      updateControlsUI();
      if (animId) window.cancelAnimationFrame(animId);
      return;
    }

    if (playbackState === 'paused' && synthController) {
      playbackState = 'playing';
      updateControlsUI();
      synthController.play();
      animId = window.requestAnimationFrame(syncProgress);
      return;
    }

    // Idle: Initialize and play
    playbackState = 'loading';
    updateControlsUI();
    void (async () => {
      try {
        const sc = await initSynth();
        if (!sc) {
          playbackState = 'idle';
          updateControlsUI();
          return;
        }
        playbackState = 'playing';
        updateControlsUI();
        await sc.play();
        totalDuration = sc.midiBuffer?.duration || totalDuration;
        durationEl.textContent = formatTime(totalDuration);
        progressSlider.max = totalDuration.toString();
        animId = window.requestAnimationFrame(syncProgress);
      } catch (err) {
        console.error('AbcJS playback error:', err);
        stopPlayback();
      }
    })();
  });

  stopBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    stopPlayback();
  });

  restartBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    clearHighlights();
    if (synthController) {
      synthController.seek(0);
      currentTimeEl.textContent = '0:00';
      progressSlider.value = '0';
      if (playbackState !== 'playing') {
        playbackState = 'playing';
        updateControlsUI();
        synthController.play();
        animId = window.requestAnimationFrame(syncProgress);
      }
    }
  });

  progressSlider.addEventListener('input', () => {
    const val = parseFloat(progressSlider.value);
    currentTimeEl.textContent = formatTime(val);
    if (synthController && totalDuration > 0) {
      clearHighlights();
      synthController.seek(val / totalDuration);
    }
  });
}

import type * as Plot from '@observablehq/plot';
import { generateInnerColors } from 'src/util';
import { renderPieChart } from './pieRenderer';
import { renderRadarChart } from './radarRenderer';
import { renderSankeyChart } from './sankeyRenderer';
import { buildScatterPlotOptions, extractScatterData } from './scatterRenderer';
import {
  isLogScale,
  extractMarkLines,
  buildPlotMarkLines,
  resolveAxisConfig,
  resolveFillConfig,
  resolveLabelConfig,
} from './chartConfig';
import { getPlot, getD3 } from './plotInstance';

export interface PreparedChart {
  plotOptions: Plot.PlotOptions | null;
  customElement?: HTMLElement | SVGElement;
  width?: string;
}

const ISO_DATE_REGEX = /^\d{4}[-/]\d{1,2}(?:[-/]\d{1,2})?(?:[T ].*)?$/;
const DIGITS_ONLY_REGEX = /^\d+$/;
const HAS_DIGIT_REGEX = /\d/;

export function tryParseDate(v: any): any {
  if (v instanceof Date) return isNaN(v.getTime()) ? v : v;
  if (typeof v === 'string') {
    const s = v.trim();
    // Guard regex tests with delimiter check to fast-path standard strings without dashes or slashes
    if ((s.includes('-') || s.includes('/')) && ISO_DATE_REGEX.test(s)) {
      const d = new Date(s.includes('/') ? s.replace(/\//g, '-') : s);
      if (!isNaN(d.getTime())) return d;
    }
    // Also support standard date strings (e.g. from toString or ISO formatted dates).
    // Performance optimization: Guard Date.parse(s) with HAS_DIGIT_REGEX. Any valid date format
    // (ISO, RFC2822, "12 May 2023", etc.) must contain at least one digit. Skipping Date.parse()
    // on long categorical non-date text strings (e.g. "United States of America") provides a ~4.7x speedup.
    if (s.length >= 10 && HAS_DIGIT_REGEX.test(s) && !DIGITS_ONLY_REGEX.test(s)) {
      const parsed = Date.parse(s);
      if (!isNaN(parsed)) {
        const d = new Date(parsed);
        if (!isNaN(d.getTime())) return d;
      }
    }
  }
  return v;
}

export function prepareChartDataset(
  yaml: any,
  el: HTMLElement,
  settings: { themeable: boolean; colors: string[] },
  themeColors = false
): PreparedChart {
  if (!yaml || typeof yaml !== 'object') {
    return { plotOptions: null, width: '100%' };
  }

  const computedStyle = getComputedStyle(el);

  const colors: string[] = [];
  if (settings.themeable || themeColors) {
    let i = 1;
    while (true) {
      const color = computedStyle.getPropertyValue(`--chart-color-${i}`);
      if (color) {
        colors.push(color.trim());
        i++;
      } else {
        break;
      }
    }
  }
  const baseColors = colors.length
    ? colors
    : settings.colors.map((c) => c.trim());

  const transparency = yaml.transparency ?? 0.25;
  const innerColors = generateInnerColors(baseColors, transparency);

  const rawLabels = yaml.labels;
  const labels: any[] = Array.isArray(rawLabels) ? rawLabels : [];
  const rawSeries: any[] = yaml.series ?? [];

  // Performance optimization: Pre-allocate parsedLabels and track hasDateLabels in a single pass.
  // This avoids redundant tryParseDate calls and eliminates subsequent labels.some() and labels.every() passes.
  const numLabels = labels.length;
  const parsedLabels = new Array(numLabels);
  let hasDateLabels = false;

  for (let idx = 0; idx < numLabels; idx++) {
    const parsed = tryParseDate(labels[idx]);
    parsedLabels[idx] = parsed;
    if (!hasDateLabels && parsed instanceof Date) {
      hasDateLabels = true;
    }
  }

  // Performance optimization: Pre-allocate dataPoints array capacity using total series count
  // and assign by index directly instead of dataPoints.push() to eliminate array buffer reallocations.
  let totalPoints = 0;
  for (let i = 0; i < rawSeries.length; i++) {
    const sData = rawSeries[i]?.data;
    if (Array.isArray(sData)) {
      totalPoints += sData.length;
    }
  }

  const dataPoints: Array<{
    x: any;
    y: number;
    series: string;
    index: number;
    seriesIndex: number;
  }> = new Array(totalPoints);
  let dpIdx = 0;

  for (let i = 0; i < rawSeries.length; i++) {
    const s = rawSeries[i];
    const seriesTitle = s.title ?? `Series ${i + 1}`;
    const seriesData = s.data ?? [];
    const sLen = seriesData.length;
    for (let j = 0; j < sLen; j++) {
      // Since parsedLabels[j] was already parsed during the label pre-pass, avoid redundant tryParseDate calls
      const xVal = j < numLabels ? parsedLabels[j] : j;
      const val = seriesData[j];
      const numVal = typeof val === 'number' ? val : Number(val);
      const yVal = isNaN(numVal) ? 0 : numVal;
      dataPoints[dpIdx++] = {
        x: xVal,
        y: yVal,
        series: seriesTitle,
        index: j,
        seriesIndex: i,
      };
    }
  }

  const type = String(yaml.type ?? 'bar').trim().toLowerCase();
  const gridColor =
    computedStyle.getPropertyValue('--background-modifier-border') ||
    '#e0e0e0';
  const textColor =
    yaml.textColor ||
    computedStyle.getPropertyValue('--text-muted') ||
    'currentColor';

  const widthStr = yaml.width ? String(yaml.width) : '100%';

  // Custom SVG rendering for Pie / Doughnut / Donut
  if (type === 'pie' || type === 'doughnut' || type === 'donut') {
    return renderPieChart(yaml, dataPoints, labels, baseColors, gridColor, textColor, widthStr, getD3);
  }

  // Custom SVG rendering for Radar / PolarArea
  if (type === 'radar' || type === 'polararea' || type === 'polar_area') {
    return renderRadarChart(yaml, dataPoints, labels, baseColors, innerColors, gridColor, textColor, widthStr, getD3);
  }

  // Custom SVG rendering for Sankey
  if (type === 'sankey') {
    return renderSankeyChart(yaml, rawSeries, baseColors, textColor, widthStr);
  }

  const isScatter = ['scatter', 'point', 'points', 'scatterplot'].includes(type);
  if (isScatter) {
    const PlotInst = getPlot();
    const scatterPoints = extractScatterData(yaml, labels);
    const plotOptions = buildScatterPlotOptions(
      yaml,
      scatterPoints,
      baseColors,
      gridColor,
      textColor,
      PlotInst
    );
    return { plotOptions, width: widthStr };
  }

  // Standard Plot marks for Bar and Line charts with interactivity (tip: true)
  const marks: any[] = [];
  const isHorizontal = yaml.indexAxis === 'y';
  const isStacked = yaml.stacked === true;
  const curve = yaml.tension ? 'catmull-rom' : 'linear';

  const PlotInst = getPlot();

  // Unified fills and opacity resolution
  const fillConfig = resolveFillConfig(yaml, false);
  const resolvedFillOpacity = fillConfig.fillOpacity;

  // Unified scale resolution (log vs linear)
  const isXLog = isLogScale(yaml, 'x');
  const isYLog = isLogScale(yaml, 'y');

  // Unified label / dataLabels resolution
  const labelConfig = resolveLabelConfig(yaml);

  // If grid is enabled, standard rules
  if (isXLog || isYLog) {
    marks.push(
      PlotInst.gridX({ stroke: gridColor, strokeDasharray: '2,2' }),
      PlotInst.gridY({ stroke: gridColor, strokeDasharray: '2,2' })
    );
  }

  if (type === 'line') {
    // Sort data points monotonically along x for each series to ensure timeseries and continuous plots
    // connect sequentially without criss-crossing or random line jumps.
    const sortedLineData = [...dataPoints].sort((a, b) => {
      if (a.seriesIndex !== b.seriesIndex) return a.seriesIndex - b.seriesIndex;
      const ax = a.x instanceof Date ? a.x.getTime() : typeof a.x === 'number' ? a.x : null;
      const bx = b.x instanceof Date ? b.x.getTime() : typeof b.x === 'number' ? b.x : null;
      if (ax !== null && bx !== null) {
        return ax - bx;
      }
      return a.index - b.index;
    });

    if (fillConfig.fill) {
      marks.push(
        PlotInst.areaY(sortedLineData, {
          x: 'x',
          y: 'y',
          fill: typeof fillConfig.fill === 'string' ? fillConfig.fill : 'series',
          fillOpacity: resolvedFillOpacity,
          curve,
        })
      );
    }
    marks.push(
      PlotInst.lineY(sortedLineData, {
        x: 'x',
        y: 'y',
        stroke: 'series',
        curve,
        strokeWidth: 1.5,
      })
    );
    // Resolve line dot radius and visibility. For dense series (> 30 data points),
    // default radius to 0 (or micro-dot) so dense points do not cluster into an unreadable mess,
    // while preserving tooltip interactivity. Allow explicit user control via pointRadius / radius / r / points / dots.
    let pointRadius = 4;
    if (yaml.pointRadius !== undefined) {
      pointRadius = Number(yaml.pointRadius);
    } else if (yaml.radius !== undefined) {
      pointRadius = Number(yaml.radius);
    } else if (yaml.r !== undefined) {
      pointRadius = Number(yaml.r);
    } else if (yaml.points === false || yaml.dots === false) {
      pointRadius = 0;
    } else if (sortedLineData.length > 30) {
      pointRadius = 0;
    }

    marks.push(
      PlotInst.dot(sortedLineData, {
        x: 'x',
        y: 'y',
        fill: 'series',
        stroke: pointRadius === 0 ? 'none' : 'white',
        strokeWidth: pointRadius === 0 ? 0 : 0.75,
        r: pointRadius,
        tip: true,
        title: (d: any) => `${d.series}\n${d.x instanceof Date ? d.x.toISOString().slice(0, 10) : d.x}: ${d.y}`,
      })
    );

    // Data labels on line chart points if configured
    if (labelConfig.showLabels) {
      const labeledData = labelConfig.filterSet
        ? dataPoints.filter((d) => labelConfig.filterSet!.has(String(d.x).toLowerCase()) || labelConfig.filterSet!.has(String(d.series).toLowerCase()))
        : dataPoints;
      marks.push(
        PlotInst.text(labeledData, {
          x: 'x',
          y: 'y',
          text: (d: any) => `${d.y}`,
          dy: -10,
          fontSize: labelConfig.fontSize,
        })
      );
    }
  } else {
    // Default / Bar
    if (isHorizontal) {
      const isMultiSeries = rawSeries.length > 1;
      if (isStacked || !isMultiSeries) {
        marks.push(
          PlotInst.barX(dataPoints, {
            x: 'y',
            y: 'x',
            fill: 'series',
            fillOpacity: yaml.fillOpacity ?? (yaml.transparency !== undefined ? yaml.transparency : 1),
            tip: true,
            title: (d: any) => `${d.series}\n${d.x}: ${d.y}`,
          })
        );
      } else {
        marks.push(
          PlotInst.barX(dataPoints, {
            y: 'series',
            x: 'y',
            fy: 'x',
            fill: 'series',
            fillOpacity: yaml.fillOpacity ?? (yaml.transparency !== undefined ? yaml.transparency : 1),
            tip: true,
            title: (d: any) => `${d.series}\n${d.x}: ${d.y}`,
          })
        );
      }

      // Data labels for horizontal bar
      if (labelConfig.showLabels) {
        const labeledData = labelConfig.filterSet
          ? dataPoints.filter((d) => labelConfig.filterSet!.has(String(d.x).toLowerCase()) || labelConfig.filterSet!.has(String(d.series).toLowerCase()))
          : dataPoints;
        marks.push(
          PlotInst.text(labeledData, {
            x: 'y',
            y: isStacked || !isMultiSeries ? 'x' : 'series',
            ...(isStacked || !isMultiSeries ? {} : { fy: 'x' }),
            text: (d: any) => `${d.y}`,
            dx: 8,
            frameAnchor: 'left',
            fontSize: labelConfig.fontSize,
          })
        );
      }
    } else {
      const isMultiSeries = rawSeries.length > 1;
      if (isStacked || !isMultiSeries) {
        marks.push(
          PlotInst.barY(dataPoints, {
            x: 'x',
            y: 'y',
            fill: 'series',
            fillOpacity: yaml.fillOpacity ?? (yaml.transparency !== undefined ? yaml.transparency : 1),
            tip: true,
            title: (d: any) => `${d.series}\n${d.x}: ${d.y}`,
          })
        );
      } else {
        marks.push(
          PlotInst.barY(dataPoints, {
            x: 'series',
            y: 'y',
            fx: 'x',
            fill: 'series',
            fillOpacity: yaml.fillOpacity ?? (yaml.transparency !== undefined ? yaml.transparency : 1),
            tip: true,
            title: (d: any) => `${d.series}\n${d.x}: ${d.y}`,
          })
        );
      }

      // Data labels for vertical bar
      if (labelConfig.showLabels) {
        const labeledData = labelConfig.filterSet
          ? dataPoints.filter((d) => labelConfig.filterSet!.has(String(d.x).toLowerCase()) || labelConfig.filterSet!.has(String(d.series).toLowerCase()))
          : dataPoints;
        marks.push(
          PlotInst.text(labeledData, {
            x: isStacked || !isMultiSeries ? 'x' : 'series',
            y: 'y',
            ...(isStacked || !isMultiSeries ? {} : { fx: 'x' }),
            text: (d: any) => `${d.y}`,
            dy: -8,
            frameAnchor: 'bottom',
            fontSize: labelConfig.fontSize,
          })
        );
      }
    }
  }

  // Unified Mark lines (reference rules) for Bar and Line charts
  const markLineConfigs = extractMarkLines(yaml);
  if (markLineConfigs.length > 0) {
    marks.push(...buildPlotMarkLines(markLineConfigs, PlotInst));
  }

  // Legend
  const colorScale: Plot.ScaleOptions = {
    legend: yaml.legend !== false && yaml.options?.legend !== false,
    range: baseColors,
  };

  // Unified axis configurations
  const xResolved = resolveAxisConfig(yaml, 'x');
  const yResolved = resolveAxisConfig(yaml, 'y');

  // Auto-adaptive tick calculation based on width to prevent overcrowded tick labels
  let defaultXTicks: any;
  const explicitXTicks = yaml.xTicks ?? yaml.ticks ?? yaml.x?.ticks ?? yaml.scales?.x?.ticks;

  if (explicitXTicks !== undefined) {
    defaultXTicks = explicitXTicks;
  } else {
    // Estimate target pixel width
    let estWidth = 640;
    if (typeof yaml.width === 'number') {
      estWidth = yaml.width;
    } else if (typeof yaml.width === 'string') {
      const pxMatch = yaml.width.match(/^(\d+(?:\.\d+)?)px$/);
      if (pxMatch) {
        estWidth = parseFloat(pxMatch[1]);
      } else {
        const pctMatch = yaml.width.match(/^(\d+(?:\.\d+)?)%$/);
        if (pctMatch) {
          estWidth = Math.round((parseFloat(pctMatch[1]) / 100) * 700);
        }
      }
    }

    const targetTickCount = Math.max(3, Math.min(12, Math.round(estWidth / 80)));

    // If x represents discrete string labels and they are dense, downsample ticks adaptively.
    // For horizontal charts (indexAxis === 'y'), x is the numeric value axis, so keep targetTickCount.
    // Performance optimization: hasDateLabels was already determined during the initial label pass,
    // avoiding redundant tryParseDate re-evaluations across every label element.
    if (!isHorizontal && labels.length > targetTickCount && !hasDateLabels && labels.every((l) => typeof l === 'string')) {
      const step = Math.ceil(labels.length / targetTickCount);
      defaultXTicks = labels.filter((_, idx) => idx % step === 0);
    } else if (!hasDateLabels && !isHorizontal && labels.length > 0) {
      // For non-dense discrete labels, pass all labels to ticks or undefined so all labels display
      defaultXTicks = undefined;
    } else {
      defaultXTicks = targetTickCount;
    }
  }

  // Preserve discrete category ordering from labels on categorical axis
  const isGroupedBar = type === 'bar' && !isStacked && rawSeries.length > 1;

  let resolvedXDomain = xResolved.domain;
  let resolvedYDomain = yResolved.domain;
  let resolvedFxDomain: any = undefined;
  let resolvedFyDomain: any = undefined;

  if (!isHorizontal) {
    if (isGroupedBar) {
      if (labels.length > 0 && !hasDateLabels) {
        resolvedFxDomain = parsedLabels;
      }
    } else if (!resolvedXDomain && labels.length > 0 && !hasDateLabels) {
      resolvedXDomain = parsedLabels;
    }
  } else {
    if (isGroupedBar) {
      if (labels.length > 0 && !hasDateLabels) {
        resolvedFyDomain = parsedLabels;
      }
    } else if (!resolvedYDomain && labels.length > 0 && !hasDateLabels) {
      resolvedYDomain = parsedLabels;
    }
  }

  const xOptions: Plot.ScaleOptions = {
    type: isXLog ? 'log' : undefined,
    label: xResolved.label,
    domain: resolvedXDomain,
    reverse: xResolved.reverse,
    ticks: defaultXTicks,
    axis: yaml.xDisplay === false || xResolved.axis === null ? null : undefined,
  };

  const yOptions: Plot.ScaleOptions = {
    type: isYLog ? 'log' : undefined,
    label: yResolved.label,
    domain: resolvedYDomain,
    reverse: yResolved.reverse,
    zero: yaml.beginAtZero !== undefined ? yaml.beginAtZero : !isYLog,
    axis: yaml.yDisplay === false || yResolved.axis === null ? null : undefined,
  };

  const fxOptions: Plot.ScaleOptions | undefined = resolvedFxDomain
    ? { domain: resolvedFxDomain }
    : undefined;

  const fyOptions: Plot.ScaleOptions | undefined = resolvedFyDomain
    ? { domain: resolvedFyDomain }
    : undefined;

  const plotOptions: Plot.PlotOptions = {
    title: yaml.title ?? yaml.chartTitle ?? undefined,
    subtitle: yaml.subtitle ?? undefined,
    caption: yaml.caption ?? undefined,
    style: {
      background: 'transparent',
      color: textColor,
    },
    grid: yaml.grid ?? true,
    x: xOptions,
    y: yOptions,
    ...(fxOptions ? { fx: fxOptions } : {}),
    ...(fyOptions ? { fy: fyOptions } : {}),
    color: colorScale,
    marks,
  };

  return { plotOptions, width: widthStr };
}

export interface MarkLineConfig {
  x?: number | string;
  y?: number | string;
  value?: number | string;
  axis?: 'x' | 'y' | 'xAxis' | 'yAxis' | (string & {});
  label?: string;
  title?: string;
  text?: string;
  color?: string;
  stroke?: string;
  style?: 'solid' | 'dashed' | 'dotted' | (string & {});
  strokeDasharray?: string;
  strokeWidth?: number;
  width?: number;
}

export interface TrendlineConfig {
  enabled?: boolean;
  stroke?: string;
  strokeWidth?: number;
  strokeDasharray?: string;
  ci?: number | boolean | null;
  fill?: string | boolean | null;
}

export interface CommonChartConfig {
  title?: string;
  subtitle?: string;
  caption?: string;
  legend: boolean;
  isXLog: boolean;
  isYLog: boolean;
  xLabel: string | null;
  yLabel: string | null;
  xDomain?: any[];
  yDomain?: any[];
  xReverse?: boolean;
  yReverse?: boolean;
  xDisplay?: boolean;
  yDisplay?: boolean;
  beginAtZero?: boolean;
  grid: boolean;
  xGrid?: boolean;
  yGrid?: boolean;
  fill: boolean | string;
  fillOpacity: number;
  markLines: MarkLineConfig[];
  trendline?: TrendlineConfig | boolean;
  showLabels?: boolean | string[] | string;
  labelFontSize?: number;
}

/**
 * Standardizes log scale detection across all chart types and DSL permutations:
 * - xLog / yLog (boolean)
 * - xScale: 'log' | 'logarithmic'
 * - xType / x.type / scales.x.type / options.scales.x.type: 'log' | 'logarithmic'
 */
export function isLogScale(yaml: any, axis: 'x' | 'y'): boolean {
  if (!yaml || typeof yaml !== 'object') return false;
  const a = axis;

  return Boolean(
    yaml[`${a}Log`] ||
    yaml[`${a}Scale`] === 'log' ||
    yaml[`${a}Scale`] === 'logarithmic' ||
    yaml[`${a}Type`] === 'log' ||
    yaml[`${a}Type`] === 'logarithmic' ||
    yaml[a]?.type === 'log' ||
    yaml[a]?.type === 'logarithmic' ||
    yaml[a]?.scale === 'log' ||
    yaml[a]?.scale === 'logarithmic' ||
    yaml[`${a}Axis`]?.type === 'log' ||
    yaml[`${a}Axis`]?.type === 'logarithmic' ||
    yaml.scales?.[a]?.type === 'log' ||
    yaml.scales?.[a]?.type === 'logarithmic' ||
    yaml.options?.scales?.[a]?.type === 'log' ||
    yaml.options?.scales?.[a]?.type === 'logarithmic' ||
    yaml.options?.[`${a}Log`] ||
    yaml.options?.[`${a}Scale`] === 'log'
  );
}

/**
 * Extracts mark line configurations supported universally across chart DSLs:
 * - markLine / markLines / markline / marklines / marks
 * - options.markLine / options.markLines
 */
export function extractMarkLines(yaml: any): MarkLineConfig[] {
  if (!yaml || typeof yaml !== 'object') return [];
  const raw =
    yaml.markLine ||
    yaml.markLines ||
    yaml.markline ||
    yaml.marklines ||
    yaml.marks ||
    yaml.options?.markLine ||
    yaml.options?.markLines;

  if (!raw) return [];
  const list = Array.isArray(raw) ? raw : [raw];
  const results: MarkLineConfig[] = [];

  for (const item of list) {
    if (item && typeof item === 'object') {
      results.push(item);
    }
  }
  return results;
}

/**
 * Parses and builds Plot markLine rule and label marks.
 * Compatible with numerical or categorical coordinates.
 */
export function buildPlotMarkLines(
  markLines: MarkLineConfig[],
  PlotInst: typeof import('@observablehq/plot')
): any[] {
  const marks: any[] = [];
  if (!markLines || markLines.length === 0) return marks;

  for (const ml of markLines) {
    if (!ml || typeof ml !== 'object') continue;

    const axisType = (ml.axis || '').toLowerCase();
    const isX = axisType.includes('x') || ml.x !== undefined;
    const rawVal = ml.value ?? (isX ? ml.x : ml.y);
    if (rawVal === undefined || rawVal === null) continue;

    // Check if numeric or categorical value
    const numVal = Number(rawVal);
    const resolvedVal = isNaN(numVal) ? rawVal : numVal;

    const strokeColor = ml.color || ml.stroke || '#dc2626';
    const strokeWidth = ml.strokeWidth || ml.width || 1.5;

    let strokeDash: string | undefined = ml.strokeDasharray;
    if (!strokeDash && ml.style) {
      const st = ml.style.toLowerCase();
      if (st === 'dashed') strokeDash = '4,4';
      else if (st === 'dotted') strokeDash = '2,2';
      else if (st === 'solid') strokeDash = undefined;
    } else if (!strokeDash) {
      strokeDash = '4,4';
    }

    const labelText = ml.label || ml.title || ml.text;

    if (isX) {
      marks.push(
        PlotInst.ruleX([resolvedVal], {
          stroke: strokeColor,
          strokeWidth,
          strokeDasharray: strokeDash,
        })
      );
      if (labelText) {
        marks.push(
          PlotInst.text([{ x: resolvedVal, label: labelText }], {
            x: 'x',
            text: 'label',
            frameAnchor: 'top',
            dy: -8,
            fill: strokeColor,
            fontSize: 11,
            fontWeight: '600',
          })
        );
      }
    } else {
      marks.push(
        PlotInst.ruleY([resolvedVal], {
          stroke: strokeColor,
          strokeWidth,
          strokeDasharray: strokeDash,
        })
      );
      if (labelText) {
        marks.push(
          PlotInst.text([{ y: resolvedVal, label: labelText }], {
            y: 'y',
            text: 'label',
            frameAnchor: 'right',
            dx: 8,
            fill: strokeColor,
            fontSize: 11,
            fontWeight: '600',
          })
        );
      }
    }
  }

  return marks;
}

/**
 * Resolves standard fill and opacity configurations across DSLs.
 */
export function resolveFillConfig(yaml: any, defaultFill: boolean | string = false): {
  fill: boolean | string;
  fillOpacity: number;
} {
  const fill =
    yaml.fill !== undefined
      ? yaml.fill
      : yaml.filled !== undefined
      ? yaml.filled
      : yaml.area !== undefined
      ? yaml.area
      : defaultFill;

  const fillOpacity =
    typeof yaml.fillOpacity === 'number'
      ? yaml.fillOpacity
      : typeof yaml.transparency === 'number'
      ? yaml.transparency
      : typeof yaml.opacity === 'number'
      ? yaml.opacity
      : 0.25;

  return { fill, fillOpacity };
}

/**
 * Resolves unified label / dataLabels configuration across chart DSLs.
 */
export function resolveLabelConfig(yaml: any): {
  showLabels: boolean;
  filterSet?: Set<string>;
  fontSize: number;
} {
  const rawLabelsConfig =
    yaml.dataLabels !== undefined
      ? yaml.dataLabels
      : yaml.showLabels !== undefined
      ? yaml.showLabels
      : yaml.labelFilter !== undefined
      ? yaml.labelFilter
      : yaml.pointLabels !== undefined
      ? yaml.pointLabels
      : yaml.labelsConfig;

  let showLabels = false;
  let filterSet: Set<string> | undefined = undefined;

  if (rawLabelsConfig === true) {
    showLabels = true;
  } else if (rawLabelsConfig === false) {
    showLabels = false;
  } else if (Array.isArray(rawLabelsConfig)) {
    showLabels = true;
    filterSet = new Set(rawLabelsConfig.map((item) => String(item).trim().toLowerCase()));
  } else if (typeof rawLabelsConfig === 'string' && rawLabelsConfig.trim() !== '') {
    showLabels = true;
    const parts = rawLabelsConfig
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    filterSet = new Set(parts);
  }

  const fontSize = typeof yaml.fontSize === 'number' ? yaml.fontSize : 10;
  return { showLabels, filterSet, fontSize };
}

/**
 * Resolves universal axis configurations (labels, domain, reverse, display, log type).
 */
export function resolveAxisConfig(yaml: any, axis: 'x' | 'y') {
  const isX = axis === 'x';
  const isLog = isLogScale(yaml, axis);

  const axisRaw = yaml[axis];
  const axisIsString = typeof axisRaw === 'string';

  const label =
    (isX ? yaml.xTitle : yaml.yTitle) ??
    (axisIsString ? axisRaw : (axisRaw?.label ?? axisRaw?.title)) ??
    yaml.scales?.[axis]?.label ??
    yaml.options?.scales?.[axis]?.label ??
    yaml.options?.scales?.[axis]?.title ??
    null;

  const minVal = isX ? yaml.xMin : yaml.yMin;
  const maxVal = isX ? yaml.xMax : yaml.yMax;
  const domain =
    minVal !== undefined && maxVal !== undefined
      ? [minVal, maxVal]
      : (!axisIsString ? axisRaw?.domain : undefined) ?? yaml.scales?.[axis]?.domain;

  const reverse = isX ? yaml.xReverse ?? (!axisIsString ? axisRaw?.reverse : undefined) : yaml.yReverse ?? (!axisIsString ? axisRaw?.reverse : undefined);

  const display =
    (isX ? yaml.xDisplay : yaml.yDisplay) ??
    (!axisIsString ? (axisRaw?.display ?? axisRaw?.visible) : undefined) ??
    yaml.scales?.[axis]?.display;

  const grid =
    (!axisIsString ? axisRaw?.grid : undefined) ??
    yaml.scales?.[axis]?.grid ??
    yaml.grid ??
    true;

  return {
    type: isLog ? 'log' : undefined,
    label,
    domain,
    reverse: Boolean(reverse),
    axis: display === false ? null : undefined,
    grid: Boolean(grid),
  };
}

/**
 * Extracts and unifies common chart DSL configurations into a structured representation.
 */
export function parseCommonChartConfig(yaml: any): CommonChartConfig {
  if (!yaml || typeof yaml !== 'object') {
    return {
      legend: true,
      isXLog: false,
      isYLog: false,
      xLabel: null,
      yLabel: null,
      grid: true,
      fill: false,
      fillOpacity: 0.25,
      markLines: [],
    };
  }

  const title = yaml.title ?? yaml.chartTitle ?? undefined;
  const subtitle = yaml.subtitle ?? undefined;
  const caption = yaml.caption ?? undefined;

  const legend =
    yaml.legend !== undefined
      ? Boolean(yaml.legend)
      : yaml.options?.legend !== undefined
      ? Boolean(yaml.options.legend)
      : true;

  const isXLog = isLogScale(yaml, 'x');
  const isYLog = isLogScale(yaml, 'y');

  const xCfg = resolveAxisConfig(yaml, 'x');
  const yCfg = resolveAxisConfig(yaml, 'y');

  const { fill, fillOpacity } = resolveFillConfig(yaml);
  const markLines = extractMarkLines(yaml);

  const trendline =
    yaml.trendline ??
    yaml.trending ??
    yaml.trend ??
    yaml.bestFit ??
    yaml.options?.trendline;

  const { showLabels, fontSize: labelFontSize } = resolveLabelConfig(yaml);

  return {
    title,
    subtitle,
    caption,
    legend,
    isXLog,
    isYLog,
    xLabel: xCfg.label,
    yLabel: yCfg.label,
    xDomain: xCfg.domain,
    yDomain: yCfg.domain,
    xReverse: xCfg.reverse,
    yReverse: yCfg.reverse,
    xDisplay: xCfg.axis !== null,
    yDisplay: yCfg.axis !== null,
    beginAtZero: yaml.beginAtZero,
    grid: yaml.grid !== false,
    xGrid: xCfg.grid,
    yGrid: yCfg.grid,
    fill,
    fillOpacity,
    markLines,
    trendline,
    showLabels,
    labelFontSize,
  };
}

import { MarkdownRenderChild, type TFile } from 'obsidian';
import { renderError } from 'src/util';
import {
  generateTableData,
  rowsToTableData,
  coerceTableRow,
} from 'src/chartFromTable';
import { parseMarkdownTableRows } from './timelineParser';
import { parseCsvOrTsv } from './tabularDataParser';
import { toTFile, createCustomFetch } from './customFetch';
import type Renderer from '../chartRenderer';

export class PlotJsRenderChild extends MarkdownRenderChild {
  code: string;
  chartEl: HTMLElement | SVGElement | null = null;
  renderer: Renderer;
  ownPath: string;
  referencedFiles: Set<string> = new Set();

  constructor(
    code: string,
    el: HTMLElement,
    renderer: Renderer,
    ownPath: string
  ) {
    super(el);
    this.code = code;
    this.renderer = renderer;
    this.ownPath = ownPath;
    this.changeHandler = this.changeHandler.bind(this);
    this.reload = this.reload.bind(this);
  }

  async onload() {
    try {
      this.chartEl = await this.renderer.renderRaw(
        this.code,
        this.containerEl,
        this.ownPath,
        (filePath: string) => {
          this.referencedFiles.add(filePath);
        }
      );
    } catch (error) {
      renderError(error, this.containerEl);
    }

    this.renderer.plugin.app?.metadataCache?.on?.(
      'changed',
      this.changeHandler as any
    );
    this.renderer.plugin.app?.workspace?.on?.('css-change', this.reload);
  }

  changeHandler = (file?: TFile) => {
    if (!file) return;
    if (
      this.referencedFiles.has(file.path) ||
      this.referencedFiles.has(file.basename) ||
      file.path === this.ownPath
    ) {
      this.reload();
    }
  };

  reload = () => {
    this.onunload();
    void this.onload();
  };

  onunload() {
    this.renderer.plugin.app?.metadataCache?.off?.(
      'changed',
      this.changeHandler as any
    );
    this.renderer.plugin.app?.workspace?.off?.('css-change', this.reload);
    if (typeof (this.containerEl as any).empty === 'function') {
      (this.containerEl as any).empty();
    } else if (typeof this.containerEl.replaceChildren === 'function') {
      this.containerEl.replaceChildren();
    } else {
      this.containerEl.textContent = '';
    }
    this.chartEl = null;
  }
}

export class ChartRenderChild extends MarkdownRenderChild {
  data: any;
  chartEl: HTMLElement | SVGElement | null = null;
  renderer: Renderer;
  prep: any = null;
  ownPath: string;
  el: HTMLElement;
  referencedFiles: Set<string> = new Set();

  constructor(
    data: any,
    el: HTMLElement,
    renderer: Renderer,
    ownPath: string
  ) {
    super(el);
    this.el = el;
    this.data = data;
    this.renderer = renderer;
    this.ownPath = ownPath;
    this.changeHandler = this.changeHandler.bind(this);
    this.reload = this.reload.bind(this);
  }

  async onload() {
    try {
      const isExternalData = typeof this.data.data === 'string' && this.data.data.trim() !== '';

      if (isExternalData) {
        let obsidianModule: any = null;
        if (typeof require === 'function') {
          try {
            obsidianModule = require('obsidian');
          } catch {
            /* ignore */
          }
        }

        const app = this.renderer.plugin.app;
        const customFetch = createCustomFetch(app, obsidianModule, this.ownPath);

        const rawDataPath = String(this.data.data).trim().replace(/^[["'`\s]+|[\]"'`\s]+$/g, '');
        const cleanPath = rawDataPath.replace(/\\/g, '/').replace(/^\.?\//, '');
        this.referencedFiles.add(cleanPath);
        if (cleanPath.endsWith('.csv') || cleanPath.endsWith('.tsv') || cleanPath.endsWith('.json')) {
          const baseName = cleanPath.substring(cleanPath.lastIndexOf('/') + 1);
          this.referencedFiles.add(baseName);
          const noExt = baseName.replace(/\.[^/.]+$/, '');
          this.referencedFiles.add(noExt);
        }

        const res = await customFetch(cleanPath);
        const text = await res.text();
        const trimmed = text.trim();

        let rawRows: Record<string, any>[] = [];
        if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
          try {
            const parsedJson = JSON.parse(trimmed);
            rawRows = Array.isArray(parsedJson) ? parsedJson : [parsedJson];
          } catch {
            rawRows = parseCsvOrTsv(text);
          }
        } else {
          rawRows = parseCsvOrTsv(text);
        }

        if (rawRows.length === 0) {
          throw new Error(`External data at '${rawDataPath}' is empty or invalid`);
        }

        const tableRows = rawRows.map(coerceTableRow);
        const tableData = rowsToTableData(tableRows, this.data.layout ?? 'columns', this.data.select);

        const mergedYaml = {
          ...this.data,
          labels: this.data.labels ?? tableData.labels,
          tableRows,
          series: this.data.series ?? tableData.dataFields.map((df) => ({
            title: df.dataTitle,
            data: df.data,
          })),
        };

        this.data = mergedYaml;
        const updatedPrep = await this.renderer.datasetPrep(mergedYaml, this.el);
        this.chartEl = await this.renderer.renderRaw(updatedPrep, this.containerEl, this.ownPath);
      } else if (this.data.id) {
        const activeFile = this.renderer.plugin.app?.workspace?.getActiveFile() ?? null;
        const activePath = activeFile ? activeFile.path : '';
        const linkDest: TFile | null = this.data.file
          ? toTFile(
              this.renderer.plugin.app?.metadataCache?.getFirstLinkpathDest(
                this.data.file,
                activePath
              )
            )
          : null;
        const fileToRead = toTFile(
          this.data.file
            ? linkDest
            : this.renderer.plugin.app?.vault?.getAbstractFileByPath(
                this.ownPath
              ) ?? activeFile
        );

        if (!fileToRead) {
          throw new Error('Invalid id and/or file');
        }

        const fileCache =
          fileToRead ? (this.renderer.plugin.app?.metadataCache?.getFileCache(fileToRead) ?? null) : null;

        const cleanId = String(this.data.id).replace(/^\^/, '');
        const caretId = '^' + cleanId;

        let pos: any = undefined;

        if (fileCache?.blocks) {
          const exactBlock = fileCache.blocks[cleanId] ?? fileCache.blocks[caretId];
          if (exactBlock) {
            pos = exactBlock.position;
          } else {
            const cleanLower = cleanId.toLowerCase();
            const strippedLower = cleanLower.replace(/[-_]+/g, '');
            for (const k in fileCache.blocks) {
              const kLower = k.toLowerCase().replace(/^\^/, '');
              if (kLower === cleanLower || kLower.replace(/[-_]+/g, '') === strippedLower) {
                pos = fileCache.blocks[k]?.position;
                break;
              }
            }
          }
        }

        if (!pos && fileCache?.sections) {
          const cleanLower = cleanId.toLowerCase();
          const strippedLower = cleanLower.replace(/[-_]+/g, '');
          const sec = fileCache.sections.find(
            (pre: any) => {
              if (!pre.id) return false;
              const pId = String(pre.id).replace(/^\^/, '').toLowerCase();
              return (
                pId === cleanLower ||
                pId.replace(/[-_]+/g, '') === strippedLower ||
                pre.id === cleanId ||
                pre.id === caretId ||
                pre.id === this.data.id
              );
            }
          );
          if (sec) {
            pos = sec.position;
          }
        }

        const fullNoteText = await this.renderer.plugin.app.vault.cachedRead(fileToRead);
        let tableString = '';

        if (pos && pos.start && pos.end) {
          tableString = fullNoteText.substring(pos.start.offset, pos.end.offset);
        } else {
          // Fallback: search note text lines for matching block ID tag (^cleanId or inline)
          const lines = fullNoteText.split(/\r?\n/);
          const cleanLower = cleanId.toLowerCase();
          const strippedLower = cleanLower.replace(/[-_]+/g, '');

          let blockLineIdx = -1;
          for (let i = 0; i < lines.length; i++) {
            const l = lines[i].trim();
            const caretMatch = l.match(/\^([a-zA-Z0-9_-]+)\s*$/);
            if (caretMatch) {
              const matchedId = caretMatch[1].toLowerCase();
              if (matchedId === cleanLower || matchedId.replace(/[-_]+/g, '') === strippedLower) {
                blockLineIdx = i;
                break;
              }
            }
          }

          if (blockLineIdx >= 0) {
            let startIdx = blockLineIdx;
            if (lines[blockLineIdx].trim().startsWith('^')) {
              startIdx = blockLineIdx - 1;
            }
            while (startIdx >= 0 && lines[startIdx].trim().includes('|')) {
              startIdx--;
            }
            tableString = lines.slice(startIdx + 1, blockLineIdx + 1).join('\n');
          }
        }

        if (!tableString || !tableString.includes('|')) {
          throw new Error('Invalid id and/or file');
        }

        let tableData;
        try {
          tableData = generateTableData(
            tableString,
            this.data.layout ?? 'columns',
            this.data.select
          );
        } catch {
          throw new Error('There is no table at that id and/or file');
        }

        let tableRows: any[] = [];
        try {
          const rawRows = parseMarkdownTableRows(tableString);
          if (rawRows.length > 0) {
            tableRows = rawRows.map(coerceTableRow);
          }
        } catch {
          // ignore row extraction errors and fallback to series/labels
        }

        const mergedYaml = {
          ...this.data,
          labels: tableData.labels,
          tableRows,
          series: tableData.dataFields.map((df) => ({
            title: df.dataTitle,
            data: df.data,
          })),
        };

        const updatedPrep = await this.renderer.datasetPrep(mergedYaml, this.el);
        this.prep = updatedPrep;
        this.chartEl = await this.renderer.renderRaw(updatedPrep, this.containerEl, this.ownPath);
      } else {
        const preparedData = await this.renderer.datasetPrep(this.data, this.el);
        this.prep = preparedData;
        this.chartEl = await this.renderer.renderRaw(preparedData, this.containerEl, this.ownPath);
      }
    } catch (error) {
      renderError(error, this.el);
    }

    if (this.data.id || (typeof this.data.data === 'string' && this.data.data.trim() !== '')) {
      this.renderer.plugin.app?.metadataCache?.on?.(
        'changed',
        this.changeHandler as any
      );
    }
    this.renderer.plugin.app?.workspace?.on?.('css-change', this.reload);
  }

  changeHandler = (file?: TFile) => {
    if (!file) return;
    const isTargetFile =
      (this.data.file && (file.basename === this.data.file || file.name === this.data.file)) ||
      file.path === this.ownPath ||
      this.referencedFiles.has(file.path) ||
      this.referencedFiles.has(file.basename) ||
      this.referencedFiles.has(file.name);

    if (isTargetFile) {
      this.reload();
    }
  };

  reload = () => {
    this.onunload();
    void this.onload();
  };

  onunload() {
    this.renderer.plugin.app?.metadataCache?.off?.(
      'changed',
      this.changeHandler as any
    );
    this.renderer.plugin.app?.workspace?.off?.('css-change', this.reload);
    if (typeof this.el.empty === 'function') {
      this.el.empty();
    } else if (typeof this.el.replaceChildren === 'function') {
      this.el.replaceChildren();
    } else {
      this.el.textContent = '';
    }
    this.chartEl = null;
  }
}

import { TFile } from 'obsidian';

export function toTFile(item: unknown): TFile | null {
  if (typeof TFile === 'function' && item instanceof TFile) return item;
  return null;
}

export function createCustomFetch(app: any, obsidianModule: any, sourcePath: string = '') {
  return async function customFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    const urlString =
      typeof input === 'string'
        ? input
        : input instanceof URL
        ? input.toString()
        : input.url;

    if (/^https?:\/\//i.test(urlString)) {
      if (obsidianModule && typeof obsidianModule.requestUrl === 'function') {
        try {
          const reqOptions: any = { url: urlString };
          if (init) {
            if (init.method) reqOptions.method = init.method;
            if (init.headers) reqOptions.headers = init.headers;
            if (init.body) reqOptions.body = init.body;
          }
          const res = await obsidianModule.requestUrl(reqOptions);
          return new Response(res.arrayBuffer || res.text, {
            status: res.status,
            headers: res.headers,
          });
        } catch {
          // Fallback if requestUrl fails
        }
      }
      if (typeof window !== 'undefined' && typeof window.fetch === 'function') {
        return window.fetch(input, init);
      }
    }

    // Local vault relative path (normalize Windows backslashes and leading dots/slashes)
    const normalizedPath = urlString.replace(/\\/g, '/').replace(/^\.?\//, '');
    let file: TFile | null = null;

    if (app?.vault) {
      if (typeof app.vault.getAbstractFileByPath === 'function') {
        file = toTFile(app.vault.getAbstractFileByPath(normalizedPath));
      }
      if (!file && app.metadataCache && typeof app.metadataCache.getFirstLinkpathDest === 'function') {
        file = toTFile(app.metadataCache.getFirstLinkpathDest(normalizedPath, sourcePath));
      }

      if (file) {
        if (typeof app.vault.readBinary === 'function') {
          const buffer = await app.vault.readBinary(file);
          return new Response(buffer, { status: 200, statusText: 'OK' });
        }
        if (typeof app.vault.read === 'function') {
          const text = await app.vault.read(file);
          return new Response(text, { status: 200, statusText: 'OK' });
        }
      }

      if (app.vault.adapter) {
        try {
          if (typeof app.vault.adapter.readBinary === 'function') {
            const buffer = await app.vault.adapter.readBinary(normalizedPath);
            return new Response(buffer, { status: 200, statusText: 'OK' });
          }
          if (typeof app.vault.adapter.read === 'function') {
            const text = await app.vault.adapter.read(normalizedPath);
            return new Response(text, { status: 200, statusText: 'OK' });
          }
        } catch {
          // Adapter read failed
        }
      }
    }

    if (typeof window !== 'undefined' && typeof window.fetch === 'function') {
      return window.fetch(input, init);
    }

    throw new TypeError(`Failed to fetch local vault file: ${urlString}`);
  };
}

import { bindPlotStyleTooltip } from './tooltip';

export interface ChartDataPoint {
  x: any;
  y: number;
  series: string;
  index: number;
  seriesIndex: number;
}

export function renderPieChart(
  yaml: any,
  dataPoints: ChartDataPoint[],
  labels: any[],
  baseColors: string[],
  gridColor: string,
  textColor: string,
  widthStr: string,
  getD3: () => typeof import('d3')
) {
  const type = String(yaml.type ?? 'bar').trim().toLowerCase();
  const container = createDiv({ cls: 'chart-relative-container' });

  // Unified Title, Subtitle, Caption support matching figure[class*="plot"] styling
  const title = yaml.title ?? yaml.chartTitle;
  const subtitle = yaml.subtitle;
  const caption = yaml.caption;

  if (title) {
    const titleEl = createEl('h2', { cls: 'chart-heading-title' });
    titleEl.textContent = String(title);
    titleEl.style.color = textColor;
    container.appendChild(titleEl);
  }

  if (subtitle) {
    const subEl = createEl('h3', { cls: 'chart-heading-subtitle' });
    subEl.textContent = String(subtitle);
    subEl.style.color = textColor;
    container.appendChild(subEl);
  }

  const svgNs = 'http://www.w3.org/2000/svg';
  const size = 300;
  const radius = size / 2 - 20;
  const isDoughnut = type === 'doughnut' || type === 'donut';

  const pieData = dataPoints.length
    ? dataPoints
    : labels.map((l, i) => ({
        x: l,
        y: 1,
        series: 'Series 1',
        index: i,
        seriesIndex: 0,
      }));

  const d3Inst = getD3();
  const pie = d3Inst.pie<ChartDataPoint>()
    .value((d) => Math.max(0, d.y))
    .sort(null);

  const arcs = pie(pieData);
  const arcGen = d3Inst
    .arc<any>()
    .innerRadius(isDoughnut ? radius * 0.5 : 0)
    .outerRadius(radius);

  const svg = document.createElementNS(svgNs, 'svg');
  svg.setAttribute('class', 'chart-interactive-svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('width', `${size}`);
  svg.setAttribute('height', `${size}`);

  const g = document.createElementNS(svgNs, 'g');
  g.setAttribute('transform', `translate(${size / 2}, ${size / 2})`);

  arcs.forEach((slice, idx) => {
    const path = document.createElementNS(svgNs, 'path');
    const dStr = arcGen(slice);
    if (dStr) path.setAttribute('d', dStr);
    const color = baseColors[idx % baseColors.length];
    path.setAttribute('fill', color);
    path.setAttribute('stroke', gridColor);
    path.setAttribute('stroke-width', '1');
    path.setAttribute('class', 'chart-interactive-path');

    const tooltipText = slice.data.series && slice.data.series !== 'Series 1'
      ? `${slice.data.series}\n${slice.data.x}: ${slice.data.y}`
      : `${slice.data.x}: ${slice.data.y}`;

    bindPlotStyleTooltip(path, container, () => tooltipText);
    g.appendChild(path);
  });

  svg.appendChild(g);
  container.appendChild(svg);

  // Legend
  if (yaml.legend !== false) {
    const legendDiv = createDiv({ cls: 'chart-legend-container' });
    legendDiv.style.color = textColor;

    const legendItems = dataPoints.length ? dataPoints : labels.map((l) => ({ x: l, series: '' }));
    const hasMultipleSeries = dataPoints.some((d) => d.seriesIndex > 0);

    legendItems.forEach((item, idx) => {
      const itemDiv = createDiv({ cls: 'chart-legend-item' });

      const swatch = createSpan({ cls: 'chart-legend-swatch' });
      swatch.style.backgroundColor = baseColors[idx % baseColors.length];

      const textSpan = createSpan();
      textSpan.textContent = hasMultipleSeries && item.series ? `${item.x} (${item.series})` : String(item.x);

      itemDiv.appendChild(swatch);
      itemDiv.appendChild(textSpan);
      legendDiv.appendChild(itemDiv);
    });
    container.appendChild(legendDiv);
  }

  if (caption) {
    const capEl = createDiv({ cls: 'chart-caption-text' });
    capEl.textContent = String(caption);
    capEl.style.color = textColor;
    container.appendChild(capEl);
  }

  return { plotOptions: null, customElement: container, width: widthStr };
}

let _Plot: typeof import('@observablehq/plot') | null = null;
let _d3: typeof import('d3') | null = null;

const VALID_FRAME_ANCHORS = new Set([
  'middle',
  'top-left',
  'top',
  'top-right',
  'right',
  'bottom-right',
  'bottom',
  'bottom-left',
  'left',
]);

const FRAME_ANCHOR_MARKS = new Set([
  'text',
  'textX',
  'textY',
  'dot',
  'dotX',
  'dotY',
  'tip',
  'vector',
  'image',
]);

/**
 * Wraps an Observable Plot instance so marks supporting frameAnchor can accept
 * frameAnchor (as well as dx and dy) as channel accessors (strings or functions)
 * across collections of data items, automatically grouping and emitting composite
 * marks without throwing "invalid frameAnchor" errors.
 */
export function wrapPlotInstance(originalPlot: any): any {
  if (!originalPlot || originalPlot.__isWrapped) {
    return originalPlot;
  }

  const handler: ProxyHandler<any> = {
    get(target, prop, receiver) {
      const orig = Reflect.get(target, prop, receiver) as unknown;

      if (prop === 'lineY' && typeof orig === 'function') {
        const origLineY = orig as (...args: any[]) => any;
        return function (data: any, options: any = {}) {
          if (options.tip && options.stroke !== undefined) {
            const line = origLineY.call(target, data, { ...options, tip: false });
            // A hidden fill-coded point mark gives the tooltip the line's categorical color channel.
            const dotOptions: any = {
              ...(options.x !== undefined ? { x: options.x } : {}),
              ...(options.y !== undefined ? { y: options.y } : {}),
              fill: options.stroke,
              r: 0,
              stroke: 'none',
              tip: options.tip,
            };
            if (options.title !== undefined) dotOptions.title = options.title;
            const tooltipDots = target.dot(data, dotOptions);
            return target.marks([line, tooltipDots]);
          }
          return origLineY.call(target, data, options);
        };
      }

      if (typeof prop === 'string' && FRAME_ANCHOR_MARKS.has(prop) && typeof orig === 'function') {
        const origMarkFn = orig as (...args: any[]) => any;
        return function (data: any, options: any = {}) {
          if (options && options.frameAnchor !== undefined && !VALID_FRAME_ANCHORS.has(options.frameAnchor)) {
            const dataArr = Array.isArray(data)
              ? data
              : data && typeof data[Symbol.iterator] === 'function'
              ? Array.from(data)
              : null;

            if (dataArr && dataArr.length > 0) {
              const anchorGetter =
                typeof options.frameAnchor === 'function'
                  ? (options.frameAnchor as (d: any) => any)
                  : (d: any) => (d as Record<string, any>)?.[options.frameAnchor];

              const dxGetter =
                typeof options.dx === 'function'
                  ? (options.dx as (d: any) => any)
                  : typeof options.dx === 'string' && isNaN(Number(options.dx))
                  ? (d: any) => (d as Record<string, any>)?.[options.dx]
                  : null;

              const dyGetter =
                typeof options.dy === 'function'
                  ? (options.dy as (d: any) => any)
                  : typeof options.dy === 'string' && isNaN(Number(options.dy))
                  ? (d: any) => (d as Record<string, any>)?.[options.dy]
                  : null;

              // Group items by resolved (anchor, dx, dy)
              const groups = new Map<string, { anchor: string; dx: any; dy: any; items: any[] }>();

              for (const d of dataArr) {
                const anchorVal = anchorGetter(d);
                if (VALID_FRAME_ANCHORS.has(anchorVal)) {
                  const resolvedDx = dxGetter ? dxGetter(d) : options.dx;
                  const resolvedDy = dyGetter ? dyGetter(d) : options.dy;
                  const groupKey = `${anchorVal}___${resolvedDx}___${resolvedDy}`;

                  if (!groups.has(groupKey)) {
                    groups.set(groupKey, {
                      anchor: anchorVal,
                      dx: resolvedDx,
                      dy: resolvedDy,
                      items: [],
                    });
                  }
                  groups.get(groupKey)!.items.push(d);
                }
              }

              if (groups.size > 0) {
                const markList: any[] = [];
                for (const { anchor, dx, dy, items } of groups.values()) {
                  const subOptions = { ...options, frameAnchor: anchor };
                  if (dx !== undefined) subOptions.dx = dx;
                  if (dy !== undefined) subOptions.dy = dy;
                  markList.push(origMarkFn.call(target, items, subOptions));
                }
                return typeof target.marks === 'function' ? target.marks(markList) : markList;
              }
            }
          }

          return origMarkFn.call(target, data, options);
        };
      }

      return orig;
    },
  };

  const proxy = new Proxy(originalPlot, handler);
  proxy.__isWrapped = true;
  return proxy;
}

export function getPlot(): typeof import('@observablehq/plot') {
  if (!_Plot) {
    const loaded = require('@observablehq/plot');
    _Plot = wrapPlotInstance(loaded.default ?? loaded);
  }
  return _Plot!;
}

export function setPlot(val: any): void {
  _Plot = wrapPlotInstance(val);
}

export function getD3(): typeof import('d3') {
  if (!_d3) {
    const loaded = require('d3');
    _d3 = loaded.default ?? loaded;
  }
  return _d3!;
}

export function setD3(val: any): void {
  _d3 = val;
}

import type { TFile } from 'obsidian';
import { extractTablesFromMarkdown, extractTablesFromDom } from 'src/chartFromTable';
import { toTFile, createCustomFetch } from './customFetch';
import { getPlot, getD3 } from './plotInstance';

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;

const TABLE_COMMENT_REGEX1 = /^\/\/\s*table\s*:\s*(.+)$/i;
const TABLE_COMMENT_REGEX2 = /^\/\*\s*table\s*:\s*(.+)\s*\*\/$/i;
const ID_COMMENT_REGEX1 = /^\/\/\s*id\s*:\s*(.+)$/i;
const ID_COMMENT_REGEX2 = /^\/\*\s*id\s*:\s*(.+)\s*\*\/$/i;
const FILE_COMMENT_REGEX1 = /^\/\/\s*file\s*:\s*(.+)$/i;
const FILE_COMMENT_REGEX2 = /^\/\*\s*file\s*:\s*(.+)\s*\*\/$/i;
const VALID_IDENTIFIER_REGEX = /^[a-zA-Z_$][a-zA-Z0-9_$]*$/;

export function resolveToDomElement(val: any, PlotInst: any): HTMLElement | SVGElement | null {
  if (!val) return null;
  if (val instanceof HTMLElement || val instanceof SVGElement) {
    return val;
  }
  if (typeof val.plot === 'function') {
    try {
      const plotEl = val.plot();
      if (plotEl instanceof HTMLElement || plotEl instanceof SVGElement) {
        return plotEl;
      }
    } catch {
      // Ignore plot error
    }
  }
  if (Array.isArray(val) || val.marks) {
    try {
      const plotEl = PlotInst.plot(Array.isArray(val) ? { marks: val } : val);
      if (plotEl instanceof HTMLElement || plotEl instanceof SVGElement) {
        return plotEl;
      }
    } catch {
      // Ignore plot error
    }
  }
  if (typeof val.node === 'function') {
    try {
      const nodeEl = val.node();
      if (nodeEl instanceof HTMLElement || nodeEl instanceof SVGElement) {
        return nodeEl;
      }
    } catch {
      // Ignore node error
    }
  }
  return null;
}

export async function executePlotJs(
  codeStr: string,
  el: HTMLElement,
  app: any,
  sourcePath: string = '',
  onFileReferenced?: (filePath: string) => void
): Promise<HTMLElement | SVGElement | null> {
  let code = codeStr.trim();

  // Strip code fences if present in the string
  if (code.startsWith('```')) {
    code = code.replace(/^```[a-zA-Z0-9_-]*\n?/, '').replace(/\n?```$/, '').trim();
  }

  let obsidianModule: any = {};
  if (typeof require === 'function') {
    try {
      obsidianModule = require('obsidian');
    } catch {
      // Fallback if obsidian module not present
    }
  }

  const customFetch = createCustomFetch(app, obsidianModule, sourcePath);

  const PlotInst = getPlot();
  const d3Inst = getD3();

  // Table resolution: parse table IDs / comments and discover note tables
  const tableScope: Record<string, any> = {};
  const tablesMap = new Map<string, any[]>();
  const allTables: Array<{ id: string | null; rows: any[] }> = [];

  let explicitTableRef: string | null = null;
  let explicitFileRef: string | null = null;

  // Performance optimization: Fast O(1) delimiter check skips line splitting, trimming, and
  // regex matching when chart code contains no comments (57x speedup). When comments are present,
  // early check on line prefix avoids running 6 regular expressions against standard code lines.
  if (code.includes('//') || code.includes('/*')) {
    const codeLines = code.split('\n');
    for (let i = 0; i < codeLines.length; i++) {
      const l = codeLines[i].trim();
      if (!l.startsWith('//') && !l.startsWith('/*')) continue;

      const tableMatch = l.match(TABLE_COMMENT_REGEX1) || l.match(TABLE_COMMENT_REGEX2);
      if (tableMatch) {
        explicitTableRef = tableMatch[1].trim().replace(/^["']|["'];?$/g, '');
      }
      const idMatch = l.match(ID_COMMENT_REGEX1) || l.match(ID_COMMENT_REGEX2);
      if (idMatch && !explicitTableRef) {
        explicitTableRef = idMatch[1].trim().replace(/^["']|["'];?$/g, '');
      }
      const fileMatch = l.match(FILE_COMMENT_REGEX1) || l.match(FILE_COMMENT_REGEX2);
      if (fileMatch) {
        explicitFileRef = fileMatch[1].trim().replace(/^["']|["'];?$/g, '');
      }
    }
  }

  if (explicitTableRef && explicitTableRef.includes('#')) {
    const hashIdx = explicitTableRef.indexOf('#');
    if (!explicitFileRef) {
      explicitFileRef = explicitTableRef.slice(0, hashIdx).trim().replace(/^\[\[|\]\]$/g, '');
    }
    explicitTableRef = explicitTableRef.slice(hashIdx + 1).trim();
  }

  let targetFile: TFile | null = null;

  if (app) {
    if (explicitFileRef) {
      if (app.metadataCache?.getFirstLinkpathDest) {
        targetFile = toTFile(app.metadataCache.getFirstLinkpathDest(explicitFileRef, sourcePath));
      }
      if (!targetFile && app.vault?.getAbstractFileByPath) {
        targetFile = toTFile(app.vault.getAbstractFileByPath(
          explicitFileRef.endsWith('.md') ? explicitFileRef : `${explicitFileRef}.md`
        ));
      }
    } else if (sourcePath && app.vault?.getAbstractFileByPath) {
      targetFile = toTFile(app.vault.getAbstractFileByPath(sourcePath));
    }
    if (!targetFile && app.workspace?.getActiveFile) {
      targetFile = toTFile(app.workspace.getActiveFile());
    }
  }

  if (targetFile) {
    if (onFileReferenced) onFileReferenced(targetFile.path);
    let fullText = '';
    try {
      if (typeof app.vault?.cachedRead === 'function') {
        fullText = await app.vault.cachedRead(targetFile);
      } else if (typeof app.vault?.read === 'function') {
        fullText = await app.vault.read(targetFile);
      }
    } catch {
      // ignore read error
    }
    if (fullText) {
      const fileCache = app.metadataCache?.getFileCache ? app.metadataCache.getFileCache(targetFile) : null;
      extractTablesFromMarkdown(fullText, fileCache, tablesMap, allTables);
    }
  }

  const doc = el?.ownerDocument || (typeof document !== 'undefined' ? document : null);
  if (doc) {
    extractTablesFromDom(doc, tablesMap, allTables);
  }

  for (const [k, v] of tablesMap.entries()) {
    if (VALID_IDENTIFIER_REGEX.test(k)) {
      tableScope[k] = v;
    }
  }

  // Rewrite kebab-case table identifiers (e.g. table-countries) in user code
  if (code.includes('-')) {
    const kebabKeys = Array.from(tablesMap.keys()).filter((k) => k.includes('-') && !k.startsWith('^') && !k.startsWith('#'));
    if (kebabKeys.length > 0) {
      const kebabSet = new Set(kebabKeys);
      const tokenRegex = /(\/\/.*$|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|(?<![a-zA-Z0-9_$])([a-zA-Z0-9_$]+(?:-[a-zA-Z0-9_$]+)+)(?![a-zA-Z0-9_$])/gm;
      code = code.replace(tokenRegex, (match: string, literal: string | undefined, kebabIdent: string | undefined) => {
        if (literal) return literal;
        if (kebabIdent && kebabSet.has(kebabIdent)) {
          const stripped = kebabIdent.replace(/[-_]+/g, '');
          const under = kebabIdent.replace(/[-]/g, '_');
          if (tableScope[stripped]) return stripped;
          if (tableScope[under]) return under;
          return stripped;
        }
        return match;
      });
    }
  }

  if (explicitTableRef) {
    const cleanRef = explicitTableRef.replace(/^[#^]+/, '').trim();
    const matched =
      tablesMap.get(cleanRef) ||
      tablesMap.get('^' + cleanRef) ||
      tablesMap.get('#' + cleanRef) ||
      tablesMap.get(cleanRef.toLowerCase());
    if (matched) {
      tableScope.table = matched;
    }
  }

  if (!tableScope.table) {
    if (tablesMap.has('table')) {
      tableScope.table = tablesMap.get('table');
    } else if (allTables.length > 0) {
      tableScope.table = allTables[0].rows;
    }
  }

  let displayedElement: HTMLElement | SVGElement | null = null;
  const display = (val: any) => {
    const dom = resolveToDomElement(val, PlotInst);
    if (dom) {
      el.appendChild(dom);
      displayedElement = dom;
    }
    return val as unknown;
  };

  const prevWindowDisplay = typeof window !== 'undefined' ? (window as any).display : undefined;
  if (typeof window !== 'undefined') {
    (window as any).display = display;
  }

  const hasTableVars = Object.keys(tableScope).length > 0;
  const isStrict = code.includes('"use strict"') || code.includes("'use strict'");

  const wrapFnCode = (src: string) => {
    if (!hasTableVars) return src;
    if (isStrict) {
      const varDecls = Object.keys(tableScope)
        .filter((k) => /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(k))
        .map((k) => `var ${k} = __tableScope__["${k}"];`)
        .join('\n');
      return `${varDecls}\n${src}`;
    }
    return `with (__tableScope__) {\n${src}\n}`;
  };

  const runUserCode = async (userSrc: string): Promise<unknown> => {
    const wrapped = wrapFnCode(userSrc);
    const fn = new AsyncFunction('Plot', 'd3', 'el', 'container', 'app', 'obsidian', 'fetch', 'display', '__tableScope__', wrapped);
    return await fn(PlotInst, d3Inst, el, el, app, obsidianModule, customFetch, display, tableScope) as unknown;
  };

  let result: any;
  try {
    result = await runUserCode(code);

    if (result === undefined && !displayedElement) {
      const lines = code.split('\n');

      for (let i = lines.length - 1; i >= 0; i--) {
        const lineTrimmed = lines[i].trim();
        if (!lineTrimmed || lineTrimmed.startsWith('//')) continue;
        if (lineTrimmed.startsWith('return')) break;

        const declMatch = lineTrimmed.match(/^(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=/);
        const assignMatch = !declMatch && lineTrimmed.match(/^([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=/);
        const varName = declMatch ? declMatch[1] : assignMatch ? assignMatch[1] : null;

        if (varName) {
          try {
            const copy = [...lines, `return ${varName};`];
            const resVar = await runUserCode(copy.join('\n'));
            if (resVar !== undefined) {
              result = resVar;
              break;
            }
          } catch {
            // Ignore error and continue
          }
        }

        const copy = [...lines];
        copy[i] = 'return ' + copy[i];
        try {
          const res2 = await runUserCode(copy.join('\n'));
          if (res2 !== undefined) {
            result = res2;
            break;
          }
        } catch {
          // Ignore syntax error and try previous line
        }
      }
    }
  } finally {
    if (typeof window !== 'undefined') {
      if (prevWindowDisplay !== undefined) {
        (window as any).display = prevWindowDisplay;
      } else {
        delete (window as any).display;
      }
    }
  }

  if (displayedElement && (result === undefined || result === displayedElement)) {
    return displayedElement;
  }

  const domElement = resolveToDomElement(result, PlotInst);
  if (domElement) {
    if (domElement.parentElement !== el) {
      el.appendChild(domElement);
    }
    return domElement;
  }

  if (displayedElement) {
    return displayedElement;
  }

  return null;
}

import { bindPlotStyleTooltip } from './tooltip';
import type { ChartDataPoint } from './pieRenderer';

export function renderRadarChart(
  yaml: any,
  dataPoints: ChartDataPoint[],
  labels: any[],
  baseColors: string[],
  innerColors: string[],
  gridColor: string,
  textColor: string,
  widthStr: string,
  getD3: () => typeof import('d3')
) {
  const type = String(yaml.type ?? 'bar').trim().toLowerCase();
  const container = createDiv({ cls: 'chart-relative-container' });

  // Unified Title, Subtitle, Caption support
  const title = yaml.title ?? yaml.chartTitle;
  const subtitle = yaml.subtitle;
  const caption = yaml.caption;

  if (title) {
    const titleEl = createEl('h2', { cls: 'chart-heading-title' });
    titleEl.textContent = String(title);
    titleEl.style.color = textColor;
    container.appendChild(titleEl);
  }

  if (subtitle) {
    const subEl = createEl('h3', { cls: 'chart-heading-subtitle' });
    subEl.textContent = String(subtitle);
    subEl.style.color = textColor;
    container.appendChild(subEl);
  }

  const svgNs = 'http://www.w3.org/2000/svg';
  const size = 320;
  const center = size / 2;
  const maxRadius = size / 2 - 40;

  const categoryLabels = labels.length ? labels : Array.from(new Set(dataPoints.map((d: ChartDataPoint) => d.x)));
  const numCategories = Math.max(1, categoryLabels.length);

  // Performance optimization: Single-pass linear evaluation of min and max Y domain values.
  let minYVal = 0;
  let maxYVal = yaml.rMax ?? 1;
  if (dataPoints.length > 0) {
    if (!yaml.beginAtZero) minYVal = Math.min(0, dataPoints[0].y);
    for (let idx = 0; idx < dataPoints.length; idx++) {
      const y = dataPoints[idx].y;
      if (y > maxYVal) maxYVal = y;
      if (!yaml.beginAtZero && y < minYVal) minYVal = y;
    }
  }
  maxYVal = Math.max(maxYVal, 1);
  const effectiveMaxY = maxYVal === minYVal ? minYVal + 1 : maxYVal;

  const d3Inst = getD3();
  const rScale = d3Inst.scaleLinear().domain([minYVal, effectiveMaxY]).range([0, maxRadius]);

  const svg = document.createElementNS(svgNs, 'svg');
  svg.setAttribute('class', 'chart-interactive-svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('width', `${size}`);
  svg.setAttribute('height', `${size}`);

  const g = document.createElementNS(svgNs, 'g');
  g.setAttribute('transform', `translate(${center}, ${center})`);

  // Draw Grid Rings
  const numRings = 4;
  for (let rIdx = 1; rIdx <= numRings; rIdx++) {
    const ringRadius = (maxRadius / numRings) * rIdx;
    const circle = document.createElementNS(svgNs, 'circle');
    circle.setAttribute('r', `${ringRadius}`);
    circle.setAttribute('fill', 'none');
    circle.setAttribute('stroke', gridColor);
    circle.setAttribute('stroke-dasharray', '2 2');
    g.appendChild(circle);
  }

  // Draw Axis Lines and Labels
  categoryLabels.forEach((label, idx) => {
    const angle = (2 * Math.PI * idx) / numCategories - Math.PI / 2;
    const x2 = maxRadius * Math.cos(angle);
    const y2 = maxRadius * Math.sin(angle);

    const line = document.createElementNS(svgNs, 'line');
    line.setAttribute('x1', '0');
    line.setAttribute('y1', '0');
    line.setAttribute('x2', `${x2}`);
    line.setAttribute('y2', `${y2}`);
    line.setAttribute('stroke', gridColor);
    g.appendChild(line);

    const labelX = (maxRadius + 18) * Math.cos(angle);
    const labelY = (maxRadius + 18) * Math.sin(angle);
    const text = document.createElementNS(svgNs, 'text');
    text.setAttribute('x', `${labelX}`);
    text.setAttribute('y', `${labelY}`);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('dominant-baseline', 'middle');
    text.setAttribute('fill', textColor);
    text.setAttribute('font-size', '10px');
    text.textContent = String(label);
    g.appendChild(text);
  });

  // Group series
  const seriesMap = new Map<string, typeof dataPoints>();
  dataPoints.forEach((pt) => {
    if (!seriesMap.has(pt.series)) seriesMap.set(pt.series, []);
    seriesMap.get(pt.series)!.push(pt);
  });

  const isPolarArea = type !== 'radar';
  const isSingleSeriesPolarArea = isPolarArea && seriesMap.size <= 1;

  let sIdx = 0;
  seriesMap.forEach((pts, seriesName) => {
    const seriesColor = baseColors[sIdx % baseColors.length];
    const seriesInnerColor = innerColors[sIdx % innerColors.length];

    const ptMap = new Map<string, (typeof pts)[0]>();
    pts.forEach((pt) => ptMap.set(String(pt.x), pt));

    if (type === 'radar') {
      const polyPoints: Array<[number, number]> = categoryLabels.map((catLabel, cIdx) => {
        const angle = (2 * Math.PI * cIdx) / numCategories - Math.PI / 2;
        const pt = ptMap.get(String(catLabel)) || { y: 0 };
        const r = rScale(pt.y);
        return [r * Math.cos(angle), r * Math.sin(angle)];
      });

      const pathD = polyPoints
        .map((p, i) => `${i === 0 ? 'M' : 'L'}${p[0]},${p[1]}`)
        .join(' ') + ' Z';

      const path = document.createElementNS(svgNs, 'path');
      path.setAttribute('d', pathD);
      path.setAttribute('fill', seriesInnerColor);
      path.setAttribute('stroke', seriesColor);
      path.setAttribute('stroke-width', '2');
      path.setAttribute('class', 'chart-interactive-path');

      const tooltipText = `${seriesName}\n${pts.map((p) => `${p.x}: ${p.y}`).join('\n')}`;
      bindPlotStyleTooltip(path, container, () => tooltipText);

      g.appendChild(path);

      // Render interactive dots on vertices for specific point tooltips
      polyPoints.forEach((p, cIdx) => {
        const catLabel = categoryLabels[cIdx];
        const pt = ptMap.get(String(catLabel)) || { y: 0 };
        const dot = document.createElementNS(svgNs, 'circle');
        dot.setAttribute('cx', `${p[0]}`);
        dot.setAttribute('cy', `${p[1]}`);
        dot.setAttribute('r', '4');
        dot.setAttribute('fill', seriesColor);
        dot.setAttribute('class', 'chart-interactive-dot');
        bindPlotStyleTooltip(dot, container, () => `${seriesName}\n${catLabel}: ${pt.y}`);
        g.appendChild(dot);
      });
    } else {
      // Polar Area
      categoryLabels.forEach((catLabel, cIdx) => {
        const color = isSingleSeriesPolarArea
          ? baseColors[cIdx % baseColors.length]
          : seriesColor;
        const innerColor = isSingleSeriesPolarArea
          ? innerColors[cIdx % innerColors.length]
          : seriesInnerColor;

        const startAngle = (2 * Math.PI * cIdx) / numCategories - Math.PI / 2;
        const endAngle = (2 * Math.PI * (cIdx + 1)) / numCategories - Math.PI / 2;
        const pt = ptMap.get(String(catLabel)) || { y: 0 };
        const r = rScale(pt.y);

        const arcGen = d3Inst
          .arc<any>()
          .innerRadius(0)
          .outerRadius(r)
          .startAngle(startAngle + Math.PI / 2)
          .endAngle(endAngle + Math.PI / 2);

        const pathD = arcGen({} as any);
        if (pathD) {
          const path = document.createElementNS(svgNs, 'path');
          path.setAttribute('d', pathD);
          path.setAttribute('fill', innerColor);
          path.setAttribute('stroke', color);
          path.setAttribute('stroke-width', '1');
          path.setAttribute('class', 'chart-interactive-path');

          const tooltipPrefix = isSingleSeriesPolarArea && (seriesName.startsWith('Series ') || !seriesName)
            ? ''
            : `${seriesName}\n`;
          bindPlotStyleTooltip(path, container, () => `${tooltipPrefix}${catLabel}: ${pt.y}`);
          g.appendChild(path);
        }
      });
    }
    sIdx++;
  });

  svg.appendChild(g);
  container.appendChild(svg);

  // Legend
  if (yaml.legend !== false && seriesMap.size > 0) {
    const legendDiv = createDiv({ cls: 'chart-legend-container' });
    legendDiv.style.color = textColor;

    if (isSingleSeriesPolarArea) {
      // For single top-category polar area chart, show each category in the legend
      categoryLabels.forEach((label, lIdx) => {
        const itemDiv = createDiv({ cls: 'chart-legend-item' });

        const swatch = createSpan({ cls: 'chart-legend-swatch' });
        swatch.style.backgroundColor = baseColors[lIdx % baseColors.length];

        const textSpan = createSpan();
        textSpan.textContent = String(label);

        itemDiv.appendChild(swatch);
        itemDiv.appendChild(textSpan);
        legendDiv.appendChild(itemDiv);
      });
    } else {
      let lIdx = 0;
      seriesMap.forEach((_, name) => {
        const itemDiv = createDiv({ cls: 'chart-legend-item' });

        const swatch = createSpan({ cls: 'chart-legend-swatch' });
        swatch.style.backgroundColor = baseColors[lIdx % baseColors.length];

        const textSpan = createSpan();
        textSpan.textContent = name;

        itemDiv.appendChild(swatch);
        itemDiv.appendChild(textSpan);
        legendDiv.appendChild(itemDiv);
        lIdx++;
      });
    }
    container.appendChild(legendDiv);
  }

  if (caption) {
    const capEl = createDiv({ cls: 'chart-caption-text' });
    capEl.textContent = String(caption);
    capEl.style.color = textColor;
    container.appendChild(capEl);
  }

  return { plotOptions: null, customElement: container, width: widthStr };
}

import { bindPlotStyleTooltip } from './tooltip';

let sankeyGradCounter = 0;

export function renderSankeyChart(
  yaml: any,
  rawSeries: any[],
  baseColors: string[],
  textColor: string,
  widthStr: string
) {
  const container = createDiv({ cls: 'chart-relative-container' });

  // Unified Title, Subtitle, Caption support
  const title = yaml.title ?? yaml.chartTitle;
  const subtitle = yaml.subtitle;
  const caption = yaml.caption;

  if (title) {
    const titleEl = createEl('h2', { cls: 'chart-heading-title' });
    titleEl.textContent = String(title);
    titleEl.style.color = textColor;
    container.appendChild(titleEl);
  }

  if (subtitle) {
    const subEl = createEl('h3', { cls: 'chart-heading-subtitle' });
    subEl.textContent = String(subtitle);
    subEl.style.color = textColor;
    container.appendChild(subEl);
  }

  const explicitLabels: string[] = Array.isArray(yaml.labels) ? yaml.labels.map(String) : [];

  const explicitLabelsSet = new Set(explicitLabels);
  const normalizedLabelMap = new Map<string, string>();
  for (const l of explicitLabels) {
    const lower = l.toLowerCase();
    if (!normalizedLabelMap.has(lower)) normalizedLabelMap.set(lower, l);
    if (lower.endsWith('s')) {
      const sing = lower.slice(0, -1);
      if (!normalizedLabelMap.has(sing)) normalizedLabelMap.set(sing, l);
    }
    if (lower.endsWith('es')) {
      const sing = lower.slice(0, -2);
      if (!normalizedLabelMap.has(sing)) normalizedLabelMap.set(sing, l);
    }
  }

  const resolveNodeName = (rawName: string): string => {
    if (!rawName) return '';
    const trimmed = String(rawName).trim();

    if (explicitLabelsSet.has(trimmed)) return trimmed;

    const lower = trimmed.toLowerCase();
    const directMatch = normalizedLabelMap.get(lower);
    if (directMatch) return directMatch;

    if (lower.endsWith('s')) {
      const singMatch = normalizedLabelMap.get(lower.slice(0, -1));
      if (singMatch) return singMatch;
    }
    if (lower.endsWith('es')) {
      const esMatch = normalizedLabelMap.get(lower.slice(0, -2));
      if (esMatch) return esMatch;
    }

    return trimmed;
  };

  const sankeyFlows: Array<{ from: string; to: string; flow: number }> = [];
  const rawPriorityMap: Record<string, number> = { ...(yaml.priority ?? {}) };
  const rawColorFromMap: Record<string, string> = { ...(yaml.colorFrom ?? {}) };
  const rawColorToMap: Record<string, string> = { ...(yaml.colorTo ?? {}) };

  rawSeries.forEach((s: any) => {
    if (s.priority && typeof s.priority === 'object') {
      Object.assign(rawPriorityMap, s.priority);
    }
    if (s.colorFrom && typeof s.colorFrom === 'object') {
      Object.assign(rawColorFromMap, s.colorFrom);
    }
    if (s.colorTo && typeof s.colorTo === 'object') {
      Object.assign(rawColorToMap, s.colorTo);
    }

    const sData = s.data ?? [];
    sData.forEach((item: any) => {
      if (Array.isArray(item)) {
        if (item.length >= 3) {
          const val1IsNum = typeof item[1] === 'number' || (!isNaN(Number(item[1])) && isNaN(Number(item[2])));
          if (val1IsNum) {
            const from = resolveNodeName(item[0]);
            const flow = Number(item[1]) || 0;
            const to = resolveNodeName(item[2]);
            sankeyFlows.push({ from, to, flow });
          } else {
            const from = resolveNodeName(item[0]);
            const to = resolveNodeName(item[1]);
            const flow = Number(item[2]) || 0;
            sankeyFlows.push({ from, to, flow });
          }
        }
      } else if (item && typeof item === 'object') {
        const from = resolveNodeName(item.from ?? item.source ?? '');
        const to = resolveNodeName(item.to ?? item.target ?? '');
        const flow = Number(item.flow ?? item.value ?? 0) || 0;
        if (from && to) {
          sankeyFlows.push({ from, to, flow });
        }
      }
    });
  });

  const priorityMap: Record<string, number> = {};
  Object.entries(rawPriorityMap).forEach(([k, v]) => {
    priorityMap[resolveNodeName(k)] = v;
  });

  const colorFromMap: Record<string, string> = {};
  Object.entries(rawColorFromMap).forEach(([k, v]) => {
    colorFromMap[resolveNodeName(k)] = v;
  });

  const colorToMap: Record<string, string> = {};
  Object.entries(rawColorToMap).forEach(([k, v]) => {
    colorToMap[resolveNodeName(k)] = v;
  });

  const nodesSet = new Set<string>();
  explicitLabels.forEach((l) => nodesSet.add(l));
  sankeyFlows.forEach((f) => {
    nodesSet.add(f.from);
    nodesSet.add(f.to);
  });
  const nodes = Array.from(nodesSet).filter(Boolean);

  const nodeDepths: Record<string, number> = {};
  nodes.forEach((n) => (nodeDepths[n] = 0));

  for (let i = 0; i < nodes.length; i++) {
    let updated = false;
    sankeyFlows.forEach((f) => {
      if (nodeDepths[f.to] <= nodeDepths[f.from]) {
        nodeDepths[f.to] = nodeDepths[f.from] + 1;
        updated = true;
      }
    });
    if (!updated) break;
  }

  let maxDepth = 1;
  for (let i = 0; i < nodes.length; i++) {
    const d = nodeDepths[nodes[i]];
    if (d > maxDepth) maxDepth = d;
  }
  const layers: string[][] = Array.from({ length: maxDepth + 1 }, () => []);

  nodes.forEach((n) => {
    const depth = nodeDepths[n];
    layers[depth].push(n);
  });

  const nodeIndexMap = new Map<string, number>();
  nodes.forEach((n, idx) => nodeIndexMap.set(n, idx));

  layers.forEach((layer) => {
    layer.sort((a, b) => {
      const prioA = priorityMap[a] ?? Number.MAX_SAFE_INTEGER;
      const prioB = priorityMap[b] ?? Number.MAX_SAFE_INTEGER;
      if (prioA !== prioB) return prioA - prioB;
      return (nodeIndexMap.get(a) ?? 0) - (nodeIndexMap.get(b) ?? 0);
    });
  });

  const nodeOutFlow: Record<string, number> = {};
  const nodeInFlow: Record<string, number> = {};
  nodes.forEach((n) => {
    nodeOutFlow[n] = 0;
    nodeInFlow[n] = 0;
  });

  sankeyFlows.forEach((f) => {
    nodeOutFlow[f.from] += f.flow;
    nodeInFlow[f.to] += f.flow;
  });

  const nodeValues: Record<string, number> = {};
  nodes.forEach((n) => {
    nodeValues[n] = Math.max(nodeOutFlow[n], nodeInFlow[n], 1);
  });

  const svgNs = 'http://www.w3.org/2000/svg';
  const width = 700;
  const height = 400;
  const padX = 100;
  const padY = 30;
  const nodeWidth = 16;
  const nodeMarginY = 24;

  const usableWidth = width - padX * 2;
  const usableHeight = height - padY * 2;

  let scale = Number.POSITIVE_INFINITY;
  for (let lIdx = 0; lIdx < layers.length; lIdx++) {
    const layer = layers[lIdx];
    if (layer.length === 0) continue;
    let totalVal = 0;
    for (let nIdx = 0; nIdx < layer.length; nIdx++) {
      totalVal += nodeValues[layer[nIdx]];
    }
    const availH = usableHeight - (layer.length - 1) * nodeMarginY;
    const layerScale = availH / Math.max(totalVal, 1);
    if (layerScale < scale) scale = layerScale;
  }
  if (!isFinite(scale) || scale <= 0) scale = 1;

  const nodeCoords: Record<string, { x: number; y: number; height: number }> = {};
  const layerXStep = maxDepth > 0 ? usableWidth / maxDepth : 0;

  for (let depthIdx = 0; depthIdx < layers.length; depthIdx++) {
    const layer = layers[depthIdx];
    if (layer.length === 0) continue;

    const x = padX + depthIdx * layerXStep;
    let sumHeights = 0;
    for (let nIdx = 0; nIdx < layer.length; nIdx++) {
      sumHeights += Math.max(12, nodeValues[layer[nIdx]] * scale);
    }

    const totalLayerH = sumHeights + (layer.length - 1) * nodeMarginY;
    let currY = padY + (usableHeight - totalLayerH) / 2;

    for (let nIdx = 0; nIdx < layer.length; nIdx++) {
      const n = layer[nIdx];
      const h = Math.max(12, nodeValues[n] * scale);
      nodeCoords[n] = { x, y: currY, height: h };
      currY += h + nodeMarginY;
    }
  }

  const svg = document.createElementNS(svgNs, 'svg');
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('width', '100%');
  svg.setAttribute('height', `${height}`);

  const defs = document.createElementNS(svgNs, 'defs');
  svg.appendChild(defs);

  const currentOutY: Record<string, number> = {};
  const currentInY: Record<string, number> = {};
  nodes.forEach((n) => {
    const coord = nodeCoords[n];
    if (!coord) return;
    const totalOutH = nodeOutFlow[n] * scale;
    const totalInH = nodeInFlow[n] * scale;
    currentOutY[n] = coord.y + (coord.height - totalOutH) / 2;
    currentInY[n] = coord.y + (coord.height - totalInH) / 2;
  });

  const gradientPrefix = `sankey-grad-${++sankeyGradCounter}`;

  const sortedFlows = [...sankeyFlows].sort((a, b) => {
    const depthAFrom = nodeDepths[a.from];
    const depthBFrom = nodeDepths[b.from];
    if (depthAFrom !== depthBFrom) return depthAFrom - depthBFrom;

    const yAFrom = nodeCoords[a.from]?.y ?? 0;
    const yBFrom = nodeCoords[b.from]?.y ?? 0;
    if (yAFrom !== yBFrom) return yAFrom - yBFrom;

    const yATo = nodeCoords[a.to]?.y ?? 0;
    const yBTo = nodeCoords[b.to]?.y ?? 0;
    return yATo - yBTo;
  });

  sortedFlows.forEach((flow, idx) => {
    const srcCoord = nodeCoords[flow.from];
    const tgtCoord = nodeCoords[flow.to];
    if (!srcCoord || !tgtCoord) return;

    const linkStrokeWidth = Math.max(2, flow.flow * scale);

    const srcX = srcCoord.x + nodeWidth;
    const srcY = currentOutY[flow.from] + linkStrokeWidth / 2;
    currentOutY[flow.from] += linkStrokeWidth;

    const tgtX = tgtCoord.x;
    const tgtY = currentInY[flow.to] + linkStrokeWidth / 2;
    currentInY[flow.to] += linkStrokeWidth;

    const cFrom = colorFromMap[flow.from];
    const cTo = colorToMap[flow.to];
    let strokeColor = baseColors[idx % baseColors.length];

    if (cFrom && cTo) {
      const gradId = `${gradientPrefix}-${idx}`;
      const grad = document.createElementNS(svgNs, 'linearGradient');
      grad.setAttribute('id', gradId);
      grad.setAttribute('gradientUnits', 'userSpaceOnUse');
      grad.setAttribute('x1', `${srcX}`);
      grad.setAttribute('y1', `${srcY}`);
      grad.setAttribute('x2', `${tgtX}`);
      grad.setAttribute('y2', `${tgtY}`);

      const stop1 = document.createElementNS(svgNs, 'stop');
      stop1.setAttribute('offset', '0%');
      stop1.setAttribute('stop-color', cFrom);

      const stop2 = document.createElementNS(svgNs, 'stop');
      stop2.setAttribute('offset', '100%');
      stop2.setAttribute('stop-color', cTo);

      grad.appendChild(stop1);
      grad.appendChild(stop2);
      defs.appendChild(grad);

      strokeColor = `url(#${gradId})`;
    } else if (cFrom) {
      strokeColor = cFrom;
    } else if (cTo) {
      strokeColor = cTo;
    }

    const dx = (tgtX - srcX) * 0.5;
    const dStr = `M ${srcX} ${srcY} C ${srcX + dx} ${srcY}, ${tgtX - dx} ${tgtY}, ${tgtX} ${tgtY}`;

    const path = document.createElementNS(svgNs, 'path');
    path.setAttribute('d', dStr);
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', strokeColor);
    path.setAttribute('stroke-width', `${linkStrokeWidth}`);
    path.setAttribute('stroke-opacity', '0.5');
    path.setAttribute('class', 'chart-sankey-link');
    path.addEventListener('mouseenter', () => path.setAttribute('stroke-opacity', '0.85'));
    path.addEventListener('mouseleave', () => path.setAttribute('stroke-opacity', '0.5'));

    bindPlotStyleTooltip(path, container, () => `${flow.from} ➔ ${flow.to}\nFlow: ${flow.flow}`);
    svg.appendChild(path);
  });

  nodes.forEach((n, idx) => {
    const coord = nodeCoords[n];
    if (!coord) return;

    const nodeColor = colorFromMap[n] || colorToMap[n] || baseColors[idx % baseColors.length];

    const rect = document.createElementNS(svgNs, 'rect');
    rect.setAttribute('x', `${coord.x}`);
    rect.setAttribute('y', `${coord.y}`);
    rect.setAttribute('width', `${nodeWidth}`);
    rect.setAttribute('height', `${coord.height}`);
    rect.setAttribute('fill', nodeColor);
    rect.setAttribute('rx', '2');
    rect.setAttribute('class', 'chart-sankey-node');

    bindPlotStyleTooltip(rect, container, () => `${n}\nTotal Flow: ${nodeValues[n]}`);
    svg.appendChild(rect);

    const text = document.createElementNS(svgNs, 'text');
    const depth = nodeDepths[n];

    if (depth === 0) {
      text.setAttribute('x', `${coord.x - 8}`);
      text.setAttribute('text-anchor', 'end');
    } else {
      text.setAttribute('x', `${coord.x + nodeWidth + 8}`);
      text.setAttribute('text-anchor', 'start');
    }

    text.setAttribute('y', `${coord.y + coord.height / 2}`);
    text.setAttribute('dominant-baseline', 'middle');
    text.setAttribute('fill', textColor);
    text.setAttribute('font-size', '12px');
    text.setAttribute('font-weight', '500');
    text.textContent = n;
    svg.appendChild(text);
  });

  container.appendChild(svg);

  if (caption) {
    const capEl = createDiv({ cls: 'chart-caption-text' });
    capEl.textContent = String(caption);
    capEl.style.color = textColor;
    container.appendChild(capEl);
  }

  return { plotOptions: null, customElement: container, width: widthStr };
}

import type * as Plot from '@observablehq/plot';

import type { MarkLineConfig, TrendlineConfig } from './chartConfig';
import {
  isLogScale,
  extractMarkLines,
  buildPlotMarkLines,
  resolveAxisConfig,
} from './chartConfig';

export type { MarkLineConfig, TrendlineConfig };

export interface ScatterPoint {
  x: number;
  y: number;
  series: string;
  fill?: any;
  text?: string;
  r?: number;
  [key: string]: any;
}

function normalizeKey(str: string): string {
  return str
    .toLowerCase()
    .replace(/[²³]/g, (m) => (m === '²' ? '2' : '3'))
    .replace(/[^a-z0-9]/g, '');
}

function findMatchingColumn(candidates: string[], availableKeys: string[]): string | undefined {
  for (const c of candidates) {
    if (!c) continue;
    const direct = availableKeys.find((k) => k === c);
    if (direct) return direct;
    const lowerC = c.toLowerCase().trim();
    const caseMatch = availableKeys.find((k) => k.toLowerCase().trim() === lowerC);
    if (caseMatch) return caseMatch;
    const normC = normalizeKey(c);
    const normMatch = availableKeys.find((k) => normalizeKey(k) === normC);
    if (normMatch) return normMatch;
  }
  return undefined;
}

/**
 * Extracts and normalizes scatter data points from various schema formats:
 * - tableRows / tabular data: array of row objects mapped across columns (x, y, fill, text, r)
 * - series / datasets: [{ title, data: [[x, y], ...] | [{x, y}, ...] | [num, num, ...] }]
 * - data: [[x, y], ...] | [{x, y, series}, ...]
 * - labels-to-x mapping when data contains 1D numeric values
 */
export function extractScatterData(
  yaml: any,
  labels: any[] = []
): ScatterPoint[] {
  const scatterData: ScatterPoint[] = [];

  // Check if tabular data is provided (via tableRows or array of objects with >2 keys in yaml.data)
  const rows: any[] | null =
    Array.isArray(yaml.tableRows) && yaml.tableRows.length > 0
      ? yaml.tableRows
      : Array.isArray(yaml.rows) && yaml.rows.length > 0
      ? yaml.rows
      : Array.isArray(yaml.data) &&
        yaml.data.length > 0 &&
        yaml.data[0] &&
        typeof yaml.data[0] === 'object' &&
        !Array.isArray(yaml.data[0]) &&
        Object.keys(yaml.data[0]).length > 2 &&
        !('x' in yaml.data[0] && 'y' in yaml.data[0] && Object.keys(yaml.data[0]).length <= 3)
      ? yaml.data
      : null;

  if (rows && rows.length > 0) {
    const sampleRow = rows[0];
    const availableKeys = Object.keys(sampleRow);

    // Identify which columns are primarily numeric and text
    const numericCols = availableKeys.filter((k) => {
      let count = 0;
      for (const r of rows) {
        const val = r[k];
        if (typeof val === 'number' || (typeof val === 'string' && val.trim() !== '' && !isNaN(Number(val)))) {
          count++;
        }
      }
      return count >= Math.ceil(rows.length * 0.5);
    });

    const textCols = availableKeys.filter((k) => !numericCols.includes(k));

    // Resolve X column
    const explicitX =
      typeof yaml.x === 'string'
        ? yaml.x
        : yaml.x?.key || yaml.x?.field || yaml.x?.column || yaml.xField || yaml.xAxis;
    const xLabelCandidate = yaml.x?.label || yaml.xTitle;
    const xCol =
      findMatchingColumn([explicitX, xLabelCandidate].filter(Boolean), availableKeys) ||
      (numericCols.length >= 2 ? numericCols[numericCols.length - 1] : numericCols[0]) ||
      availableKeys[0];

    // Resolve Y column
    const explicitY =
      typeof yaml.y === 'string'
        ? yaml.y
        : yaml.y?.key || yaml.y?.field || yaml.y?.column || yaml.yField || yaml.yAxis;
    const yLabelCandidate = yaml.y?.label || yaml.yTitle;
    const yCol =
      findMatchingColumn([explicitY, yLabelCandidate].filter(Boolean), availableKeys) ||
      numericCols.find((k) => k !== xCol) ||
      availableKeys.find((k) => k !== xCol) ||
      availableKeys[0];

    // Resolve Fill / Color column
    const explicitFill =
      typeof yaml.fill === 'string'
        ? yaml.fill
        : typeof yaml.color === 'string'
        ? yaml.color
        : yaml.fill?.key || yaml.color?.key || yaml.category || yaml.group;
    let fillCol = findMatchingColumn([explicitFill].filter(Boolean), availableKeys);
    if (!fillCol) {
      // Find another numeric column (like Density) or categorical column
      fillCol = numericCols.find((k) => k !== xCol && k !== yCol);
    }

    // Resolve Text / Label column
    const explicitText =
      typeof yaml.text === 'string'
        ? yaml.text
        : typeof yaml.label === 'string'
        ? yaml.label
        : yaml.text?.key || yaml.label?.key;
    let textCol = findMatchingColumn([explicitText].filter(Boolean), availableKeys);
    if (!textCol && textCols.length > 0) {
      textCol = textCols[0];
    }

    // Resolve Radius / Size column
    const explicitR =
      typeof yaml.r === 'string'
        ? findMatchingColumn([yaml.r], availableKeys)
        : typeof yaml.size === 'string'
        ? findMatchingColumn([yaml.size], availableKeys)
        : typeof yaml.radius === 'string'
        ? findMatchingColumn([yaml.radius], availableKeys)
        : undefined;

    let hasRValues = false;

    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      const rawX = r[xCol];
      const rawY = r[yCol];
      const numX = Number(rawX);
      const numY = Number(rawY);

      if (!isNaN(numX) && !isNaN(numY)) {
        const pt: ScatterPoint = {
          ...r,
          x: numX,
          y: numY,
          series: fillCol && r[fillCol] !== undefined ? String(r[fillCol]) : 'Points',
        };

        if (fillCol && r[fillCol] !== undefined) {
          pt.fill = r[fillCol];
        }
        if (textCol && r[textCol] !== undefined) {
          pt.text = String(r[textCol]);
        }
        if (explicitR && r[explicitR] !== undefined) {
          const numR = Number(r[explicitR]);
          if (!isNaN(numR)) {
            pt.r = numR;
            hasRValues = true;
          }
        }

        scatterData.push(pt);
      }
    }

    if (scatterData.length > 0) {
      (scatterData as any).__tabularMeta = {
        xCol,
        yCol,
        fillCol,
        textCol,
        rCol: explicitR,
        hasR: hasRValues,
        isNumericFill: fillCol ? numericCols.includes(fillCol) : false,
      };
      return scatterData;
    }
  }

  const rawSeries =
    yaml.series ||
    yaml.datasets ||
    yaml.data?.series ||
    yaml.data?.datasets;

  if (Array.isArray(rawSeries) && rawSeries.length > 0) {
    for (let sIdx = 0; sIdx < rawSeries.length; sIdx++) {
      const s = rawSeries[sIdx];
      if (!s || typeof s !== 'object') continue;
      const seriesTitle = s.title || s.label || `Series ${sIdx + 1}`;
      const dataArr = Array.isArray(s.data) ? s.data : [];

      for (let ptIdx = 0; ptIdx < dataArr.length; ptIdx++) {
        const pt = dataArr[ptIdx];
        if (Array.isArray(pt)) {
          // [x, y] tuple format
          const xVal = Number(pt[0]);
          const yVal = Number(pt[1]);
          if (!isNaN(xVal) && !isNaN(yVal)) {
            scatterData.push({ x: xVal, y: yVal, series: seriesTitle });
          }
        } else if (pt && typeof pt === 'object') {
          // { x, y } object format
          const rawX = pt.x ?? pt.X ?? (labels[ptIdx] !== undefined ? labels[ptIdx] : ptIdx);
          const rawY = pt.y ?? pt.Y ?? pt.value ?? pt.val;
          const xVal = Number(rawX);
          const yVal = Number(rawY);
          if (!isNaN(xVal) && !isNaN(yVal)) {
            scatterData.push({ x: xVal, y: yVal, series: seriesTitle });
          }
        } else if (typeof pt === 'number' || (typeof pt === 'string' && !isNaN(Number(pt)))) {
          // numeric 1D value with labels mapping to x
          const rawX = labels[ptIdx] !== undefined ? Number(labels[ptIdx]) : ptIdx + 1;
          const xVal = isNaN(rawX) ? ptIdx + 1 : rawX;
          const yVal = Number(pt);
          if (!isNaN(xVal) && !isNaN(yVal)) {
            scatterData.push({ x: xVal, y: yVal, series: seriesTitle });
          }
        }
      }
    }
  } else if (Array.isArray(yaml.data)) {
    for (let ptIdx = 0; ptIdx < yaml.data.length; ptIdx++) {
      const pt = yaml.data[ptIdx];
      const seriesTitle = pt?.series || pt?.group || pt?.category || 'Points';
      if (Array.isArray(pt)) {
        const xVal = Number(pt[0]);
        const yVal = Number(pt[1]);
        if (!isNaN(xVal) && !isNaN(yVal)) {
          scatterData.push({ x: xVal, y: yVal, series: seriesTitle });
        }
      } else if (pt && typeof pt === 'object') {
        const xVal = Number(pt.x ?? pt.X ?? ptIdx);
        const yVal = Number(pt.y ?? pt.Y ?? pt.value);
        if (!isNaN(xVal) && !isNaN(yVal)) {
          scatterData.push({ x: xVal, y: yVal, series: seriesTitle });
        }
      }
    }
  }

  return scatterData;
}

/**
 * Builds Observable Plot options for scatter / point / scatterplot DSL specifications.
 */
export function buildScatterPlotOptions(
  yaml: any,
  scatterData: ScatterPoint[],
  baseColors: string[],
  gridColor: string,
  textColor: string,
  PlotInst: typeof import('@observablehq/plot')
): Plot.PlotOptions {
  const marks: any[] = [];

  // Detect scale type (normal or log)
  const isXLog = isLogScale(yaml, 'x');
  const isYLog = isLogScale(yaml, 'y');

  const tabularMeta = (scatterData as any)?.__tabularMeta;
  const isTabular = Boolean(tabularMeta);

  // Grids and Zero lines
  marks.push(
    PlotInst.gridX({ stroke: gridColor, strokeDasharray: '2,2' }),
    PlotInst.gridY({ stroke: gridColor, strokeDasharray: '2,2' }),
    PlotInst.ruleY([0], { stroke: gridColor }),
    PlotInst.ruleX([0], { stroke: gridColor })
  );

  // Scatter points (dot mark)
  const pointRadius = typeof yaml.radius === 'number' ? yaml.radius : (typeof yaml.r === 'number' ? yaml.r : 6);
  const dotStroke = yaml.stroke !== undefined ? yaml.stroke : 'white';
  const dotStrokeWidth = typeof yaml.strokeWidth === 'number' ? yaml.strokeWidth : 0.75;

  const dotOptions: any = {
    x: 'x',
    y: 'y',
    r: isTabular && tabularMeta.hasR ? 'r' : pointRadius,
    tip: true,
  };

  if (isTabular) {
    if (tabularMeta.fillCol) {
      dotOptions.fill = 'fill';
    } else {
      dotOptions.fill = baseColors[0] || '#3b82f6';
    }
    dotOptions.stroke = dotStroke;
    dotOptions.strokeWidth = dotStrokeWidth;
    if (yaml.transparency !== undefined) {
      dotOptions.fillOpacity = yaml.transparency;
    }
  } else {
    dotOptions.fill = 'series';
    dotOptions.stroke = dotStroke;
    dotOptions.strokeWidth = dotStrokeWidth;
    dotOptions.fillOpacity = yaml.transparency ?? 0.7;
  }

  marks.push(PlotInst.dot(scatterData, dotOptions));

  // Text mark for dot labels if text column is present
  // Supports boolean toggles (false to hide, true to show all) or selective filtering:
  // - labels: ["China", "India"] or "China, India"
  // - showLabels: ["Monaco", "Singapore"]
  // - labelFilter: /China|India/ or string list
  const rawLabelsConfig =
    yaml.labels !== undefined
      ? yaml.labels
      : yaml.showLabels !== undefined
      ? yaml.showLabels
      : yaml.labelFilter !== undefined
      ? yaml.labelFilter
      : yaml.text !== undefined
      ? yaml.text
      : true;

  const isLabelsDisabled =
    rawLabelsConfig === false ||
    yaml.labels === false ||
    yaml.text === false ||
    yaml.showLabels === false;

  const hasTextMark = isTabular && tabularMeta.textCol && !isLabelsDisabled;

  if (hasTextMark) {
    let labeledPoints = scatterData;

    // Filter points if selective labels are specified (array or string filter)
    const filterConfig =
      yaml.labelFilter !== undefined
        ? yaml.labelFilter
        : Array.isArray(yaml.labels) || (typeof yaml.labels === 'string' && yaml.labels.trim() !== '' && yaml.labels !== 'true')
        ? yaml.labels
        : Array.isArray(yaml.showLabels) || (typeof yaml.showLabels === 'string' && yaml.showLabels.trim() !== '' && yaml.showLabels !== 'true')
        ? yaml.showLabels
        : undefined;

    if (filterConfig) {
      if (Array.isArray(filterConfig)) {
        const allowed = new Set(
          filterConfig.map((item) => String(item).trim().toLowerCase())
        );
        labeledPoints = scatterData.filter(
          (pt) => pt.text && allowed.has(String(pt.text).trim().toLowerCase())
        );
      } else if (typeof filterConfig === 'string') {
        const parts = filterConfig
          .split(',')
          .map((s) => s.trim().toLowerCase())
          .filter(Boolean);
        const allowed = new Set(parts);
        labeledPoints = scatterData.filter(
          (pt) => pt.text && allowed.has(String(pt.text).trim().toLowerCase())
        );
      }
    }

    const fontSize = typeof yaml.fontSize === 'number' ? yaml.fontSize : 10;
    marks.push(
      PlotInst.text(labeledPoints, {
        x: 'x',
        y: 'y',
        text: 'text',
        dy: yaml.dy ?? -10,
        fontSize,
      })
    );
  }

  // Trending line (Linear Regression)
  const trendConfig: boolean | TrendlineConfig | undefined =
    yaml.trendline ??
    yaml.trending ??
    yaml.trend ??
    yaml.bestFit ??
    yaml.options?.trendline;

  if (trendConfig) {
    const isObj = typeof trendConfig === 'object' && trendConfig !== null;
    const strokeColor =
      isObj && trendConfig.stroke
        ? trendConfig.stroke
        : isTabular
        ? '#3b82f6'
        : 'series';
    const strokeWidth = isObj && trendConfig.strokeWidth ? trendConfig.strokeWidth : 2;
    const strokeDash =
      isObj && trendConfig.strokeDasharray
        ? trendConfig.strokeDasharray
        : isObj && trendConfig.stroke
        ? undefined
        : '4,4';
    const ciVal = isObj && trendConfig.ci !== undefined ? (trendConfig.ci ? 0.95 : null) : null;
    const fillVal =
      isObj && trendConfig.fill
        ? typeof trendConfig.fill === 'string'
          ? trendConfig.fill
          : 'series'
        : null;

    marks.push(
      PlotInst.linearRegressionY(scatterData, {
        x: 'x',
        y: 'y',
        stroke: strokeColor,
        strokeWidth,
        strokeDasharray: strokeDash,
        ci: ciVal as any,
        fill: fillVal as any,
      })
    );
  }

  // Mark lines (reference rules)
  const markLineConfigs = extractMarkLines(yaml);
  if (markLineConfigs.length > 0) {
    marks.push(...buildPlotMarkLines(markLineConfigs, PlotInst));
  }

  const showLegend =
    yaml.legend !== undefined
      ? Boolean(yaml.legend)
      : yaml.options?.legend !== undefined
      ? Boolean(yaml.options.legend)
      : true;

  let colorConfig: any;
  if (isTabular && tabularMeta.isNumericFill) {
    // Determine color scale type:
    // User request: Align color ruler scale with x or y scale when either is using log axis,
    // or when explicitly requested via colorScale/colorType/color.type/colorLog.
    const explicitColorType =
      yaml.colorType ||
      yaml.colorScale ||
      yaml.color?.type ||
      yaml.color?.scale ||
      yaml.scales?.color?.type;

    let colorType: string;
    if (explicitColorType) {
      colorType = explicitColorType === 'logarithmic' ? 'log' : explicitColorType;
    } else if (yaml.colorLog === true || yaml.logColor === true) {
      colorType = 'log';
    } else if (isXLog || isYLog) {
      // Auto-align with log axis
      colorType = 'log';
    } else {
      colorType = 'linear';
    }

    colorConfig = {
      type: colorType,
      scheme: yaml.colorScheme || yaml.color?.scheme || 'turbo',
      legend: showLegend,
      label: tabularMeta.fillCol,
      ...(yaml.colorDomain ? { domain: yaml.colorDomain } : {}),
      ...(yaml.color?.domain ? { domain: yaml.color.domain } : {}),
    };
  } else {
    colorConfig = {
      range: baseColors,
      legend: showLegend,
    };
  }

  const xResolved = resolveAxisConfig(yaml, 'x');
  const yResolved = resolveAxisConfig(yaml, 'y');

  const xAxisLabel = xResolved.label ?? (isTabular ? tabularMeta.xCol : null);
  const yAxisLabel = yResolved.label ?? (isTabular ? tabularMeta.yCol : null);

  // Auto-adaptive ticks based on width
  let defaultXTicks: any;
  const explicitXTicks = yaml.xTicks ?? yaml.ticks ?? yaml.x?.ticks ?? yaml.scales?.x?.ticks;
  if (explicitXTicks !== undefined) {
    defaultXTicks = explicitXTicks;
  } else {
    let estWidth = 640;
    if (typeof yaml.width === 'number') {
      estWidth = yaml.width;
    } else if (typeof yaml.width === 'string') {
      const pxMatch = yaml.width.match(/^(\d+(?:\.\d+)?)px$/);
      if (pxMatch) {
        estWidth = parseFloat(pxMatch[1]);
      } else {
        const pctMatch = yaml.width.match(/^(\d+(?:\.\d+)?)%$/);
        if (pctMatch) {
          estWidth = Math.round((parseFloat(pctMatch[1]) / 100) * 700);
        }
      }
    }
    defaultXTicks = Math.max(3, Math.min(12, Math.round(estWidth / 80)));
  }

  const xAxisConfig: any = {
    type: isXLog ? 'log' : 'linear',
    label: xAxisLabel,
    grid: yaml.x?.grid ?? true,
    domain: xResolved.domain,
    reverse: xResolved.reverse,
    ticks: defaultXTicks,
    axis: yaml.xDisplay === false ? null : undefined,
  };

  const yAxisConfig: any = {
    type: isYLog ? 'log' : 'linear',
    label: yAxisLabel,
    grid: yaml.y?.grid ?? true,
    domain: yResolved.domain,
    reverse: yResolved.reverse,
    zero: yaml.beginAtZero ?? false,
    axis: yaml.yDisplay === false ? null : undefined,
  };

  return {
    title: yaml.title ?? yaml.chartTitle ?? undefined,
    subtitle: yaml.subtitle ?? undefined,
    caption: yaml.caption ?? undefined,
    style: {
      background: 'transparent',
      color: textColor,
    },
    color: colorConfig,
    x: xAxisConfig,
    y: yAxisConfig,
    marks,
  };
}

// Fast-path plain CSV/TSV lines and parse quoted fields when needed.
export function parseCsvOrTsv(text: string): Record<string, string>[] {
  const rawLines = text.split(/\r?\n/);
  const lines: string[] = [];
  for (let i = 0; i < rawLines.length; i++) {
    const trimmed = rawLines[i].trim();
    if (trimmed.length > 0) {
      lines.push(trimmed);
    }
  }
  if (lines.length < 2) return [];

  let commaCount = 0;
  let tabCount = 0;
  let inHeaderQuotes = false;
  for (let i = 0; i < lines[0].length; i++) {
    const char = lines[0][i];
    if (char === '"') {
      if (inHeaderQuotes && lines[0][i + 1] === '"') {
        i++;
      } else {
        inHeaderQuotes = !inHeaderQuotes;
      }
    } else if (!inHeaderQuotes && char === ',') {
      commaCount++;
    } else if (!inHeaderQuotes && char === '\t') {
      tabCount++;
    }
  }
  const delimiter = tabCount > commaCount ? '\t' : ',';

  const parseLine = (line: string): string[] => {
    if (!line.includes('"')) {
      const parts = line.split(delimiter);
      for (let k = 0; k < parts.length; k++) {
        parts[k] = parts[k].trim();
      }
      return parts;
    }

    const result: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === delimiter && !inQuotes) {
        result.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    result.push(current.trim());
    return result;
  };

  const headers = parseLine(lines[0]);
  const numHeaders = headers.length;
  const numRows = lines.length - 1;
  const rows: Record<string, string>[] = new Array(numRows);

  for (let i = 0; i < numRows; i++) {
    const values = parseLine(lines[i + 1]);
    const rowObj: Record<string, string> = {};
    for (let j = 0; j < numHeaders; j++) {
      rowObj[headers[j]] = values[j] !== undefined ? values[j] : '';
    }
    rows[i] = rowObj;
  }

  return rows;
}

import type { TimelineEvent } from './timelineParser';
import { formatDisplayDate } from './timelineFormatters';

export interface ProcessedEvent extends TimelineEvent {
  id: string;
  startDate: Date;
  endDate: Date;
  isOngoing: boolean;
  categoryVal: string;
  collections: string[];
}

export interface SVGColsGroupElement extends SVGGElement {
  __renderedState?: {
    isCollapsed: boolean;
    color: string;
    activeCat: string;
  };
}

export function renderCollectionsNode(
  colsG: d3.Selection<SVGGElement, any, null, undefined>,
  evt: ProcessedEvent,
  barWidth: number,
  circleRadius: number,
  eventHeight: number,
  color: string,
  activeCat: string,
  showTooltip: (event: MouseEvent, title: string, details?: any) => void,
  hideTooltip: () => void
) {
  const node: SVGColsGroupElement | null = colsG.node();
  const requiredWidth = evt.collections.length * circleRadius * 2.3;
  const isCollapsed = evt.collections.length > 1 && barWidth < requiredWidth + 10;

  if (
    node?.__renderedState &&
    node.__renderedState.isCollapsed === isCollapsed &&
    node.__renderedState.color === color &&
    node.__renderedState.activeCat === activeCat
  ) {
    return;
  }

  if (node) {
    node.__renderedState = { isCollapsed, color, activeCat };
  }

  colsG.selectAll('*').remove();

  if (isCollapsed) {
    const badgeG = colsG.append('g').attr('class', 'collection-badge-node').style('cursor', 'pointer');
    const cx = -circleRadius * 1.5;
    const cy = eventHeight / 2;

    badgeG.append('circle')
      .attr('cx', cx)
      .attr('cy', cy)
      .attr('r', Math.max(circleRadius * 1.5, 12))
      .attr('fill', 'transparent');

    badgeG.append('circle')
      .attr('class', 'visible-badge-circle')
      .attr('cx', cx)
      .attr('cy', cy)
      .attr('r', circleRadius * 1.2)
      .attr('fill', color)
      .attr('stroke', 'var(--background-primary, #ffffff)')
      .attr('stroke-width', 1.5);

    badgeG.append('text')
      .attr('x', cx)
      .attr('y', cy + 3.5)
      .attr('text-anchor', 'middle')
      .attr('font-size', '9px')
      .attr('font-weight', '700')
      .attr('fill', '#ffffff')
      .attr('pointer-events', 'none')
      .text(`+${evt.collections.length}`);

    badgeG
      .on('mouseenter', (event: MouseEvent) => {
        event.stopPropagation();
        badgeG.select('.visible-badge-circle')
          .attr('stroke', 'var(--text-normal, #000000)')
          .attr('stroke-width', 2);
        showTooltip(
          event,
          `${evt.collections.length} Collection Items`,
          {
            categoryLabel: activeCat,
            categoryValue: evt.categoryVal,
            categoryColor: color,
            dateRange: `${formatDisplayDate(evt.startDate)} – ${evt.isOngoing ? 'Present' : formatDisplayDate(evt.endDate)}`,
            items: evt.collections,
          }
        );
      })
      .on('mousemove', (event: MouseEvent) => {
        event.stopPropagation();
        showTooltip(
          event,
          `${evt.collections.length} Collection Items`,
          {
            categoryLabel: activeCat,
            categoryValue: evt.categoryVal,
            categoryColor: color,
            dateRange: `${formatDisplayDate(evt.startDate)} – ${evt.isOngoing ? 'Present' : formatDisplayDate(evt.endDate)}`,
            items: evt.collections,
          }
        );
      })
      .on('mouseleave', (event: MouseEvent) => {
        event.stopPropagation();
        badgeG.select('.visible-badge-circle')
          .attr('stroke', 'var(--background-primary, #ffffff)')
          .attr('stroke-width', 1.5);
        hideTooltip();
      });
  } else {
    evt.collections.forEach((colItem, cIdx) => {
      const cx = -(cIdx + 0.75) * circleRadius * 2.3;
      const cy = eventHeight / 2;

      const circleG = colsG.append('g').attr('class', 'collection-node').style('cursor', 'pointer');

      circleG.append('circle')
        .attr('cx', cx)
        .attr('cy', cy)
        .attr('r', Math.max(circleRadius + 4, 10))
        .attr('fill', 'transparent');

      circleG.append('circle')
        .attr('class', 'visible-circle')
        .attr('cx', cx)
        .attr('cy', cy)
        .attr('r', circleRadius)
        .attr('fill', color)
        .attr('stroke', 'var(--background-primary, #ffffff)')
        .attr('stroke-width', 1);

      circleG
        .on('mouseenter', (event: MouseEvent) => {
          event.stopPropagation();
          circleG.select('.visible-circle')
            .attr('stroke', 'var(--text-normal, #000000)')
            .attr('stroke-width', 2)
            .attr('r', circleRadius * 1.3);
          showTooltip(event, String(colItem), {
            categoryLabel: activeCat,
            categoryValue: evt.categoryVal,
            categoryColor: color,
            dateRange: `${formatDisplayDate(evt.startDate)} – ${evt.isOngoing ? 'Present' : formatDisplayDate(evt.endDate)}`,
          });
        })
        .on('mousemove', (event: MouseEvent) => {
          event.stopPropagation();
          showTooltip(event, String(colItem), {
            categoryLabel: activeCat,
            categoryValue: evt.categoryVal,
            categoryColor: color,
            dateRange: `${formatDisplayDate(evt.startDate)} – ${evt.isOngoing ? 'Present' : formatDisplayDate(evt.endDate)}`,
          });
        })
        .on('mouseleave', (event: MouseEvent) => {
          event.stopPropagation();
          circleG.select('.visible-circle')
            .attr('stroke', 'var(--background-primary, #ffffff)')
            .attr('stroke-width', 1)
            .attr('r', circleRadius);
          hideTooltip();
        });
    });
  }
}

import {
  parseEventDate,
  type ParsedTimelineData,
} from './timelineParser';
import {
  createAdaptiveTickFormatter,
  formatCursorDate,
  calculateOptimalTickCount,
  preventTickOverlap,
} from '../lib/timeline-utils';
import { stripWikilinks } from './timelineWikilinks';
import { formatDisplayDate } from './timelineFormatters';
import { renderCollectionsNode, type ProcessedEvent } from './timelineCollections';
import type { TimelineTooltipController } from './timelineTooltip';

export interface SVGGroupElementWithRefs extends SVGGElement {
  __rectBar?: SVGRectElement | null;
  __leaderLine?: SVGLineElement | null;
  __colsG?: SVGGElement | null;
  __colsGSelection?: d3.Selection<SVGGElement, any, null, undefined> | null;
}

export interface EventNodeItem {
  gNode: SVGGElement;
  evt: ProcessedEvent;
  rectBarNode: SVGRectElement;
  leaderLineNode: SVGLineElement;
  colsGNode: SVGGElement | null;
  colsGSelection: d3.Selection<SVGGElement, any, null, undefined> | null;
  yPos: number;
  color: string;
  isHidden: boolean;
  baseXStart: number;
  baseXEnd: number;
  lastIsCollapsed?: boolean;
}

const ONGOING_KEYWORDS = new Set(['present', 'now', 'current', 'today']);

export function renderTimelineD3Chart(
  svg: SVGSVGElement,
  wrapper: HTMLElement,
  container: HTMLElement,
  parsedData: ParsedTimelineData,
  activeCategoryState: string,
  d3: typeof import('d3'),
  tooltipCtrl: TimelineTooltipController
): void {
  const { showTooltip, hideTooltip, positionTooltip } = tooltipCtrl;
  const activeCat = activeCategoryState || parsedData.categories[0] || 'category';
  const rawEvents = parsedData.events;
  const now = new Date();
  const nowTime = now.getTime();

  let minTime = Infinity;
  let maxTime = -Infinity;
  let hasOngoingEvent = false;

  const numEvents = rawEvents.length;
  const processedEvents: ProcessedEvent[] = new Array(numEvents);
  const categoryValuesSet = new Set<string>();

  for (let idx = 0; idx < numEvents; idx++) {
    const evt = rawEvents[idx];
    let startDate = parseEventDate(evt.start, now);

    const endVal = evt.end;
    let isOngoing = evt.ongoing === true;
    if (!isOngoing) {
      if (typeof endVal === 'string') {
        isOngoing = ONGOING_KEYWORDS.has(endVal.trim().toLowerCase());
      } else if (typeof endVal === 'number') {
        isOngoing = Math.abs(endVal - nowTime) < 86400000;
      }
    }
    if (isOngoing) {
      hasOngoingEvent = true;
    }

    let endDate: Date;
    if (isOngoing) {
      endDate = now;
    } else if (endVal !== undefined && endVal !== null && endVal !== '') {
      endDate = parseEventDate(endVal, startDate);
    } else {
      endDate = startDate;
    }

    if (!isOngoing && endDate < startDate) {
      const temp = startDate;
      startDate = endDate;
      endDate = temp;
    }
    const startTime = startDate.getTime();
    const endTime = endDate.getTime();

    if (startTime < minTime) minTime = startTime;
    if (endTime > maxTime) maxTime = endTime;

    const categoryVal = String(evt[activeCat] ?? 'default');
    categoryValuesSet.add(categoryVal);
    const collections = Array.isArray(evt.collection) ? evt.collection : [];

    processedEvents[idx] = {
      ...evt,
      id: `evt_${idx}_${startTime}`,
      startDate,
      endDate,
      isOngoing,
      categoryVal,
      collections,
    };
  }

  processedEvents.sort((a, b) => a.startDate.getTime() - b.startDate.getTime());

  const containerWidth = wrapper.getBoundingClientRect().width || 760;
  const width = Math.max(containerWidth, 380);
  const height = Math.max(340, processedEvents.length * 44 + 120);

  const margin = { top: 52, right: 30, bottom: 85, left: 20 };
  const padding = { top: 28, right: 0, bottom: 0, left: 0 };

  const innerWidth = width - margin.left - margin.right - padding.left - padding.right;
  const innerHeight = height - margin.top - margin.bottom - padding.top - padding.bottom;

  const compStyle = typeof window !== 'undefined' && window.getComputedStyle ? window.getComputedStyle(container) : null;
  const isDarkMode = (typeof document !== 'undefined' && document.body && document.body.classList.contains('theme-dark')) ||
    compStyle?.getPropertyValue('--background-primary')?.trim().startsWith('#2') ||
    false;

  const d3Svg = d3.select(svg);
  d3Svg.selectAll('*').remove();

  d3Svg
    .attr('viewBox', `0 0 ${width} ${height}`)
    .attr('width', '100%')
    .attr('height', height)
    .style('max-width', '100%')
    .style('height', 'auto')
    .style('user-select', 'none')
    .style('font-family', 'var(--font-interface, var(--font-text, sans-serif))');

  const categoryValues = Array.from(categoryValuesSet);
  const colorPalette = isDarkMode
    ? ['#60a5fa', '#f59e0b', '#f87171', '#34d399', '#a78bfa', '#fbbf24', '#38bdf8', '#c084fc']
    : (d3.schemeTableau10 || ['#4e79a7', '#f28e2c', '#e15759', '#76b7b2', '#59a14f', '#edc949', '#af7aa1', '#ff9da7']);

  const scaleColor = d3.scaleOrdinal<string>().domain(categoryValues).range(colorPalette);

  const minDate = isFinite(minTime) ? new Date(minTime) : new Date('2013-01-01');
  const maxDate = isFinite(maxTime) ? new Date(maxTime) : new Date('2027-01-01');

  const timeSpan = maxDate.getTime() - minDate.getTime();
  const domainBuffer = Math.max(timeSpan * 0.05, 86400000 * 30);
  const dateExtent: [Date, Date] = [
    new Date(minDate.getTime() - domainBuffer),
    new Date(maxDate.getTime() + domainBuffer),
  ];

  const timeScale = d3.scaleTime().domain(dateExtent).range([0, innerWidth]).nice();

  const eventIds: string[] = new Array(numEvents);
  for (let idx = 0; idx < numEvents; idx++) {
    eventIds[idx] = processedEvents[idx].id;
  }
  const scaleY = d3.scaleBand().domain(eventIds).range([0, innerHeight]).padding(0.28);

  const eventHeight = scaleY.bandwidth() * 0.65;
  const circleRadius = Math.max(3.5, eventHeight * 0.32);

  let activeScaleX = timeScale;
  const initialSpanMs = dateExtent[1].getTime() - dateExtent[0].getTime();

  const getOptimalTicks = () => {
    const dom = activeScaleX.domain() as [Date, Date];
    const spanMs = dom && dom[0] && dom[1] ? Math.abs(dom[1].getTime() - dom[0].getTime()) : initialSpanMs;
    return calculateOptimalTickCount(innerWidth, spanMs);
  };

  const targetTicks = getOptimalTicks();
  const gridTicks = Math.max(targetTicks * 2, Math.floor(innerWidth / 45));

  let activeTickFormatter: (d: Date | d3.NumberValue) => string = () => '';
  const updateActiveTickFormatter = (ticksCount: number) => {
    const dom = activeScaleX.domain() as [Date, Date];
    const spanMs = dom && dom[0] && dom[1] ? Math.abs(dom[1].getTime() - dom[0].getTime()) : initialSpanMs;
    const ticks = activeScaleX.ticks ? activeScaleX.ticks(ticksCount) : [];
    let intervalMs = spanMs / Math.max(1, ticksCount);
    if (ticks.length >= 2) {
      intervalMs = Math.abs(ticks[1].getTime() - ticks[0].getTime());
    }
    activeTickFormatter = createAdaptiveTickFormatter(intervalMs);
  };

  updateActiveTickFormatter(targetTicks);
  const formatTick = (d: Date | d3.NumberValue): string => {
    return activeTickFormatter(d);
  };

  const chartG = d3Svg.append('g').attr('class', 'chart-main');

  const gridG = chartG.append('g').attr('class', 'grid x').attr('transform', `translate(${margin.left},${margin.top + padding.top})`);
  const eventsG = chartG.append('g').attr('class', 'events').attr('transform', `translate(${margin.left},${margin.top + padding.top})`);
  const axisTopG = chartG.append('g').attr('class', 'axis x axis-top').attr('transform', `translate(${margin.left},${margin.top})`);
  const axisBottomG = chartG.append('g').attr('class', 'axis x axis-bottom').attr('transform', `translate(${margin.left},${margin.top + innerHeight + padding.top + 10})`);

  const timeAxisTop = d3.axisTop(timeScale).ticks(targetTicks).tickFormat(formatTick).tickSize(6);
  const timeAxisBottom = d3.axisBottom(timeScale).ticks(targetTicks).tickFormat(formatTick).tickSize(6);
  const timeGrid = d3.axisTop(timeScale).ticks(gridTicks).tickFormat(() => '').tickSize(-innerHeight - padding.top - 10);

  axisTopG.call(timeAxisTop);
  axisBottomG.call(timeAxisBottom);
  gridG.call(timeGrid);
  gridG.select('.domain').attr('display', 'none');

  preventTickOverlap(axisTopG.node());
  preventTickOverlap(axisBottomG.node());

  const legendHeight = 35;
  const legendY = height - legendHeight - 10;
  const legendClipId = `legend-clip-${Math.random().toString(36).slice(2, 11)}`;

  const defs = d3Svg.append('defs');
  defs.append('clipPath')
    .attr('id', legendClipId)
    .append('rect')
    .attr('x', margin.left)
    .attr('y', 0)
    .attr('width', innerWidth)
    .attr('height', legendHeight + 20);

  const legendG = d3Svg.append('g')
    .attr('class', 'legend')
    .attr('transform', `translate(0, ${legendY})`)
    .attr('clip-path', `url(#${legendClipId})`);

  const legendContentG = legendG.append('g')
    .attr('class', 'legend-content')
    .style('cursor', 'grab');

  let currentLegendOffsetX = margin.left;
  legendContentG.attr('transform', `translate(${currentLegendOffsetX}, 0)`);

  let legendX = 0;
  categoryValues.forEach((catVal) => {
    const color = scaleColor(catVal);
    const itemG = legendContentG.append('g').attr('transform', `translate(${legendX}, 0)`);

    itemG.append('rect')
      .attr('width', 12)
      .attr('height', 12)
      .attr('rx', 2)
      .attr('fill', color);

    const textNode = itemG.append('text')
      .attr('class', 'legend-text')
      .attr('x', 18)
      .attr('y', 10)
      .attr('font-size', '12px')
      .attr('font-style', 'italic')
      .attr('fill', 'var(--text-muted, #64748b)')
      .text(catVal);

    const textNodeEl = textNode.node();
    const measured = typeof textNodeEl?.getComputedTextLength === 'function' ? textNodeEl.getComputedTextLength() : 0;
    const textWidth = measured > 0 ? measured : catVal.length * 7.5;

    legendX += textWidth + 32;
  });

  const totalLegendWidth = legendX;
  const maxLegendDragOffset = margin.left;
  const minLegendDragOffset = totalLegendWidth > innerWidth
    ? margin.left - (totalLegendWidth - innerWidth)
    : margin.left;

  const dragBehavior = d3.drag<SVGGElement, unknown>()
    .on('start', function () {
      d3.select(this).style('cursor', 'grabbing');
    })
    .on('drag', function (event) {
      currentLegendOffsetX += event.dx;
      currentLegendOffsetX = Math.max(minLegendDragOffset, Math.min(maxLegendDragOffset, currentLegendOffsetX));
      d3.select(this).attr('transform', `translate(${currentLegendOffsetX}, 0)`);
    })
    .on('end', function () {
      d3.select(this).style('cursor', 'grab');
    });

  if (totalLegendWidth > innerWidth) {
    legendContentG.call(dragBehavior);
  }

  const eventNodeList: EventNodeItem[] = new Array(numEvents);

  let nowG: d3.Selection<SVGGElement, unknown, null, undefined> | null = null;
  let nowLineNode: SVGLineElement | null = null;
  let nowLabelNode: SVGTextElement | null = null;

  if (hasOngoingEvent) {
    nowG = chartG.append('g').attr('class', 'now-indicator');

    const nowLine = nowG.append('line')
      .attr('class', 'now-line')
      .attr('y1', margin.top - 18)
      .attr('y2', margin.top + innerHeight + padding.top + 10)
      .attr('stroke', '#d97706')
      .attr('stroke-width', 1.5)
      .attr('stroke-dasharray', '3,3');

    const nowLabel = nowG.append('text')
      .attr('class', 'now-label')
      .attr('y', margin.top - 24)
      .attr('text-anchor', 'middle')
      .attr('font-size', '11px')
      .attr('font-weight', '700')
      .attr('fill', '#d97706')
      .text('Today');

    nowLineNode = nowLine.node();
    nowLabelNode = nowLabel.node();
  }

  // High-performance needle cursor indicator
  const needleG = chartG.append('g')
    .attr('class', 'needle-indicator')
    .style('pointer-events', 'none')
    .style('display', 'none');

  needleG.append('line')
    .attr('class', 'needle-line')
    .attr('y1', margin.top - 24)
    .attr('y2', margin.top + innerHeight + padding.top + 12)
    .attr('stroke', '#f97316')
    .attr('stroke-width', 1.5);

  const needleBadgeG = needleG.append('g').attr('class', 'needle-badge');

  const needleBadgeRect = needleBadgeG.append('rect')
    .attr('class', 'needle-badge-rect')
    .attr('y', margin.top - 38)
    .attr('height', 22)
    .attr('rx', 5)
    .attr('fill', '#f97316')
    .attr('stroke', '#c2410c')
    .attr('stroke-width', 1);

  const needleBadgeText = needleBadgeG.append('text')
    .attr('class', 'needle-badge-text')
    .attr('y', margin.top - 23)
    .attr('text-anchor', 'middle')
    .attr('font-size', '11px')
    .attr('font-weight', '700')
    .attr('font-family', 'monospace')
    .attr('fill', '#ffffff');

  let rafNeedleId: number | null = null;
  let lastNeedleText = '';

  const updateNeedle = (mouseX: number) => {
    rafNeedleId = null;
    const xPos = mouseX - margin.left;
    if (xPos < 0 || xPos > innerWidth || svg.classList.contains('is-zooming')) {
      needleG.style('display', 'none');
      return;
    }

    const cursorDate = activeScaleX.invert(xPos);
    const dom = activeScaleX.domain() as [Date, Date];
    const durationMs = dom && dom[0] && dom[1] ? Math.abs(dom[1].getTime() - dom[0].getTime()) : initialSpanMs;
    const dateStr = formatCursorDate(cursorDate, durationMs);

    const needleBadgeRectNode = needleBadgeRect.node();
    const needleBadgeTextNode = needleBadgeText.node();
    const needleGNode = needleG.node();
    const needleBadgeGNode = needleBadgeG.node();

    if (needleGNode) {
      needleG.style('display', null);
      needleGNode.setAttribute('transform', `translate(${margin.left + xPos}, 0)`);
    }

    if (dateStr !== lastNeedleText) {
      lastNeedleText = dateStr;
      if (needleBadgeTextNode) {
        needleBadgeTextNode.textContent = dateStr;
        const measuredWidth = typeof needleBadgeTextNode.getComputedTextLength === 'function' ? needleBadgeTextNode.getComputedTextLength() : 0;
        const textWidth = measuredWidth > 0 ? measuredWidth : dateStr.length * 7;
        const badgeWidth = textWidth + 16;

        if (needleBadgeRectNode) {
          needleBadgeRectNode.setAttribute('x', String(-badgeWidth / 2));
          needleBadgeRectNode.setAttribute('width', String(badgeWidth));
        }

        if (needleBadgeGNode) {
          const totalX = margin.left + xPos;
          let badgeOffset = 0;
          if (totalX - badgeWidth / 2 < 5) {
            badgeOffset = 5 - (totalX - badgeWidth / 2);
          } else if (totalX + badgeWidth / 2 > width - 5) {
            badgeOffset = (width - 5) - (totalX + badgeWidth / 2);
          }
          needleBadgeGNode.setAttribute('transform', `translate(${badgeOffset}, 0)`);
        }
      }
    } else if (needleBadgeGNode && needleBadgeRectNode) {
      const badgeWidth = parseFloat(needleBadgeRectNode.getAttribute('width') || '100');
      const totalX = margin.left + xPos;
      let badgeOffset = 0;
      if (totalX - badgeWidth / 2 < 5) {
        badgeOffset = 5 - (totalX - badgeWidth / 2);
      } else if (totalX + badgeWidth / 2 > width - 5) {
        badgeOffset = (width - 5) - (totalX + badgeWidth / 2);
      }
      needleBadgeGNode.setAttribute('transform', `translate(${badgeOffset}, 0)`);
    }
  };

  d3Svg
    .on('mousemove.needle', (event: MouseEvent) => {
      const [ptX] = d3.pointer(event, svg);
      if (rafNeedleId === null) {
        if (typeof window !== 'undefined' && typeof window.requestAnimationFrame !== 'undefined') {
          rafNeedleId = window.requestAnimationFrame(() => updateNeedle(ptX));
        } else {
          updateNeedle(ptX);
        }
      }
    })
    .on('mouseleave.needle', () => {
      if (rafNeedleId !== null) {
        if (typeof window !== 'undefined' && typeof window.cancelAnimationFrame !== 'undefined') {
          window.cancelAnimationFrame(rafNeedleId);
        }
        rafNeedleId = null;
      }
      needleG.style('display', 'none');
    });

  for (let evtIdx = 0; evtIdx < numEvents; evtIdx++) {
    const evt = processedEvents[evtIdx];
    const color = scaleColor(evt.categoryVal);
    const yPos = scaleY(evt.id) || 0;
    const evtG = eventsG.append('g').attr('class', 'event-group').datum(evt).style('cursor', 'pointer');

    const rectBar = evtG.append('rect')
      .attr('class', 'event-bar')
      .attr('height', eventHeight)
      .attr('fill', color)
      .attr('fill-opacity', 0.4)
      .attr('rx', 3);

    const leaderLine = evtG.append('line')
      .attr('class', 'leader')
      .attr('y1', 0)
      .attr('y2', eventHeight)
      .attr('stroke', color)
      .attr('stroke-width', 2.5);

    evtG.append('text')
      .attr('class', 'event-label')
      .attr('x', 0)
      .attr('y', -6)
      .attr('text-anchor', 'start')
      .attr('font-size', '13px')
      .attr('font-weight', '600')
      .attr('fill', 'var(--text-normal, #222222)')
      .text(stripWikilinks(evt.title));

    let colsGSelection: d3.Selection<SVGGElement, any, null, undefined> | null = null;
    if (evt.collections.length > 0) {
      colsGSelection = evtG.append('g').attr('class', 'collections') as any;
    }

    const gNode = evtG.node() as SVGGElement;
    const rectBarNode = rectBar.node() as SVGRectElement;
    const leaderLineNode = leaderLine.node() as SVGLineElement;
    const colsGNode = colsGSelection ? (colsGSelection.node() as SVGGElement) : null;

    const groupWithRefs = gNode as SVGGroupElementWithRefs;
    groupWithRefs.__rectBar = rectBarNode;
    groupWithRefs.__leaderLine = leaderLineNode;
    groupWithRefs.__colsG = colsGNode;
    groupWithRefs.__colsGSelection = colsGSelection;

    const baseXStart = timeScale(evt.startDate);
    const baseXEnd = timeScale(evt.endDate);
    const initialBarWidth = Math.max(3, baseXEnd - baseXStart);

    let initialIsCollapsed: boolean | undefined = undefined;
    if (evt.collections.length > 0 && colsGNode && colsGSelection) {
      colsGNode.setAttribute('transform', `translate(${initialBarWidth}, 0)`);
      const requiredWidth = evt.collections.length * circleRadius * 2.3;
      initialIsCollapsed = evt.collections.length > 1 && initialBarWidth < requiredWidth + 10;
      renderCollectionsNode(
        colsGSelection,
        evt,
        initialBarWidth,
        circleRadius,
        eventHeight,
        color,
        activeCat,
        showTooltip,
        hideTooltip
      );
    }

    eventNodeList[evtIdx] = {
      gNode,
      evt,
      rectBarNode,
      leaderLineNode,
      colsGNode,
      colsGSelection,
      yPos,
      color,
      isHidden: false,
      baseXStart,
      baseXEnd,
      lastIsCollapsed: initialIsCollapsed,
    };

    evtG.on('mouseenter', (event: MouseEvent) => {
      rectBarNode?.setAttribute('fill-opacity', '0.7');

      const startStr = formatDisplayDate(evt.startDate);
      const endStr = evt.isOngoing ? 'Present' : formatDisplayDate(evt.endDate);
      showTooltip(event, evt.title, {
        categoryLabel: activeCat,
        categoryValue: evt.categoryVal,
        categoryColor: color,
        dateRange: `${startStr} – ${endStr}`,
      });
    })
    .on('mousemove', (event: MouseEvent) => {
      positionTooltip(event.clientX, event.clientY);
    })
    .on('mouseleave', () => {
      rectBarNode?.setAttribute('fill-opacity', '0.4');
      hideTooltip();
    });
  }

  let zoomRafId: number | null = null;
  let pendingTransform: d3.ZoomTransform | null = null;
  let lastK = -1;
  let isNowVisible = true;
  const baseNowX = hasOngoingEvent ? timeScale(now) : 0;

  const performZoomUpdate = (transform: d3.ZoomTransform) => {
    zoomRafId = null;
    const k = transform.k;
    const tx = transform.x;
    const isKChanged = Math.abs(k - lastK) > 1e-6;
    lastK = k;

    activeScaleX = transform.rescaleX(timeScale);
    const currentTicks = getOptimalTicks();
    const currentGridTicks = Math.max(currentTicks * 2, Math.floor(innerWidth / 45));

    updateActiveTickFormatter(currentTicks);

    timeAxisTop.scale(activeScaleX).ticks(currentTicks);
    timeAxisBottom.scale(activeScaleX).ticks(currentTicks);
    timeGrid.scale(activeScaleX).ticks(currentGridTicks);

    axisTopG.call(timeAxisTop);
    axisBottomG.call(timeAxisBottom);
    gridG.call(timeGrid);

    preventTickOverlap(axisTopG.node());
    preventTickOverlap(axisBottomG.node());

    if (nowG && nowLineNode && nowLabelNode) {
      const nowX = k * baseNowX + tx;
      if (nowX >= 0 && nowX <= innerWidth) {
        if (!isNowVisible) {
          nowG.attr('display', null);
          isNowVisible = true;
        }
        const targetXStr = String(margin.left + nowX);
        nowLineNode.setAttribute('x1', targetXStr);
        nowLineNode.setAttribute('x2', targetXStr);
        nowLabelNode.setAttribute('x', targetXStr);
      } else {
        if (isNowVisible) {
          nowG.attr('display', 'none');
          isNowVisible = false;
        }
      }
    }

    for (let i = 0; i < eventNodeList.length; i++) {
      const item = eventNodeList[i];
      const evt = item.evt;

      const xStart = k * item.baseXStart + tx;
      const xEnd = k * item.baseXEnd + tx;

      if (xEnd < -50 || xStart > innerWidth + 50) {
        if (!item.isHidden) {
          item.gNode.setAttribute('display', 'none');
          item.isHidden = true;
        }
        continue;
      }

      if (item.isHidden) {
        item.gNode.removeAttribute('display');
        item.isHidden = false;
      }

      item.gNode.setAttribute('transform', `translate(${xStart},${item.yPos})`);

      if (isKChanged) {
        const barWidth = Math.max(3, xEnd - xStart);
        const barWidthStr = String(barWidth);
        item.rectBarNode.setAttribute('width', barWidthStr);
        item.leaderLineNode.setAttribute('x1', barWidthStr);
        item.leaderLineNode.setAttribute('x2', barWidthStr);

        if (evt.collections.length > 0 && item.colsGNode && item.colsGSelection) {
          item.colsGNode.setAttribute('transform', `translate(${barWidth}, 0)`);
          const requiredWidth = evt.collections.length * circleRadius * 2.3;
          const isCollapsed = evt.collections.length > 1 && barWidth < requiredWidth + 10;
          if (item.lastIsCollapsed !== isCollapsed) {
            item.lastIsCollapsed = isCollapsed;
            renderCollectionsNode(item.colsGSelection, evt, barWidth, circleRadius, eventHeight, item.color, activeCat, showTooltip, hideTooltip);
          }
        }
      }
    }
  };

  const updateZoom = (transform: d3.ZoomTransform) => {
    pendingTransform = transform;
    if (zoomRafId === null) {
      if (typeof window !== 'undefined' && typeof window.requestAnimationFrame !== 'undefined') {
        zoomRafId = window.requestAnimationFrame(() => {
          const t = pendingTransform;
          zoomRafId = null;
          pendingTransform = null;
          if (t) performZoomUpdate(t);
        });
      } else {
        performZoomUpdate(transform);
      }
    }
  };

  const zoom = d3.zoom<SVGSVGElement, unknown>()
    .extent([[0, 0], [width, height]])
    .scaleExtent([0.2, 12])
    .on('start', () => {
      svg.classList.add('is-zooming');
      eventsG.style('pointer-events', 'none');
      needleG.style('display', 'none');
      hideTooltip(true);
    })
    .on('zoom', ({ transform }) => {
      updateZoom(transform);
    })
    .on('end', () => {
      svg.classList.remove('is-zooming');
      eventsG.style('pointer-events', null);
    });

  d3Svg.call(zoom);
  updateZoom(d3.zoomIdentity);
}

import {
  parseTimelineConfig,
  parseMarkdownTableRows,
  mapRawRowsToTimelineData,
  type ParsedTimelineData,
} from './timelineParser';
import { parseCsvOrTsv } from './tabularDataParser';
import { createCustomFetch } from './customFetch';

export async function resolveTimelineData(
  code: string,
  ctx?: any,
  app?: any
): Promise<ParsedTimelineData> {
  const config = parseTimelineConfig(code);

  if (config.events && config.events.length > 0) {
    return {
      events: config.events,
      categories: config.categories || ['category'],
      activeCategory: config.activeCategory || config.categories?.[0] || 'category',
    };
  }

  let obsidianModule: any = null;
  if (typeof require === 'function') {
    try {
      obsidianModule = require('obsidian');
    } catch {
      /* ignore */
    }
  }

  const customFetch = createCustomFetch(app, obsidianModule, ctx?.sourcePath || '');

  let rawRows: Record<string, any>[] = [];

  if (config.data) {
    const res = await customFetch(config.data);
    const text = await res.text();

    const trimmedText = text.trim();
    if (trimmedText.startsWith('[') || trimmedText.startsWith('{')) {
      try {
        const json = JSON.parse(trimmedText);
        rawRows = Array.isArray(json) ? json : [json];
      } catch {
        rawRows = parseCsvOrTsv(text);
      }
    } else {
      rawRows = parseCsvOrTsv(text);
    }
  } else if (config.id) {
    const rawId = config.id.trim();
    let fileRef = '';
    let cleanId = rawId;

    if (rawId.includes('#')) {
      const parts = rawId.split('#');
      fileRef = parts[0].trim();
      cleanId = parts[1].trim().replace(/^\^/, '');
    } else {
      cleanId = rawId.replace(/^\^/, '');
    }
    const caretId = '^' + cleanId;

    let targetFile: any = null;

    if (app) {
      if (fileRef) {
        if (app.metadataCache?.getFirstLinkpathDest) {
          targetFile = app.metadataCache.getFirstLinkpathDest(fileRef, ctx?.sourcePath || '');
        }
        if (!targetFile && app.vault?.getAbstractFileByPath) {
          targetFile = app.vault.getAbstractFileByPath(fileRef.endsWith('.md') ? fileRef : `${fileRef}.md`);
        }
      } else if (app.workspace) {
        targetFile = app.workspace.getActiveFile?.() || null;
        if (ctx?.sourcePath && app.vault?.getAbstractFileByPath) {
          targetFile = app.vault.getAbstractFileByPath(ctx.sourcePath) || targetFile;
        }
      }
    }

    if (targetFile && app?.vault?.cachedRead) {
      const fullText = await app.vault.cachedRead(targetFile);

      let blockText: string;
      const fileCache = app.metadataCache?.getFileCache?.(targetFile);

      let pos: any = undefined;
      if (fileCache?.blocks) {
        const exactBlock = fileCache.blocks[cleanId] ?? fileCache.blocks[caretId];
        if (exactBlock) {
          pos = exactBlock.position;
        } else {
          const cleanLower = cleanId.toLowerCase();
          for (const k in fileCache.blocks) {
            if (k.toLowerCase() === cleanLower) {
              pos = fileCache.blocks[k]?.position;
              break;
            }
          }
        }
      }

      if (pos) {
        blockText = fullText.substring(pos.start.offset, pos.end.offset);
      } else {
        const lines = fullText.split(/\r?\n/);
        const blockIdx = lines.findIndex((l: string) => l.trim() === caretId || l.trim() === `^${cleanId}`);
        if (blockIdx > 0) {
          let startIdx = blockIdx - 1;
          while (startIdx >= 0 && lines[startIdx].trim().includes('|')) {
            startIdx--;
          }
          blockText = lines.slice(startIdx + 1, blockIdx + 1).join('\n');
        } else {
          blockText = fullText;
        }
      }

      rawRows = parseMarkdownTableRows(blockText);
    } else if (code.includes('|')) {
      rawRows = parseMarkdownTableRows(code);
    }

    if (rawRows.length === 0) {
      throw new Error(`Referenced block ID '${config.id}' not found in ${targetFile ? targetFile.path : 'vault'}`);
    }
  }

  if (rawRows.length === 0) {
    throw new Error('Unable to resolve timeline dataset');
  }

  return mapRawRowsToTimelineData(rawRows, config.schemas);
}

const SVG_NS = 'http://www.w3.org/2000/svg';

export function createTlSvgIcon(
  attrs: Record<string, string>,
  children: Array<{ tag: string; attrs: Record<string, string> }>
): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('xmlns', SVG_NS);
  for (const [k, v] of Object.entries(attrs)) {
    svg.setAttribute(k, v);
  }
  for (const child of children) {
    const el = document.createElementNS(SVG_NS, child.tag);
    for (const [k, v] of Object.entries(child.attrs)) {
      el.setAttribute(k, v);
    }
    svg.appendChild(el);
  }
  return svg;
}

