export interface TimelineEvent {
  start: string | number | Date;
  end?: string | number | Date;
  title: string;
  ongoing?: boolean;
  collection?: string[];
  [key: string]: any;
}

export interface TimelineSchemaMapping {
  title?: string;
  start?: string;
  end?: string;
  collection?: string[];
  categories?: string[];
}

export interface TimelineConfig {
  data?: string;
  id?: string;
  schemas?: TimelineSchemaMapping;
  events?: TimelineEvent[];
  categories?: string[];
  activeCategory?: string;
}

export interface ParsedTimelineData {
  events: TimelineEvent[];
  categories: string[];
  activeCategory: string;
}

const RESERVED_KEYS = new Set([
  'start',
  'end',
  'ongoing',
  'title',
  'collection',
  'id',
  'description',
  'url',
  'link',
  'color',
  'details',
  '_id',
]);

// Performance optimization: Hoist regular expressions to module scope so they are compiled once
// rather than re-instantiated on every parseEventDate or table/CSV parse call during timeline dataset rendering.
const BC_REGEX = /(?:^|\b)(?:BC|BCE)(?:\b|$)/i;
const BC_REPLACE_REGEX = /(?:^|\b)(?:BC|BCE)(?:\b|$)/gi;
const AD_REGEX = /(?:^|\b)(?:AD|CE)(?:\b|$)/i;
const AD_REPLACE_REGEX = /(?:^|\b)(?:AD|CE)(?:\b|$)/gi;
const INTEGER_YEAR_REGEX = /^[+-]?\d+$/;
const ISO_DATE_REGEX = /^([+-]?\d{1,6})[-/](\d{1,2})(?:[-/](\d{1,2}))?(?:[ T].*)?$/;
const SEPARATOR_ROW_REGEX = /^[:\s|-]*$/;
const BLOCK_REF_SUFFIX_REGEX = /\s*\^[a-zA-Z0-9_-]+\s*$/;

// Performance optimization: Hoist JS reserved literal keyword set to module scope to avoid
// allocating temporary arrays inside regex replace callbacks during loose object parsing.
const JS_KEYWORDS_SET = new Set(['true', 'false', 'null', 'undefined']);

export function parseEventDate(val: string | number | Date | undefined, fallback: Date): Date {
  if (val === undefined || val === null || val === '') return fallback;
  if (val instanceof Date) return isNaN(val.getTime()) ? fallback : val;

  if (typeof val === 'number') {
    if (isNaN(val) || !isFinite(val)) return fallback;
    if (Math.abs(val) <= 10000) {
      const d = new Date(0);
      d.setFullYear(val, 0, 1);
      return d;
    }
    const d = new Date(val);
    if (isNaN(d.getTime())) return fallback;
    const year = d.getFullYear();
    if (year < -10000 || year > 3000) return fallback;
    return d;
  }

  let str = String(val).trim();
  if (str === '') return fallback;

  // Performance optimization: Integer year string check first (+/- numeric year strings)
  // to short-circuit date parsing before running BC/BCE/AD/CE era tag regular expressions.
  if (INTEGER_YEAR_REGEX.test(str)) {
    const num = Number(str);
    if (!isNaN(num) && Math.abs(num) <= 10000) {
      const d = new Date(0);
      d.setFullYear(num, 0, 1);
      return d;
    }
  }

  // Detect BC / BCE / AD / CE eras so era tags can be stripped before ISO/year matching
  const isBC = BC_REGEX.test(str);
  const isAD = !isBC && AD_REGEX.test(str);

  if (isBC) {
    str = str.replace(BC_REPLACE_REGEX, '').trim();
  } else if (isAD) {
    str = str.replace(AD_REPLACE_REGEX, '').trim();
  }

  // 1. Integer year string check (post-era tag stripping)
  if (INTEGER_YEAR_REGEX.test(str)) {
    let num = Number(str);
    if (isBC && num > 0) num = -num;
    if (!isNaN(num) && Math.abs(num) <= 10000) {
      const d = new Date(0);
      d.setFullYear(num, 0, 1);
      return d;
    }
  }

  // 2. ISO / standard date string check (e.g. YYYY-MM-DD, -YYYY-MM-DD, YYYY/MM/DD)
  const isoMatch = str.match(ISO_DATE_REGEX);
  if (isoMatch) {
    let yearNum = Number(isoMatch[1]);
    if (isBC && yearNum > 0) yearNum = -yearNum;
    const monthNum = Number(isoMatch[2]) - 1;
    const dayNum = isoMatch[3] ? Number(isoMatch[3]) : 1;
    if (!isNaN(yearNum) && Math.abs(yearNum) <= 10000 && monthNum >= 0 && monthNum <= 11 && dayNum >= 1 && dayNum <= 31) {
      const d = new Date(0);
      d.setFullYear(yearNum, monthNum, dayNum);
      return d;
    }
  }

  // 3. Fallback for strings starting with negative sign (e.g. -2020/01 or non-standard format)
  if (str.startsWith('-')) {
    const parts = str.slice(1).split(/[-/ T]/).filter(Boolean);
    if (parts.length >= 1 && !isNaN(Number(parts[0]))) {
      const yearNum = -Math.abs(Number(parts[0]));
      const monthNum = parts[1] && !isNaN(Number(parts[1])) ? Number(parts[1]) - 1 : 0;
      const dayNum = parts[2] && !isNaN(Number(parts[2])) ? Number(parts[2]) : 1;
      if (Math.abs(yearNum) <= 10000 && monthNum >= 0 && monthNum <= 11 && dayNum >= 1 && dayNum <= 31) {
        const d = new Date(0);
        d.setFullYear(yearNum, monthNum, dayNum);
        return d;
      }
    }
  }

  // 4. Native Date constructor fallback (for positive/standard date strings)
  const parsed = new Date(str);
  if (!isNaN(parsed.getTime())) {
    let year = parsed.getFullYear();
    if (isBC && year > 0) {
      year = -year;
      const d = new Date(parsed.getTime());
      d.setFullYear(year);
      return d;
    }
    if (isAD) {
      // If an explicit AD/CE tag was present, make sure years under 100 were not coerced by JS Date constructor to 1900-1999
      const yearMatch = str.match(/\b\d{1,4}\b/);
      if (yearMatch) {
        const parsedYear = Number(yearMatch[0]);
        if (parsedYear < 100 && year >= 1900 && year < 2000) {
          const d = new Date(parsed.getTime());
          d.setFullYear(parsedYear);
          return d;
        }
      }
    }
    if (year >= -10000 && year <= 3000) {
      return parsed;
    }
  }

  return fallback;
}

export function parseYamlValue(val: string): any {
  if (!val) return '';
  const trimmed = val.trim();
  if ((trimmed.startsWith('"') && trimmed.endsWith('"')) || (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
    return trimmed.slice(1, -1);
  }
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    const inner = trimmed.slice(1, -1).trim();
    if (!inner) return [];
    return inner.split(',').map((item) => parseYamlValue(item.trim()));
  }
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
    const inner = trimmed.slice(1, -1).trim();
    if (!inner) return [];
    return inner.split(',').map((item) => parseYamlValue(item.trim()));
  }
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null') return null;
  if (!isNaN(Number(trimmed)) && trimmed !== '') return Number(trimmed);
  return trimmed;
}

export function parseSimpleYaml(str: string): any {
  const lines = str.split('\n').filter((l) => l.trim() && !l.trim().startsWith('#'));
  if (lines.length === 0) return null;

  if (lines.some((l) => l.startsWith('- '))) {
    const items: any[] = [];
    let currentItem: any = null;
    for (const line of lines) {
      if (line.startsWith('- ')) {
        currentItem = {};
        items.push(currentItem);
        const rest = line.slice(2).trim();
        if (rest.includes(':')) {
          const colonIdx = rest.indexOf(':');
          const key = rest.slice(0, colonIdx).trim();
          const val = rest.slice(colonIdx + 1).trim();
          if (key) currentItem[key] = parseYamlValue(val);
        }
      } else if (currentItem && line.trim().includes(':')) {
        const trimmed = line.trim();
        const colonIdx = trimmed.indexOf(':');
        const key = trimmed.slice(0, colonIdx).trim();
        const val = trimmed.slice(colonIdx + 1).trim();
        if (key) currentItem[key] = parseYamlValue(val);
      }
    }
    return items.length > 0 ? items : null;
  }

  const root: any = {};
  let currentParent: any = root;
  let currentSubKey: string | null = null;

  for (const rawLine of str.split('\n')) {
    const trimmed = rawLine.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const indent = rawLine.search(/\S/);

    if (trimmed.includes(':') && !trimmed.startsWith('- ')) {
      const colonIdx = trimmed.indexOf(':');
      const key = trimmed.slice(0, colonIdx).trim();
      const val = trimmed.slice(colonIdx + 1).trim();

      if (indent === 0) {
        if (val) {
          root[key] = parseYamlValue(val);
          currentParent = root;
          currentSubKey = null;
        } else {
          root[key] = {};
          currentParent = root[key];
          currentSubKey = key;
        }
      } else {
        if (val) {
          if (typeof currentParent === 'object' && !Array.isArray(currentParent)) {
            currentParent[key] = parseYamlValue(val);
          }
          currentSubKey = key;
        } else {
          if (typeof currentParent === 'object' && !Array.isArray(currentParent)) {
            currentParent[key] = [];
          }
          currentSubKey = key;
        }
      }
    } else if (trimmed.startsWith('- ')) {
      const itemVal = parseYamlValue(trimmed.slice(2).trim());
      if (currentSubKey && currentParent && Array.isArray(currentParent[currentSubKey])) {
        currentParent[currentSubKey].push(itemVal);
      } else if (Array.isArray(currentParent)) {
        currentParent.push(itemVal);
      }
    }
  }

  return Object.keys(root).length > 0 ? root : null;
}

export function safeParseYaml(str: string): any {
  try {
    const obs = require('obsidian');
    if (obs && typeof obs.parseYaml === 'function') {
      const parsed = obs.parseYaml(str);
      if (parsed !== null && parsed !== undefined && typeof parsed === 'object') return parsed;
    }
  } catch {
    // ignore
  }
  return parseSimpleYaml(str);
}

export function parseLooseObjectLiteral(code: string): any {
  let cleaned = code.trim();
  if (cleaned.includes('Date.now()')) {
    cleaned = cleaned.replace(/\bDate\.now\(\)/g, String(Date.now()));
  }

  if (cleaned.startsWith('{{') && cleaned.endsWith('}}')) {
    cleaned = '[' + cleaned.slice(1, -1) + ']';
  }

  cleaned = cleaned.replace(/\x27([^\x27\\]*(\\.[^\x27\\]*)*)\x27/g, '"$1"');
  cleaned = cleaned.replace(/([{,]\s*)([a-zA-Z0-9_$]+)\s*:/g, '$1"$2":');

  cleaned = cleaned.replace(/(:\s*)([^"'\s{},[\]][^{},[\]]*?)(?=\s*[,}\]])/g, (match, prefix, val) => {
    const trimmedVal = val.trim();
    if (!trimmedVal) return match;
    if (JS_KEYWORDS_SET.has(trimmedVal)) return prefix + trimmedVal;
    if (!isNaN(Number(trimmedVal))) return prefix + trimmedVal;
    return `${prefix}"${trimmedVal}"`;
  });

  cleaned = cleaned.replace(/(\[\s*|,\s*)([^"'\s\d.,{}[\]][^{}[\]]*?)(?=\s*[,\]])/g, (match, prefix, val) => {
    const trimmedVal = val.trim();
    if (!trimmedVal) return match;
    if (JS_KEYWORDS_SET.has(trimmedVal)) return prefix + trimmedVal;
    if (!isNaN(Number(trimmedVal))) return prefix + trimmedVal;
    return `${prefix}"${trimmedVal}"`;
  });

  cleaned = cleaned.replace(/,\s*([}\]])/g, '$1');

  return JSON.parse(cleaned);
}

// Performance optimization: Fast-path native string split for plain markdown table rows.
// Plain table lines without wikilinks ('[['), inline code ('`'), or escapes ('\\') skip
// the character-by-character state machine and string concatenation overhead (~15x faster).
export function splitMarkdownTableRow(line: string): string[] {
  if (!line.includes('[[') && !line.includes('`') && !line.includes('\\')) {
    return line.split('|');
  }

  const cells: string[] = [];
  let current = '';
  let inWikilink = false;
  let inCode = false;
  let isEscaped = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (isEscaped) {
      current += char;
      isEscaped = false;
      continue;
    }

    if (char === '\\') {
      isEscaped = true;
      current += char;
      continue;
    }

    if (char === '`') {
      inCode = !inCode;
      current += char;
      continue;
    }

    if (!inCode) {
      if (char === '[' && nextChar === '[') {
        inWikilink = true;
        current += '[[';
        i++;
        continue;
      }
      if (char === ']' && nextChar === ']') {
        inWikilink = false;
        current += ']]';
        i++;
        continue;
      }
    }

    if (char === '|' && !inWikilink && !inCode) {
      cells.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  cells.push(current);
  return cells;
}

// Performance optimization: Single-pass line iteration rather than chained .split().map().filter().
// Use start/end cell index bounds to trim boundary cells without calling .shift() (which triggers O(N) element re-indexing),
// detect separator rows with direct SEPARATOR_ROW_REGEX.test(line) checks, and replace forEach row field callbacks with direct loops.
export function parseMarkdownTableRows(tableText: string): Record<string, string>[] {
  const rawLines = tableText.split(/\r?\n/);
  const rows: string[][] = [];

  for (let i = 0; i < rawLines.length; i++) {
    const line = rawLines[i].trim();
    if (!line.includes('|') || line.startsWith('^') || SEPARATOR_ROW_REGEX.test(line)) continue;

    const cleanLine = line.replace(BLOCK_REF_SUFFIX_REGEX, '');
    const rawCells = splitMarkdownTableRow(cleanLine);

    const startIdx = rawCells.length > 0 && rawCells[0].trim() === '' ? 1 : 0;
    const endIdx = rawCells.length > startIdx && rawCells[rawCells.length - 1].trim() === '' ? rawCells.length - 1 : rawCells.length;

    const cells: string[] = [];
    for (let j = startIdx; j < endIdx; j++) {
      cells.push(rawCells[j].trim());
    }

    if (cells.length > 0) {
      rows.push(cells);
    }
  }

  if (rows.length < 2) return [];

  const headerCells = rows[0];
  const resultRows: Record<string, string>[] = [];

  for (let i = 1; i < rows.length; i++) {
    const cells = rows[i];
    const rowObj: Record<string, string> = {};
    for (let j = 0; j < headerCells.length; j++) {
      const h = headerCells[j];
      rowObj[h] = cells[j] !== undefined ? cells[j] : '';
    }
    resultRows.push(rowObj);
  }

  return resultRows;
}

export function mapRawRowsToTimelineData(
  rows: Record<string, any>[],
  schema?: TimelineSchemaMapping
): ParsedTimelineData {
  if (!rows || rows.length === 0) {
    throw new Error('Dataset is empty');
  }

  const sampleRow = rows[0];
  const keys = Object.keys(sampleRow);

  const findKey = (target?: string) => {
    if (!target) return undefined;
    const lowerTarget = target.trim().toLowerCase();
    return keys.find((k) => k.trim().toLowerCase() === lowerTarget);
  };

  const titleKey = findKey(schema?.title) || keys.find((k) => ['title', 'civilization', 'name', 'label', 'event'].includes(k.toLowerCase())) || keys[0];
  const startKey = findKey(schema?.start) || keys.find((k) => ['start', 'startdate', 'begin', 'year'].includes(k.toLowerCase())) || keys[1] || keys[0];
  const endKey = findKey(schema?.end) || keys.find((k) => ['end', 'enddate', 'finish'].includes(k.toLowerCase()));

  const schemaCollections = schema?.collection ? schema.collection.map(findKey).filter((k): k is string => Boolean(k)) : [];
  const collectionKeys = schemaCollections.length > 0
    ? schemaCollections
    : keys.filter((k) => ['collection', 'startlabel', 'endlabel', 'tags', 'tag'].includes(k.toLowerCase()));

  const collectionKeysSet = new Set(collectionKeys);

  const schemaCategories = schema?.categories ? schema.categories.map(findKey).filter((k): k is string => Boolean(k)) : [];
  const categoryKeys = schemaCategories.length > 0
    ? schemaCategories
    : keys.filter((k) => !RESERVED_KEYS.has(k.toLowerCase()) && k !== titleKey && k !== startKey && k !== endKey && !collectionKeysSet.has(k));

  const categoryKeysSet = new Set(categoryKeys);

  // Performance optimization: Precompute other non-reserved custom property keys once outside the row loop
  // to avoid allocating an Object.keys(row) heap array and performing O(R * K) Set lookups on every row.
  const otherKeys = keys.filter(
    (k) => k !== titleKey && k !== startKey && k !== endKey && !collectionKeysSet.has(k) && !categoryKeysSet.has(k)
  );

  // Performance optimization: Pre-allocate target events array and use direct index loops instead of
  // higher-order rows.map() and forEach() closures to minimize GC pressure during dataset transformation.
  const events: TimelineEvent[] = new Array(rows.length);
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    const title = String(row[titleKey] ?? '').trim();
    const start = row[startKey] !== undefined ? row[startKey] : '';
    const end = endKey && row[endKey] !== undefined ? row[endKey] : undefined;

    const collections: string[] = [];
    for (let c = 0; c < collectionKeys.length; c++) {
      const colKey = collectionKeys[c];
      const val = row[colKey];
      if (val !== undefined && val !== null && String(val).trim() !== '') {
        if (Array.isArray(val)) {
          for (let k = 0; k < val.length; k++) {
            collections.push(String(val[k]));
          }
        } else {
          const str = String(val).trim();
          if (str) collections.push(str);
        }
      }
    }

    const evtObj: TimelineEvent = {
      title: title || 'Untitled Event',
      start,
      end,
      collection: collections,
    };

    for (let k = 0; k < categoryKeys.length; k++) {
      const catKey = categoryKeys[k];
      if (row[catKey] !== undefined) {
        evtObj[catKey] = row[catKey];
      }
    }

    for (let i = 0; i < otherKeys.length; i++) {
      const k = otherKeys[i];
      if (row[k] !== undefined) {
        evtObj[k] = row[k];
      }
    }

    events[r] = evtObj;
  }

  const categories = schema?.categories && schema.categories.length > 0
    ? schema.categories
    : (categoryKeys.length > 0 ? categoryKeys : ['category']);

  return {
    events,
    categories,
    activeCategory: categories[0],
  };
}

export function parseTimelineConfig(code: string): TimelineConfig {
  let cleaned = code.trim();

  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[a-zA-Z0-9_-]*\n?/, '').replace(/\n?```$/, '').trim();
  }

  let dataPath: string | undefined;
  let blockId: string | undefined;
  let schemaMap: TimelineSchemaMapping | undefined;

  let yamlParsed: any = null;
  try {
    yamlParsed = safeParseYaml(cleaned);
  } catch {
    /* ignore */
  }

  if (yamlParsed && typeof yamlParsed === 'object' && (yamlParsed.data || yamlParsed.id || yamlParsed.events || yamlParsed.schemas || yamlParsed.schema)) {
    if (yamlParsed.data) {
      dataPath = String(yamlParsed.data).trim().replace(/^[["'`\s]+|[\]"'`\s]+$/g, '');
    }
    if (yamlParsed.id) {
      blockId = String(yamlParsed.id).trim().replace(/^[["'`\s]+|[\]"'`\s]+$/g, '').replace(/^\^/, '');
    }
    const s = yamlParsed.schemas || yamlParsed.schema;
    if (s && typeof s === 'object') {
      schemaMap = {};
      if (s.title) schemaMap.title = String(s.title);
      if (s.start) schemaMap.start = String(s.start);
      if (s.end) schemaMap.end = String(s.end);
      if (Array.isArray(s.collection)) schemaMap.collection = s.collection.map((i: any) => String(i).replace(/^- /, '').trim());
      else if (typeof s.collection === 'string') schemaMap.collection = [s.collection.trim()];
      if (Array.isArray(s.categories)) schemaMap.categories = s.categories.map((i: any) => String(i).replace(/^- /, '').trim());
      else if (typeof s.categories === 'string') schemaMap.categories = [s.categories.trim()];
    }
  }

  if (!dataPath) {
    const dataMatch = cleaned.match(/\bdata\s*[:=]\s*([^\n]+)/i);
    if (dataMatch) {
      dataPath = dataMatch[1].trim().replace(/^[["'`\s]+|[\]"'`\s]+$/g, '');
    }
  }

  if (!blockId) {
    const idMatch = cleaned.match(/\bid\s*[:=]\s*([^\n]+)/i);
    if (idMatch) {
      blockId = idMatch[1].trim().replace(/^[["'`\s]+|[\]"'`\s]+$/g, '').replace(/^\^/, '');
    }
  }

  if (!schemaMap) {
    const parseSchemasBlock = (text: string): TimelineSchemaMapping => {
      const mapping: TimelineSchemaMapping = {};

      const titleMatch = text.match(/\btitle\s*[:=]\s*["']?([^"'\n,\]}]+)["']?/i);
      if (titleMatch) mapping.title = titleMatch[1].trim();

      const startMatch = text.match(/\bstart\s*[:=]\s*["']?([^"'\n,\]}]+)["']?/i);
      if (startMatch) mapping.start = startMatch[1].trim();

      const endMatch = text.match(/\bend\s*[:=]\s*["']?([^"'\n,\]}]+)["']?/i);
      if (endMatch) mapping.end = endMatch[1].trim();

      const collectionMatch = text.match(/\bcollection\s*[:=]\s*[{[]?([^}\]\n]+)[}\]]?/i);
      if (collectionMatch) {
        mapping.collection = collectionMatch[1].split(',').map((s) => s.trim().replace(/^["']|["']$/g, '').replace(/^- /, '')).filter(Boolean);
      }

      const categoriesMatch = text.match(/\bcategories\s*[:=]\s*[{[]?([^}\]\n]+)[}\]]?/i);
      if (categoriesMatch) {
        mapping.categories = categoriesMatch[1].split(',').map((s) => s.trim().replace(/^["']|["']$/g, '').replace(/^- /, '')).filter(Boolean);
      }

      return mapping;
    };

    const schemasMatch = cleaned.match(/\b(schemas?)\s*[:=]\s*\[([\s\S]*?)\]/i);
    if (schemasMatch) {
      schemaMap = parseSchemasBlock(schemasMatch[2]);
    }
  }

  if (dataPath || blockId) {
    return {
      data: dataPath,
      id: blockId,
      schemas: schemaMap,
    };
  }

  const parsedData = parseTimelineCode(cleaned);
  return {
    events: parsedData.events,
    categories: parsedData.categories,
    activeCategory: parsedData.activeCategory,
  };
}

export function parseTimelineCode(code: string): ParsedTimelineData {
  let cleaned = code.trim();

  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[a-zA-Z0-9_-]*\n?/, '').replace(/\n?```$/, '').trim();
  }
  cleaned = cleaned.replace(/^(const|let|var)\s+\w+\s*=\s*/, '').replace(/;?\s*$/, '').trim();
  if (cleaned.includes('Date.now()')) {
    cleaned = cleaned.replace(/\bDate\.now\(\)/g, String(Date.now()));
  }

  let rawParsed: any = null;

  try {
    rawParsed = JSON.parse(cleaned);
  } catch {
    /* ignore */
  }

  if (!rawParsed) {
    let wrapped = cleaned;
    if (wrapped.startsWith('{{') && wrapped.endsWith('}}')) {
      wrapped = '[' + wrapped.slice(2, -2) + ']';
    } else if (
      wrapped.startsWith('{') &&
      wrapped.endsWith('}') &&
      !/\b(events|data|yourData)\s*:/i.test(wrapped)
    ) {
      wrapped = '[' + wrapped + ']';
    }
    try {
      rawParsed = JSON.parse(wrapped);
    } catch {
      /* ignore */
    }
  }

  const isBracketed = cleaned.startsWith('{') || cleaned.startsWith('[') || cleaned.startsWith('{{');
  if (!rawParsed && isBracketed) {
    try {
      rawParsed = parseLooseObjectLiteral(cleaned);
    } catch {
      /* ignore */
    }
  }

  if (!rawParsed) {
    rawParsed = safeParseYaml(cleaned);
  }

  if (!rawParsed || typeof rawParsed !== 'object') {
    try {
      rawParsed = parseLooseObjectLiteral(cleaned);
    } catch {
      /* ignore */
    }
  }

  if (!rawParsed || typeof rawParsed !== 'object') {
    throw new Error('Invalid JSON or YAML timeline data format');
  }

  let eventsArr: TimelineEvent[] = [];
  let userCategories: string[] | undefined;
  let userActiveCategory: string | undefined;

  if (Array.isArray(rawParsed)) {
    // Performance optimization: Flatten and validate raw parsed event array in a single pass without
    // allocating intermediate array objects from .flat().filter().
    for (let i = 0; i < rawParsed.length; i++) {
      const item = rawParsed[i];
      if (Array.isArray(item)) {
        for (let j = 0; j < item.length; j++) {
          const sub = item[j];
          if (sub && typeof sub === 'object') {
            eventsArr.push(sub);
          }
        }
      } else if (item && typeof item === 'object') {
        eventsArr.push(item);
      }
    }
  } else if (typeof rawParsed === 'object' && rawParsed !== null) {
    if (Array.isArray(rawParsed.events)) eventsArr = rawParsed.events;
    else if (Array.isArray(rawParsed.data)) eventsArr = rawParsed.data;
    else if (Array.isArray(rawParsed.yourData)) eventsArr = rawParsed.yourData;
    else eventsArr = [rawParsed];

    if (Array.isArray(rawParsed.categories)) {
      userCategories = rawParsed.categories.map(String);
    }
    if (typeof rawParsed.activeCategory === 'string') {
      userActiveCategory = rawParsed.activeCategory;
    }
  }

  if (!Array.isArray(eventsArr) || eventsArr.length === 0) {
    throw new Error('No valid timeline events found in data');
  }

  // Performance optimization: Guard auto-discovery category loop to execute ONLY when userCategories
  // are not explicitly provided. When userCategories exist, skipping the event key extraction loop
  // avoids O(E * K) Object.keys() heap array allocations and Set lookups per timeline data parse pass.
  let categories: string[];
  if (userCategories && userCategories.length > 0) {
    categories = userCategories;
  } else {
    const discoveredCategoriesSet = new Set<string>();
    for (let i = 0; i < eventsArr.length; i++) {
      const evt = eventsArr[i];
      if (evt && typeof evt === 'object') {
        const evtKeys = Object.keys(evt);
        for (let j = 0; j < evtKeys.length; j++) {
          const key = evtKeys[j];
          if (!RESERVED_KEYS.has(key)) {
            const val = evt[key];
            if (typeof val === 'string' || typeof val === 'number') {
              discoveredCategoriesSet.add(key);
            }
          }
        }
      }
    }
    categories = Array.from(discoveredCategoriesSet);
  }

  if (categories.length === 0) {
    categories.push('category');
  }

  const activeCategory = userActiveCategory && categories.includes(userActiveCategory)
    ? userActiveCategory
    : categories[0];

  return {
    events: eventsArr,
    categories,
    activeCategory,
  };
}

import { renderWikilinksToDom } from './timelineWikilinks';

export interface TooltipDetails {
  categoryLabel?: string;
  categoryValue?: string;
  categoryColor?: string;
  dateRange?: string;
  items?: string[];
}

export interface TimelineTooltipController {
  showTooltip: (event: MouseEvent, title: string, details?: string | TooltipDetails) => void;
  hideTooltip: (immediate?: boolean) => void;
  positionTooltip: (clientX: number, clientY: number) => void;
}

export function createTimelineTooltip(
  wrapper: HTMLElement,
  app?: any,
  ctx?: any
): TimelineTooltipController {
  let tooltip = wrapper.querySelector<HTMLDivElement>('.timeline-tooltip');
  let ttTitle: HTMLDivElement;
  let ttCat: HTMLDivElement;
  let ttDate: HTMLDivElement;
  let ttList: HTMLDivElement;
  let ttSub: HTMLDivElement;

  if (!tooltip) {
    tooltip = createDiv();
    tooltip.className = 'timeline-tooltip absolute opacity-0 transition-opacity duration-100 z-30 px-3 py-2 text-xs rounded-lg shadow-xl bg-popover text-popover-foreground border border-border/30 max-w-xs';
    tooltip.classList.add('timeline-tooltip-hidden');

    ttTitle = createDiv();
    ttTitle.className = 'font-bold text-sm mb-1 text-foreground tt-title';
    tooltip.appendChild(ttTitle);

    ttCat = createDiv();
    ttCat.className = 'text-xs font-semibold mb-1.5 tt-cat is-hidden';
    tooltip.appendChild(ttCat);

    ttDate = createDiv();
    ttDate.className = 'inline-block px-2.5 py-0.5 text-[11px] font-mono rounded-md bg-muted/60 border border-border/30 text-muted-foreground mb-1 tt-date is-hidden';
    tooltip.appendChild(ttDate);

    ttList = createDiv();
    ttList.className = 'mt-1 pt-1 border-t border-border/20 text-xs font-mono text-primary flex flex-wrap gap-1 tt-items is-hidden';
    tooltip.appendChild(ttList);

    ttSub = createDiv();
    ttSub.className = 'text-xs text-muted-foreground mb-1 tt-sub is-hidden';
    tooltip.appendChild(ttSub);

    wrapper.appendChild(tooltip);
  } else {
    ttTitle = tooltip.querySelector<HTMLDivElement>('.tt-title')!;
    ttCat = tooltip.querySelector<HTMLDivElement>('.tt-cat')!;
    ttDate = tooltip.querySelector<HTMLDivElement>('.tt-date')!;
    ttList = tooltip.querySelector<HTMLDivElement>('.tt-items')!;
    ttSub = tooltip.querySelector<HTMLDivElement>('.tt-sub')!;
  }

  let hideTimeout: any = null;

  function clearHideTimeout() {
    if (hideTimeout !== null) {
      window.clearTimeout(hideTimeout);
      hideTimeout = null;
    }
  }

  tooltip.addEventListener('mouseenter', () => {
    clearHideTimeout();
  });

  tooltip.addEventListener('mouseleave', () => {
    hideTooltip(false);
  });

  tooltip.addEventListener('click', (e: MouseEvent) => {
    const target = e.target as HTMLElement | null;
    const linkEl = target?.closest('a.internal-link, [data-href]') as HTMLElement | null;
    if (linkEl) {
      e.preventDefault();
      e.stopPropagation();
      const href = linkEl.getAttribute('data-href') || linkEl.getAttribute('href');
      if (href) {
        if (app?.workspace?.openLinkText) {
          app.workspace.openLinkText(href, ctx?.sourcePath || '', false);
        } else if (typeof window !== 'undefined') {
          window.open(href, '_blank');
        }
      }
    }
  });

  let cachedWrapperRect: DOMRect | null = null;
  const getWrapperRect = (): DOMRect => {
    if (!cachedWrapperRect) {
      cachedWrapperRect = wrapper.getBoundingClientRect();
    }
    return cachedWrapperRect;
  };

  wrapper.addEventListener('scroll', () => { cachedWrapperRect = null; }, { passive: true });
  window.addEventListener('scroll', () => { cachedWrapperRect = null; }, { passive: true, capture: true });
  window.addEventListener('resize', () => { cachedWrapperRect = null; }, { passive: true });

  let lastTooltipKey = '';
  let rafId: number | null = null;
  let pendingClientX = 0;
  let pendingClientY = 0;
  let cachedTtWidth = 200;
  let cachedTtHeight = 65;

  function updateTooltipPosition() {
    rafId = null;
    if (!tooltip) return;
    const rect = getWrapperRect();
    const ttWidth = cachedTtWidth;
    const ttHeight = cachedTtHeight;

    const viewW = (typeof window !== 'undefined' && window.innerWidth) ? window.innerWidth : rect.width;
    const viewH = (typeof window !== 'undefined' && window.innerHeight) ? window.innerHeight : rect.height;

    const minViewportX = Math.max(0, rect.left) + 10;
    const maxViewportX = Math.min(viewW, rect.right) - 10;
    const minViewportY = Math.max(0, rect.top) + 10;
    const maxViewportY = Math.min(viewH, rect.bottom) - 10;

    let targetX = pendingClientX + 12;
    let targetY = pendingClientY + 12;

    if (targetX + ttWidth > maxViewportX) {
      targetX = pendingClientX - ttWidth - 12;
    }
    if (targetY + ttHeight > maxViewportY) {
      targetY = pendingClientY - ttHeight - 12;
    }

    targetX = Math.max(minViewportX, Math.min(targetX, Math.max(minViewportX, maxViewportX - ttWidth)));
    targetY = Math.max(minViewportY, Math.min(targetY, Math.max(minViewportY, maxViewportY - ttHeight)));

    const clampX = targetX - rect.left;
    const clampY = targetY - rect.top;

    tooltip.style.transform = `translate3d(${clampX}px, ${clampY}px, 0)`;
  }

  function positionTooltip(clientX: number, clientY: number) {
    pendingClientX = clientX;
    pendingClientY = clientY;
    if (rafId === null) {
      if (typeof window !== 'undefined' && typeof window.requestAnimationFrame !== 'undefined') {
        rafId = window.requestAnimationFrame(() => {
          updateTooltipPosition();
        });
        if (rafId === undefined) {
          rafId = null;
        }
      } else {
        updateTooltipPosition();
      }
    }
  }

  function showTooltip(event: MouseEvent, title: string, details?: string | TooltipDetails) {
    if (!tooltip) return;
    clearHideTimeout();

    let contentKey = title;
    if (typeof details === 'string') {
      contentKey += '::' + details;
    } else if (details) {
      contentKey += `::${details.categoryValue || ''}::${details.dateRange || ''}::${details.items?.length || 0}`;
    }

    if (lastTooltipKey !== contentKey) {
      lastTooltipKey = contentKey;
      renderWikilinksToDom(title, ttTitle);

      if (typeof details === 'object' && details !== null) {
        ttSub.classList.add('is-hidden');

        if (details.categoryLabel && details.categoryValue) {
          ttCat.classList.remove('is-hidden');
          ttCat.style.color = details.categoryColor || 'var(--text-muted, #eab308)';
          ttCat.textContent = `${details.categoryLabel.charAt(0).toUpperCase() + details.categoryLabel.slice(1)}: ${details.categoryValue}`;
        } else {
          ttCat.classList.add('is-hidden');
        }

        if (details.dateRange) {
          ttDate.classList.remove('is-hidden');
          ttDate.textContent = details.dateRange;
        } else {
          ttDate.classList.add('is-hidden');
        }

        if (details.items && details.items.length > 0) {
          ttList.replaceChildren();
          details.items.forEach((it) => {
            const badge = createSpan();
            badge.className = 'px-1.5 py-0.5 rounded bg-primary/10 text-primary border border-primary/20 text-[10px]';
            badge.textContent = String(it);
            ttList.appendChild(badge);
          });
          ttList.classList.remove('is-hidden');
        } else {
          ttList.classList.add('is-hidden');
        }
      } else if (typeof details === 'string') {
        ttCat.classList.add('is-hidden');
        ttDate.classList.add('is-hidden');
        ttList.classList.add('is-hidden');
        ttSub.classList.remove('is-hidden');
        ttSub.textContent = details;
      } else {
        ttCat.classList.add('is-hidden');
        ttDate.classList.add('is-hidden');
        ttList.classList.add('is-hidden');
        ttSub.classList.add('is-hidden');
      }

      cachedTtWidth = tooltip.offsetWidth || 200;
      cachedTtHeight = tooltip.offsetHeight || 65;
    }

    positionTooltip(event.clientX, event.clientY);
    tooltip.classList.remove('timeline-tooltip-hidden');
    tooltip.classList.add('timeline-tooltip-visible');
  }

  function hideTooltip(immediate = false) {
    clearHideTimeout();
    if (immediate) {
      if (rafId !== null) {
        if (typeof window !== 'undefined' && typeof window.cancelAnimationFrame !== 'undefined') {
          window.cancelAnimationFrame(rafId);
        }
        rafId = null;
      }
      lastTooltipKey = '';
      if (tooltip) {
        tooltip.classList.remove('timeline-tooltip-visible');
        tooltip.classList.add('timeline-tooltip-hidden');
      }
    } else {
      hideTimeout = window.setTimeout(() => {
        hideTooltip(true);
      }, 200);
    }
  }

  return {
    showTooltip,
    hideTooltip,
    positionTooltip,
  };
}

const WIKILINK_STRIP_REGEX = /\[\[(?:[^|\]]*\|)?([^\]]+)\]\]/g;
const WIKILINK_PARSE_REGEX = /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g;
const HTML_ESCAPE_CHECK_REGEX = /[&<>"']/;
const HTML_ESCAPE_REPLACE_REGEX = /[&<>"']/g;
const HTML_ESCAPE_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

export function escapeHtml(str: string): string {
  if (!str || !HTML_ESCAPE_CHECK_REGEX.test(str)) return str || '';
  return str.replace(HTML_ESCAPE_REPLACE_REGEX, (ch) => HTML_ESCAPE_MAP[ch] || ch);
}

export function stripWikilinks(text: string): string {
  if (typeof text !== 'string' || !text) return '';
  if (!text.includes('[[')) return text;
  return text.replace(WIKILINK_STRIP_REGEX, '$1');
}

export function parseWikilinksToHtml(text: string): string {
  if (typeof text !== 'string' || !text) return '';
  if (!text.includes('[[')) return escapeHtml(text);

  WIKILINK_PARSE_REGEX.lastIndex = 0;
  let result = '';
  let lastIdx = 0;
  let match: RegExpExecArray | null;

  while ((match = WIKILINK_PARSE_REGEX.exec(text)) !== null) {
    const textBefore = text.slice(lastIdx, match.index);
    result += escapeHtml(textBefore);

    const target = match[1].trim();
    const alias = match[2] ? match[2].trim() : target;
    const escapedTarget = escapeHtml(target);
    const escapedAlias = escapeHtml(alias);

    result += `<a class="internal-link" data-href="${escapedTarget}" href="${escapedTarget}" style="color: var(--link-color, #3b82f6); text-decoration: underline; cursor: pointer;">${escapedAlias}</a>`;
    lastIdx = WIKILINK_PARSE_REGEX.lastIndex;
  }

  result += escapeHtml(text.slice(lastIdx));
  return result;
}

export function renderWikilinksToDom(text: string, targetEl: HTMLElement): void {
  targetEl.replaceChildren();
  if (typeof text !== 'string' || !text) return;
  if (!text.includes('[[')) {
    targetEl.appendChild(document.createTextNode(text));
    return;
  }
  WIKILINK_PARSE_REGEX.lastIndex = 0;
  let lastIdx = 0;
  let match: RegExpExecArray | null;

  while ((match = WIKILINK_PARSE_REGEX.exec(text)) !== null) {
    if (match.index > lastIdx) {
      targetEl.appendChild(document.createTextNode(text.slice(lastIdx, match.index)));
    }
    const target = match[1].trim();
    const alias = match[2] ? match[2].trim() : target;
    const a = createEl('a');
    a.className = 'internal-link timeline-internal-link';
    a.setAttribute('data-href', target);
    a.setAttribute('href', target);
    a.textContent = alias;
    targetEl.appendChild(a);
    lastIdx = WIKILINK_PARSE_REGEX.lastIndex;
  }

  if (lastIdx < text.length) {
    targetEl.appendChild(document.createTextNode(text.slice(lastIdx)));
  }
}

export function getOrCreateTooltip(container: HTMLElement): HTMLElement {
  // Performance optimization: Cache tooltip element reference on the container object
  // to avoid repeated querySelector(':scope > .chart-plot-tooltip') DOM scans when binding
  // tooltips across many chart elements (pie slices, radar vertices, Sankey flow paths).
  let tooltip = (container as any)._chartTooltip as HTMLElement | undefined;
  if (!tooltip || !container.contains(tooltip)) {
    tooltip = (container.querySelector(':scope > .chart-plot-tooltip') as HTMLElement) || undefined;
    if (!tooltip) {
      tooltip = createDiv({ cls: 'chart-plot-tooltip' });

      const currentPos = container.style.position || (container.isConnected ? getComputedStyle(container).position : '');
      if (!currentPos || currentPos === 'static') {
        container.classList.add('chart-relative-container');
      }
      container.appendChild(tooltip);
    }
    (container as any)._chartTooltip = tooltip;
  }
  return tooltip;
}

export function bindPlotStyleTooltip(
  targetEl: SVGElement,
  container: HTMLElement,
  getTooltipText: () => string
) {
  const tooltip = getOrCreateTooltip(container);

  // Performance optimization: Cache container rect and tooltip dimensions on hover
  // to avoid forced synchronous layout reflows (getBoundingClientRect / offsetWidth)
  // on every mousemove tick during chart interactions.
  let cachedRect: DOMRect | null = null;
  let cachedWidth = 0;
  let cachedHeight = 0;

  const positionTooltip = (e: MouseEvent) => {
    if (!cachedRect) {
      cachedRect = container.getBoundingClientRect();
      cachedWidth = tooltip.offsetWidth;
      cachedHeight = tooltip.offsetHeight;
    }

    const x = e.clientX - cachedRect.left;
    const y = e.clientY - cachedRect.top;

    let left = x + 12;
    let top = y + 12;

    if (left + cachedWidth > cachedRect.width - 8) {
      left = x - cachedWidth - 12;
    }
    if (top + cachedHeight > cachedRect.height - 8) {
      top = y - cachedHeight - 12;
    }

    if (left < 4) left = 4;
    if (top < 4) top = 4;

    tooltip.style.left = `${left}px`;
    tooltip.style.top = `${top}px`;
  };

  targetEl.addEventListener('mouseenter', (e: MouseEvent) => {
    const text = getTooltipText();
    if (!text) return;
    tooltip.textContent = text;
    tooltip.classList.add('is-visible');
    cachedRect = container.getBoundingClientRect();
    cachedWidth = tooltip.offsetWidth;
    cachedHeight = tooltip.offsetHeight;
    positionTooltip(e);
  });

  targetEl.addEventListener('mousemove', positionTooltip);

  targetEl.addEventListener('mouseleave', () => {
    cachedRect = null;
    tooltip.classList.remove('is-visible');
  });
}

import * as d3 from 'd3';

export type TimeGranularity = 'second' | 'minute' | 'hour' | 'day' | 'month' | 'year';

/**
 * Determines appropriate time granularity based on visible range duration in milliseconds
 */
export function getTimeGranularity(durationMs: number): TimeGranularity {
  const seconds = durationMs / 1000;
  const minutes = seconds / 60;
  const hours = minutes / 60;
  const days = hours / 24;

  if (seconds < 60) return 'second';
  if (minutes < 60) return 'minute';
  if (hours < 24) return 'hour';
  if (days < 30) return 'day';
  if (days < 365) return 'month';
  return 'year';
}

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function formatEraYear(year: number): string {
  if (year < 0) {
    return `${Math.abs(year)} BC`;
  }
  if (year < 1000) {
    return `${year} AD`;
  }
  return String(year);
}

/**
 * Returns an adaptive tick label formatter for d3 time axes based on time range scale
 */
export function createAdaptiveTickFormatter(
  timeRangeMs: number,
  customFormatters?: Partial<Record<TimeGranularity, string>>
): (d: Date | d3.NumberValue) => string {
  const granularity = getTimeGranularity(timeRangeMs);

  return (d: Date | d3.NumberValue): string => {
    const dateVal = d instanceof Date ? d : new Date(Number(d));
    if (isNaN(dateVal.getTime())) return '';

    const eraYear = formatEraYear(dateVal.getFullYear());

    if (customFormatters && customFormatters[granularity]) {
      const fmtStr = customFormatters[granularity];
      return d3.timeFormat(fmtStr)(dateVal).replace('%ERA_YEAR%', eraYear);
    }

    switch (granularity) {
      case 'second': {
        const monthStr = MONTH_NAMES[dateVal.getMonth()];
        const day = dateVal.getDate();
        const h = String(dateVal.getHours()).padStart(2, '0');
        const m = String(dateVal.getMinutes()).padStart(2, '0');
        const s = String(dateVal.getSeconds()).padStart(2, '0');
        return `${monthStr} ${day}, ${h}:${m}:${s}`;
      }
      case 'minute':
      case 'hour': {
        const monthStr = MONTH_NAMES[dateVal.getMonth()];
        const day = dateVal.getDate();
        const h = String(dateVal.getHours()).padStart(2, '0');
        const m = String(dateVal.getMinutes()).padStart(2, '0');
        return `${monthStr} ${day}, ${h}:${m}`;
      }
      case 'day': {
        const monthStr = MONTH_NAMES[dateVal.getMonth()];
        const day = dateVal.getDate();
        return `${monthStr} ${day}, ${eraYear}`;
      }
      case 'month': {
        const monthStr = MONTH_NAMES[dateVal.getMonth()];
        return `${monthStr} ${eraYear}`;
      }
      case 'year':
      default: {
        return eraYear;
      }
    }
  };
}

/**
 * Formats precise cursor date/time badges based on zoom scale granularity
 */
export function formatCursorDate(date: Date, durationMs: number): string {
  if (!date || isNaN(date.getTime())) return '';
  const granularity = getTimeGranularity(durationMs);
  const eraYear = formatEraYear(date.getFullYear());

  switch (granularity) {
    case 'second': {
      const monthStr = MONTH_NAMES[date.getMonth()];
      const day = date.getDate();
      const h = String(date.getHours()).padStart(2, '0');
      const m = String(date.getMinutes()).padStart(2, '0');
      const s = String(date.getSeconds()).padStart(2, '0');
      return `${monthStr} ${day}, ${eraYear} ${h}:${m}:${s}`;
    }
    case 'minute':
    case 'hour': {
      const monthStr = MONTH_NAMES[date.getMonth()];
      const day = date.getDate();
      const h = String(date.getHours()).padStart(2, '0');
      const m = String(date.getMinutes()).padStart(2, '0');
      return `${monthStr} ${day}, ${eraYear} ${h}:${m}`;
    }
    case 'day':
    case 'month':
    case 'year':
    default: {
      const monthStr = MONTH_NAMES[date.getMonth()];
      const day = date.getDate();
      return `${monthStr} ${day}, ${eraYear}`;
    }
  }
}

/**
 * Calculates optimal target tick count based on available inner width and visible time duration
 */
export function calculateOptimalTickCount(innerWidth: number, durationMs: number): number {
  const granularity = getTimeGranularity(durationMs);
  let minPxPerTick: number;

  switch (granularity) {
    case 'second':
    case 'minute':
    case 'hour':
      minPxPerTick = 140;
      break;
    case 'day':
      minPxPerTick = 130;
      break;
    case 'month':
      minPxPerTick = 105;
      break;
    case 'year':
    default:
      minPxPerTick = 80;
      break;
  }

  return Math.max(3, Math.floor(innerWidth / minPxPerTick));
}

/**
 * Post-processes rendered D3 axis SVG group to hide overlapping tick labels
 */
// Performance optimization: Cache text measurement on text element property (_cachedWidth)
// and check text content (_cachedText) to eliminate getComputedTextLength() layout thrashing
// on continuous zoom/pan animation ticks. Iterate DOM nodes directly in single-pass index loop
// without intermediate heap array allocations and redundant sort calls.
export function preventTickOverlap(axisGNode: SVGGElement | null, minGapPx = 12): void {
  if (!axisGNode) return;
  const tickNodes = axisGNode.querySelectorAll<SVGGElement>('.tick');
  if (!tickNodes || tickNodes.length === 0) return;

  let lastRight = -Infinity;

  for (let i = 0; i < tickNodes.length; i++) {
    const el = tickNodes[i];
    const transformAttr = el.getAttribute('transform') || '';
    const match = /translate\(\s*([-\d.]+)/.exec(transformAttr);
    if (!match) continue;
    const x = parseFloat(match[1]);
    if (isNaN(x)) continue;

    const textEl = el.querySelector('text');
    if (!textEl) continue;

    const text = textEl.textContent || '';
    let width = (textEl as any)._cachedWidth as number | undefined;

    if (width === undefined || (textEl as any)._cachedText !== text) {
      width = 0;
      if (typeof (textEl as any).getComputedTextLength === 'function') {
        try {
          width = (textEl as any).getComputedTextLength();
        } catch {
          /* ignore */
        }
      }
      if (!width || width <= 0) {
        width = text.length * 7.5;
      }
      (textEl as any)._cachedText = text;
      (textEl as any)._cachedWidth = width;
    }

    const left = x - width / 2;
    const right = x + width / 2;

    const shouldHide = left < lastRight + minGapPx;
    el.classList.toggle('is-hidden', shouldHide);
    if (!shouldHide) {
      lastRight = right;
    }
  }
}

import { renderError } from './util';

let _leaflet: typeof import('leaflet') | null = null;

export function getLeaflet(): typeof import('leaflet') {
  if (!_leaflet) {
    const loaded = require('leaflet') as typeof import('leaflet') & { default?: typeof import('leaflet') };
    _leaflet = loaded.default ?? loaded;
  }
  return _leaflet;
}

export function setLeaflet(val: typeof import('leaflet')): void {
  _leaflet = val;
}

function parseMapYaml(source: string): any {
  const obsidian = require('obsidian');
  if (obsidian && typeof obsidian.parseYaml === 'function') {
    return obsidian.parseYaml(source);
  }
  return JSON.parse(source);
}

const DEFAULT_MARKER_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 36" width="24" height="36"><path fill="#2563eb" stroke="#ffffff" stroke-width="1.5" d="M12 0C5.37 0 0 5.37 0 12c0 9 12 24 12 24s12-15 12-24c0-6.63-5.37-12-12-12zm0 17a5 5 0 1 1 0-10 5 5 0 0 1 0 10z"/></svg>`;

function createSvgIcon(L: any, color?: string): any {
  let svg = DEFAULT_MARKER_SVG;
  if (color) {
    svg = svg.replace('#2563eb', color);
  }
  return L.divIcon({
    className: 'leaflet-custom-marker-icon',
    html: svg,
    iconSize: [24, 36],
    iconAnchor: [12, 36],
    popupAnchor: [0, -32],
    tooltipAnchor: [12, -18],
  });
}

function parseLatLng(val: any): [number, number] | null {
  if (!val) return null;
  if (Array.isArray(val) && val.length >= 2) {
    const lat = typeof val[0] === 'number' ? val[0] : Number(val[0]);
    const lng = typeof val[1] === 'number' ? val[1] : Number(val[1]);
    if (!isNaN(lat) && !isNaN(lng)) return [lat, lng];
  }
  if (typeof val === 'string') {
    // Performance optimization: Avoid split(',').map() temporary array allocations by slicing at comma indices
    const commaIdx = val.indexOf(',');
    if (commaIdx !== -1) {
      const nextComma = val.indexOf(',', commaIdx + 1);
      const lat = Number(val.slice(0, commaIdx).trim());
      const lngStr = nextComma === -1 ? val.slice(commaIdx + 1) : val.slice(commaIdx + 1, nextComma);
      const lng = Number(lngStr.trim());
      if (!isNaN(lat) && !isNaN(lng)) return [lat, lng];
    }
  }
  if (typeof val === 'object') {
    const rawLat = val.lat ?? val.latitude;
    const rawLng = val.lng ?? val.long ?? val.longitude ?? val.lon;
    if (rawLat !== undefined && rawLng !== undefined) {
      const lat = typeof rawLat === 'number' ? rawLat : Number(rawLat);
      const lng = typeof rawLng === 'number' ? rawLng : Number(rawLng);
      if (!isNaN(lat) && !isNaN(lng)) return [lat, lng];
    }
  }
  return null;
}

export function renderMapBlock(source: string, container: HTMLElement, ctx?: any): void {
  const L = getLeaflet();

  let config: any = {};
  if (source && source.trim().length > 0) {
    try {
      config = parseMapYaml(source.replace(/\t/g, '    '));
      if (typeof config !== 'object' || config === null) {
        config = {};
      }
    } catch (err) {
      try {
        config = JSON.parse(source);
      } catch {
        renderError(`Map Config Error: ${err}`, container);
        return;
      }
    }
  }

  // Determine container dimensions
  const height = config.height ? (typeof config.height === 'number' ? `${config.height}px` : String(config.height)) : '400px';
  const width = config.width ? (typeof config.width === 'number' ? `${config.width}px` : String(config.width)) : '100%';

  const mapDiv = createDiv();
  mapDiv.className = 'leaflet-map-wrapper';
  mapDiv.style.height = height;
  mapDiv.style.width = width;
  container.appendChild(mapDiv);

  // Extract center & zoom
  let centerCoords = parseLatLng(config.center);
  if (!centerCoords) {
    const lat = config.lat ?? config.latitude;
    const lng = config.lng ?? config.long ?? config.longitude ?? config.lon;
    if (lat !== undefined && lng !== undefined) {
      centerCoords = parseLatLng([lat, lng]);
    }
  }

  const zoom = Number(config.zoom ?? config.defaultZoom ?? (centerCoords ? 13 : 2));
  const minZoom = Number(config.minZoom ?? 1);
  const maxZoom = Number(config.maxZoom ?? 19);

  // Fallback center if none provided
  const initialCenter = centerCoords || [0, 0];

  const supportsCanvas = typeof document !== 'undefined' &&
    (typeof createEl === 'function'
      ? !!createEl('canvas')?.getContext?.('2d')
      : typeof mapDiv.createEl === 'function'
      ? !!mapDiv.createEl('canvas')?.getContext?.('2d')
      : !!createEl('canvas')?.getContext?.('2d'));

  let map: any;
  try {
    map = L.map(mapDiv, {
      center: initialCenter,
      zoom,
      minZoom,
      maxZoom,
      preferCanvas: supportsCanvas,
    });
  } catch (err) {
    renderError(`Leaflet Map Initialization Error: ${err}`, container);
    return;
  }

  // Tile layer configuration
  const tileUrl = config.tileServer ?? config.url ?? config.tile ?? config.tiles ?? 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
  const attribution = config.attribution ?? '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';
  const subdomains = config.subdomains ?? 'abc';

  L.tileLayer(tileUrl, {
    attribution,
    subdomains,
    maxZoom,
    minZoom,
    crossOrigin: true,
    updateWhenIdle: false,
    updateWhenZooming: true,
    keepBuffer: 2,
  }).addTo(map);

  // Performance optimization: Compute bounding box extents in O(1) space with scalar min/max accumulators
  // rather than accumulating thousands of coordinate tuple arrays in an allCoords heap array, and pass
  // only the 2 corner points to L.latLngBounds.
  let minLat = Infinity;
  let maxLat = -Infinity;
  let minLng = Infinity;
  let maxLng = -Infinity;
  let hasCoords = false;

  const updateBounds = (p: [number, number]) => {
    const lat = p[0];
    const lng = p[1];
    if (lat < minLat) minLat = lat;
    if (lat > maxLat) maxLat = lat;
    if (lng < minLng) minLng = lng;
    if (lng > maxLng) maxLng = lng;
    hasCoords = true;
  };

  if (centerCoords) {
    updateBounds(centerCoords);
  }

  // Handle Markers
  const rawMarkers = config.markers ?? config.marker;
  const markerList: any[] = Array.isArray(rawMarkers) ? rawMarkers : rawMarkers ? [rawMarkers] : [];

  markerList.forEach((m) => {
    let coords: [number, number] | null = null;
    let popupText: string | undefined = undefined;
    let titleText: string | undefined = undefined;
    let tooltipText: string | undefined = undefined;
    let color: string | undefined = undefined;

    if (Array.isArray(m)) {
      coords = parseLatLng([m[0], m[1]]);
      popupText = m[2];
      titleText = m[3];
    } else if (typeof m === 'object' && m !== null) {
      coords = parseLatLng(m);
      popupText = m.popup;
      titleText = m.title;
      tooltipText = m.tooltip;
      color = m.color;
    }

    if (coords) {
      updateBounds(coords);
      const icon = createSvgIcon(L, color);
      const markerOpts: any = { icon };
      if (titleText) markerOpts.title = titleText;

      const marker = L.marker(coords, markerOpts).addTo(map);

      if (popupText) {
        marker.bindPopup(String(popupText));
      }
      if (tooltipText) {
        marker.bindTooltip(String(tooltipText));
      }
    }
  });

  // Handle Lines / Polylines
  const rawLines = config.lines ?? config.polylines ?? config.line;
  const linesList: any[] = Array.isArray(rawLines) ? rawLines : rawLines ? [rawLines] : [];

  linesList.forEach((line) => {
    const pts: [number, number][] = [];
    let color = '#2563eb';
    let weight = 3;
    let popupText: string | undefined = undefined;

    // Performance optimization: Single-pass coordinate parsing and bounds accumulation.
    // Eliminates intermediate map/filter array object allocations per line feature.
    let rawPts: any[] = [];
    if (Array.isArray(line)) {
      rawPts = line;
    } else if (typeof line === 'object' && line !== null) {
      rawPts = line.points ?? line.coordinates ?? line.path;
      if (!Array.isArray(rawPts)) rawPts = [];
      color = line.color ?? color;
      weight = Number(line.weight ?? weight);
      popupText = line.popup;
    }

    for (let i = 0; i < rawPts.length; i++) {
      const pt = parseLatLng(rawPts[i]);
      if (pt) {
        pts.push(pt);
        updateBounds(pt);
      }
    }

    if (pts.length > 0) {
      const polyline = L.polyline(pts, { color, weight }).addTo(map);
      if (popupText) {
        polyline.bindPopup(String(popupText));
      }
    }
  });

  // Handle Polygons
  const rawPolygons = config.polygons ?? config.polygon;
  const polygonsList: any[] = Array.isArray(rawPolygons) ? rawPolygons : rawPolygons ? [rawPolygons] : [];

  polygonsList.forEach((poly) => {
    const pts: [number, number][] = [];
    let color = '#2563eb';
    let fillColor = '#3b82f6';
    let fillOpacity = 0.4;
    let popupText: string | undefined = undefined;

    // Performance optimization: Single-pass coordinate parsing and bounds accumulation.
    // Eliminates intermediate map/filter array object allocations per polygon feature.
    let rawPts: any[] = [];
    if (Array.isArray(poly)) {
      rawPts = poly;
    } else if (typeof poly === 'object' && poly !== null) {
      rawPts = poly.points ?? poly.coordinates ?? poly.path;
      if (!Array.isArray(rawPts)) rawPts = [];
      color = poly.color ?? color;
      fillColor = poly.fillColor ?? fillColor;
      fillOpacity = Number(poly.fillOpacity ?? fillOpacity);
      popupText = poly.popup;
    }

    for (let i = 0; i < rawPts.length; i++) {
      const pt = parseLatLng(rawPts[i]);
      if (pt) {
        pts.push(pt);
        updateBounds(pt);
      }
    }

    if (pts.length > 0) {
      const polygon = L.polygon(pts, { color, fillColor, fillOpacity }).addTo(map);
      if (popupText) {
        polygon.bindPopup(String(popupText));
      }
    }
  });

  // Handle Circles
  const rawCircles = config.circles ?? config.circle;
  const circlesList: any[] = Array.isArray(rawCircles) ? rawCircles : rawCircles ? [rawCircles] : [];

  circlesList.forEach((c) => {
    let coords: [number, number] | null = null;
    let radius = 100;
    let color = '#2563eb';
    let fillColor = '#3b82f6';
    let fillOpacity = 0.4;
    let popupText: string | undefined = undefined;

    if (Array.isArray(c)) {
      coords = parseLatLng([c[0], c[1]]);
      radius = Number(c[2] ?? radius);
      popupText = c[3];
    } else if (typeof c === 'object' && c !== null) {
      coords = parseLatLng(c);
      radius = Number(c.radius ?? radius);
      color = c.color ?? color;
      fillColor = c.fillColor ?? fillColor;
      fillOpacity = Number(c.fillOpacity ?? fillOpacity);
      popupText = c.popup;
    }

    if (coords) {
      updateBounds(coords);
      const circle = L.circle(coords, { radius, color, fillColor, fillOpacity }).addTo(map);
      if (popupText) {
        circle.bindPopup(String(popupText));
      }
    }
  });

  // Handle GeoJSON
  const geojson = config.geojson ?? config.geoJson;
  if (geojson) {
    try {
      const geoObj = typeof geojson === 'string' ? JSON.parse(geojson) : geojson;
      const geoLayer = L.geoJSON(geoObj, {
        onEachFeature: (feature: any, layer: any) => {
          if (feature?.properties) {
            const popup = feature.properties.popup ?? feature.properties.name ?? feature.properties.title;
            if (popup) layer.bindPopup(String(popup));
          }
        },
      }).addTo(map);

      try {
        const bounds = geoLayer.getBounds();
        if (bounds && bounds.isValid && bounds.isValid()) {
          updateBounds([bounds.getSouth(), bounds.getWest()]);
          updateBounds([bounds.getNorth(), bounds.getEast()]);
        }
      } catch {
        // ignore bounds invalid check if mock/empty
      }
    } catch (err) {
      console.warn('GeoJSON parsing failed:', err);
    }
  }

  // Auto fit bounds if fitBounds is true, or if center wasn't explicitly provided but markers/elements exist
  if (config.fitBounds === true || (!centerCoords && config.center === undefined && hasCoords)) {
    if (hasCoords) {
      const bounds = L.latLngBounds([[minLat, minLng], [maxLat, maxLng]]);
      if (bounds && bounds.isValid ? bounds.isValid() : true) {
        map.fitBounds(bounds, { padding: [20, 20] });
      }
    }
  }

  // Multi-stage invalidation to ensure Leaflet calculates correct dimensions and loads visible tiles
  let isCleanedUp = false;
  let resizeObserver: ResizeObserver | null = null;
  let intersectionObserver: IntersectionObserver | null = null;
  const timeoutIds: any[] = [];

  const triggerInvalidate = () => {
    if (isCleanedUp || !map || typeof map.invalidateSize !== 'function') return;
    map.invalidateSize({ debounceMoveend: true });
  };

  // Immediate and staggered frame/timeout passes to adapt as container is inserted and styled
  if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
    window.requestAnimationFrame(triggerInvalidate);
  }

  // Staggered timeouts help catch layout transitions in Obsidian reading view
  [0, 50, 150, 300, 600].forEach((delay) => {
    const tid = window.setTimeout(triggerInvalidate, delay);
    timeoutIds.push(tid);
  });

  // Track size changes without prematurely disconnecting when mapDiv is temporarily unattached during initial render
  if (typeof ResizeObserver !== 'undefined') {
    resizeObserver = new ResizeObserver((entries) => {
      if (isCleanedUp) return;
      for (const entry of entries) {
        if (entry.contentRect && (entry.contentRect.width > 0 || entry.contentRect.height > 0)) {
          triggerInvalidate();
        }
      }
    });
    resizeObserver.observe(mapDiv);
  }

  // Detect when map becomes visible in Obsidian reading view viewport
  if (typeof IntersectionObserver !== 'undefined') {
    intersectionObserver = new IntersectionObserver((entries) => {
      if (isCleanedUp) return;
      for (const entry of entries) {
        if (entry.isIntersecting) {
          triggerInvalidate();
        }
      }
    });
    intersectionObserver.observe(mapDiv);
  }

  // Integrate with Obsidian's MarkdownRenderChild lifecycle if available
  const obsidian = require('obsidian');
  const MarkdownRenderChildClass = obsidian?.MarkdownRenderChild;

  const cleanup = () => {
    if (isCleanedUp) return;
    isCleanedUp = true;
    timeoutIds.forEach((id) => window.clearTimeout(id));
    timeoutIds.length = 0;
    if (resizeObserver) {
      resizeObserver.disconnect();
      resizeObserver = null;
    }
    if (intersectionObserver) {
      intersectionObserver.disconnect();
      intersectionObserver = null;
    }
    try {
      if (map && typeof map.remove === 'function') {
        map.remove();
      }
    } catch {
      // ignore
    }
  };

  if (ctx && typeof ctx.addChild === 'function' && MarkdownRenderChildClass) {
    const child = new MarkdownRenderChildClass(container);
    child.onload = () => {
      triggerInvalidate();
      // Delay check in case layout settling occurs right after onload
      window.setTimeout(triggerInvalidate, 100);
    };
    child.onunload = cleanup;
    ctx.addChild(child);
  }
}

import { App, MarkdownView, Modal } from "obsidian";
import type Renderer from "../chartRenderer"
import type { ChartPluginSettings } from "../constants/settingsConstants";

export class CreationHelperModal extends Modal {
	view: MarkdownView;
	settings: ChartPluginSettings;
	renderer: Renderer;
	component: any = null;

	constructor(app: App, view: MarkdownView, settings: ChartPluginSettings, renderer: Renderer) {
		super(app);
		this.settings = settings;
		this.view = view;
		this.renderer = renderer;
	}

	onOpen() {
		const { contentEl, view, renderer} = this;
		contentEl.empty();
		const { mount } = require("svelte");
		const HelperModal = require('./HelperModal.svelte').default ?? require('./HelperModal.svelte');
		this.component = mount(HelperModal, {
			target: contentEl,
			props: {
				editor: view.editor,
				renderer,
				onclose: () => this.close()
			}
		});
	}

	onClose() {
		if (this.component) {
			const { unmount } = require("svelte");
			unmount(this.component);
			this.component = null;
		}
		const { contentEl } = this;
		contentEl.empty();
	}
}

import {
  DEFAULT_SETTINGS,
} from './../constants/settingsConstants';
import {
  App,
  PluginSettingTab,
  Setting,
  type SettingDefinitionItem,
  type SettingGroupItem,
} from 'obsidian';
import type ChartPlugin from '../main';

let _Picker: any = null;
function getPicker(): any {
  if (!_Picker) {
    const loaded = require('vanilla-picker');
    _Picker = loaded.default ?? loaded;
  }
  return _Picker;
}

export class ChartSettingTab extends PluginSettingTab {
  plugin: ChartPlugin;

  constructor(app: App, plugin: ChartPlugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  refreshTab(): void {
    this.update();
  }

  getSettingDefinitions(): SettingDefinitionItem[] {
    const definitions: SettingDefinitionItem[] = [
      {
        name: 'Show button in context menu',
        desc: 'If enabled, you will see a button in your editor context menu to open the chart creator.',
        control: {
          type: 'toggle',
          key: 'contextMenu',
          defaultValue: this.plugin.settings.contextMenu,
        },
      },
      {
        name: 'Enable theme colors',
        desc: 'If your Obsidian theme (or snippet) provides colors you can use them instead.',
        control: {
          type: 'toggle',
          key: 'themeable',
          defaultValue: this.plugin.settings.themeable,
        },
      },
    ];

    if (!this.plugin.settings.themeable) {
      const descFrag = createFragment();
      const descP = descFrag.createEl('p', { cls: 'setting-item-description' });
      descP.append(
        'Set the Colors for your Charts. This will set the border Color and the inner Color will be the same, but with less opacity. This ensures better compatibility with Dark and Light Mode. ',
        'You can use any ',
        descP.createEl('a', {
          href: 'https://www.w3schools.com/cssref/css_colors.asp',
          text: 'valid CSS Color.',
        })
      );

      const colorItems: SettingGroupItem[] = [];

      this.plugin.settings.colors.forEach((color, idx) => {
        colorItems.push({
          name: `Color #${idx + 1}`,
          desc: 'This will be the border Color used in the Charts you create.',
          render: (setting: Setting) => {
            const nameEl = createFragment();
            nameEl.createSpan({ text: '●', attr: { style: `color: ${color}` } });
            nameEl.appendText(` Color #${idx + 1}`);
            setting.setName(nameEl);

            setting.addButton((btn) => {
              btn.setButtonText('Change Color');
              const Picker = getPicker();
              new Picker({
                parent: btn.buttonEl,
                onDone: async (col: any) => {
                  this.plugin.settings.colors[idx] = col.hex;
                  await this.plugin.saveSettings();
                  this.refreshTab();
                },
                popup: 'left',
                color: color,
                alpha: false,
              });
            });

            setting.addExtraButton((btn) => {
              btn
                .setIcon('trash')
                .setTooltip('Remove')
                .onClick(async () => {
                  this.plugin.settings.colors.remove(color);
                  await this.plugin.saveSettings();
                  this.refreshTab();
                });
              if (this.plugin.settings.colors.length === 1) {
                btn.setDisabled(true);
              }
            });

            setting.addExtraButton((btn) => {
              btn
                .setIcon('reset')
                .setTooltip('Reset to default')
                .onClick(async () => {
                  this.plugin.settings.colors[idx] =
                    DEFAULT_SETTINGS.colors[idx] ?? '#ffffff';
                  await this.plugin.saveSettings();
                  this.refreshTab();
                });
            });
          },
        });
      });

      colorItems.push({
        name: 'Add Color',
        action: () => {
          this.addColor().catch((error: unknown) => {
            console.error('Failed to add chart color', error);
          });
        },
      });

      definitions.push({
        type: 'group',
        heading: 'Colors',
        desc: descFrag,
        items: colorItems,
      });
    }

    return definitions;
  }

  getControlValue(key: string): unknown {
    return (this.plugin.settings as any)[key];
  }

  async setControlValue(key: string, value: unknown): Promise<void> {
    (this.plugin.settings as any)[key] = value;
    await this.plugin.saveSettings();
    if (key === 'themeable') {
      this.refreshTab();
    }
  }

  private async addColor(): Promise<void> {
    this.plugin.settings.colors.push('#ffffff');
    await this.plugin.saveSettings();
    this.refreshTab();
  }
}

